/** Tests for the externally observable type extraction behavior of {@link TypeExtractor}. */
class TypeExtractorTests {

    // ------------------------------------------------------------------------
    //  Basic, array, collection, and POJO extraction
    // ------------------------------------------------------------------------

    @Test
    void extractsBasicTypes() {
        assertThat(TypeExtractor.createTypeInfo(String.class))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
        assertThat(TypeExtractor.createTypeInfo(Integer.class))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
        assertThat(TypeExtractor.createTypeInfo(Boolean.TYPE))
                .isEqualTo(BasicTypeInfo.BOOLEAN_TYPE_INFO);
        assertThat(TypeExtractor.getForClass(Long.class)).isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
    }

    @Test
    void extractsPrimitiveAndObjectArrays() {
        assertThat(TypeExtractor.createTypeInfo(int[].class))
                .isEqualTo(PrimitiveArrayTypeInfo.INT_PRIMITIVE_ARRAY_TYPE_INFO);
        assertThat(TypeExtractor.createTypeInfo(String[].class))
                .isEqualTo(BasicArrayTypeInfo.STRING_ARRAY_TYPE_INFO);

        TypeInformation<?> nestedArray = TypeExtractor.createTypeInfo(String[][].class);
        assertThat(nestedArray).isInstanceOf(ObjectArrayTypeInfo.class);
        assertThat(nestedArray.getTypeClass()).isEqualTo(String[][].class);
        assertThat(((ObjectArrayTypeInfo<?, ?>) nestedArray).getComponentInfo())
                .isEqualTo(BasicArrayTypeInfo.STRING_ARRAY_TYPE_INFO);

        TypeInformation<?> pojoArray = TypeExtractor.createTypeInfo(PublicPojo[].class);
        assertThat(pojoArray).isInstanceOf(ObjectArrayTypeInfo.class);
        assertThat(((ObjectArrayTypeInfo<?, ?>) pojoArray).getComponentInfo())
                .isInstanceOf(PojoTypeInfo.class);
    }

    @Test
    void extractsParameterizedCollectionInterfaces() throws Exception {
        TypeInformation<?> listInfo =
                TypeExtractor.createTypeInfo(
                        CollectionHolder.class.getField("list").getGenericType());
        assertThat(listInfo).isInstanceOf(ListTypeInfo.class);
        assertThat(((ListTypeInfo<?>) listInfo).getElementTypeInfo())
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);

        TypeInformation<?> mapInfo =
                TypeExtractor.createTypeInfo(
                        CollectionHolder.class.getField("map").getGenericType());
        assertThat(mapInfo).isInstanceOf(MapTypeInfo.class);
        assertThat(((MapTypeInfo<?, ?>) mapInfo).getKeyTypeInfo())
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
        assertThat(((MapTypeInfo<?, ?>) mapInfo).getValueTypeInfo())
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);

        TypeInformation<?> setInfo =
                TypeExtractor.createTypeInfo(
                        CollectionHolder.class.getField("set").getGenericType());
        assertThat(setInfo).isInstanceOf(SetTypeInfo.class);
        assertThat(((SetTypeInfo<?>) setInfo).getElementTypeInfo())
                .isEqualTo(BasicTypeInfo.DOUBLE_TYPE_INFO);
    }

    @Test
    void extractsPublicFieldPojoIncludingNestedFieldTypes() {
        TypeInformation<PublicPojo> info = TypeExtractor.createTypeInfo(PublicPojo.class);

        assertThat(info).isInstanceOf(PojoTypeInfo.class);
        PojoTypeInfo<PublicPojo> pojo = (PojoTypeInfo<PublicPojo>) info;
        assertThat(pojo.getTypeClass()).isEqualTo(PublicPojo.class);
        assertThat(pojo.getArity()).isEqualTo(3);
        assertThat(pojo.getFieldNames()).containsExactly("age", "name", "tags");
        assertThat(pojo.getTypeAt("name")).isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
        assertThat(pojo.getTypeAt("age")).isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
        assertThat(pojo.getTypeAt("tags")).isInstanceOf(ListTypeInfo.class);
    }

    @Test
    void extractsBeanStylePojoWithPrivateFieldAndAccessors() {
        TypeInformation<BeanPojo> info = TypeExtractor.createTypeInfo(BeanPojo.class);

        assertThat(info).isInstanceOf(PojoTypeInfo.class);
        assertThat(info.getArity()).isEqualTo(1);
        assertThat(((PojoTypeInfo<?>) info).getFieldNames()).containsExactly("count");
        assertThat(((PojoTypeInfo<?>) info).getTypeAt("count"))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
    }

    @Test
    void extractsInheritedPojoFieldsAndHonorsTransientAndStaticFields() {
        TypeInformation<ChildPojo> info = TypeExtractor.createTypeInfo(ChildPojo.class);

        assertThat(info).isInstanceOf(PojoTypeInfo.class);
        assertThat(((PojoTypeInfo<?>) info).getFieldNames())
                .containsExactly("child", "parent", "visible");
        assertThat(((PojoTypeInfo<?>) info).getTypeAt("parent"))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
    }

    @Test
    void fallsBackToGenericTypeForNonPojoClasses() {
        assertThat(TypeExtractor.createTypeInfo(InvalidPojo.class))
                .isInstanceOf(GenericTypeInfo.class);
        assertThat(TypeExtractor.createTypeInfo(NoDefaultConstructorPojo.class))
                .isInstanceOf(GenericTypeInfo.class);
        assertThat(TypeExtractor.createTypeInfo(EmptyPojo.class))
                .isInstanceOf(GenericTypeInfo.class);
        assertThat(TypeExtractor.createTypeInfo(NonPublicPojo.class))
                .isInstanceOf(GenericTypeInfo.class);
        assertThat(TypeExtractor.createTypeInfo(CustomSerializationPojo.class))
                .isInstanceOf(GenericTypeInfo.class);
    }

    @Test
    void extractsEnumsAndFlinkValueTypes() {
        assertThat(TypeExtractor.createTypeInfo(TestEnum.class)).isInstanceOf(EnumTypeInfo.class);
        assertThat(TypeExtractor.createTypeInfo(TestEnum.class).getTypeClass())
                .isEqualTo(TestEnum.class);

        TypeInformation<TestValue> valueInfo = TypeExtractor.createTypeInfo(TestValue.class);
        assertThat(valueInfo).isInstanceOf(ValueTypeInfo.class);
        assertThat(valueInfo.getTypeClass()).isEqualTo(TestValue.class);
    }

    @Test
    void handlesObjectAndClassAsGenericTypes() {
        assertThat(TypeExtractor.createTypeInfo(Object.class)).isInstanceOf(GenericTypeInfo.class);
        assertThat(TypeExtractor.createTypeInfo(Class.class)).isInstanceOf(GenericTypeInfo.class);
    }

    @Test
    void rejectsRawTupleClassesButAcceptsTupleZero() {
        assertThatThrownBy(() -> TypeExtractor.createTypeInfo(Tuple.class))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("Usage of class Tuple");

        assertThatThrownBy(() -> TypeExtractor.getForClass(Tuple2.class))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("cannot be done based on the class");

        TypeInformation<Tuple0> tuple0 = TypeExtractor.getForClass(Tuple0.class);
        assertThat(tuple0).isInstanceOf(TupleTypeInfo.class);
        assertThat(tuple0.getTypeClass()).isEqualTo(Tuple0.class);
        assertThat(tuple0.getArity()).isZero();
    }

    // ------------------------------------------------------------------------
    //  Function return type extraction
    // ------------------------------------------------------------------------

    @Test
    void extractsReturnTypesOfUnaryFunctionFamilies() {
        TypeInformation<String> input = BasicTypeInfo.STRING_TYPE_INFO;

        assertThat(TypeExtractor.getMapReturnTypes(new StringToIntegerMap(), input))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
        assertThat(TypeExtractor.getFlatMapReturnTypes(new StringToLongFlatMap(), input))
                .isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
        assertThat(
                        TypeExtractor.getMapPartitionReturnTypes(
                                new StringToDoubleMapPartition(), input))
                .isEqualTo(BasicTypeInfo.DOUBLE_TYPE_INFO);
        assertThat(TypeExtractor.getGroupReduceReturnTypes(new StringToFloatGroupReduce(), input))
                .isEqualTo(BasicTypeInfo.FLOAT_TYPE_INFO);
        assertThat(TypeExtractor.getGroupCombineReturnTypes(new StringToByteGroupCombine(), input))
                .isEqualTo(BasicTypeInfo.BYTE_TYPE_INFO);
    }

    @Test
    void extractsAggregateAccumulatorAndResultTypes() {
        SumAggregate aggregate = new SumAggregate();

        assertThat(
                        TypeExtractor.getAggregateFunctionAccumulatorType(
                                aggregate, BasicTypeInfo.INT_TYPE_INFO, "sum", false))
                .isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
        assertThat(
                        TypeExtractor.getAggregateFunctionReturnType(
                                aggregate, BasicTypeInfo.INT_TYPE_INFO, "sum", false))
                .isEqualTo(BasicTypeInfo.DOUBLE_TYPE_INFO);
    }

    @Test
    void extractsReturnTypesOfBinaryFunctionFamilies() {
        TypeInformation<String> left = BasicTypeInfo.STRING_TYPE_INFO;
        TypeInformation<Integer> right = BasicTypeInfo.INT_TYPE_INFO;

        assertThat(TypeExtractor.getJoinReturnTypes(new StringIntegerToLongJoin(), left, right))
                .isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
        assertThat(
                        TypeExtractor.getFlatJoinReturnTypes(
                                new StringIntegerToDoubleFlatJoin(), left, right))
                .isEqualTo(BasicTypeInfo.DOUBLE_TYPE_INFO);
        assertThat(
                        TypeExtractor.getCoGroupReturnTypes(
                                new StringIntegerToFloatCoGroup(), left, right))
                .isEqualTo(BasicTypeInfo.FLOAT_TYPE_INFO);
        assertThat(TypeExtractor.getCrossReturnTypes(new StringIntegerToShortCross(), left, right))
                .isEqualTo(BasicTypeInfo.SHORT_TYPE_INFO);
    }

    @Test
    void extractsKeySelectorAndPartitionerTypes() {
        assertThat(
                        TypeExtractor.getKeySelectorTypes(
                                new StringToLongKeySelector(), BasicTypeInfo.STRING_TYPE_INFO))
                .isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
        assertThat(TypeExtractor.getPartitionerTypes(new StringPartitioner()))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
    }

    @Test
    void extractsComplexGenericReturnType() {
        TypeInformation<Tuple2<String, Integer>> info =
                TypeExtractor.getMapReturnTypes(
                        new TupleReturningMap(), BasicTypeInfo.STRING_TYPE_INFO);

        assertThat(info).isInstanceOf(TupleTypeInfo.class);
        assertThat(info.getTypeClass()).isEqualTo(Tuple2.class);
        assertThat(info.getArity()).isEqualTo(2);
        assertThat(((TupleTypeInfo<?>) info).getTypeAt(0))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
        assertThat(((TupleTypeInfo<?>) info).getTypeAt(1)).isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
    }

    @Test
    void derivesGenericReturnTypeFromInputTypeInformation() {
        TypeInformation<String> info =
                TypeExtractor.getMapReturnTypes(
                        new IdentityMap<String>(), BasicTypeInfo.STRING_TYPE_INFO);

        assertThat(info).isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
    }

    @Test
    void materializesGenericReturnTypeThroughClassHierarchy() {
        TypeInformation<String> info =
                TypeExtractor.getMapReturnTypes(
                        new StringIdentityMap(), BasicTypeInfo.STRING_TYPE_INFO);

        assertThat(info).isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
    }

    @Test
    @SuppressWarnings({"rawtypes", "unchecked"})
    void infersGenericReturnTypesFromTupleArrayAndPojoInputs() throws Exception {
        TypeInformation<Tuple2<String, Integer>> tupleInput =
                TypeExtractor.getForObject(new Tuple2<>("hello", 1));
        assertThat(TypeExtractor.getMapReturnTypes(new FirstOfTupleMap<String>(), tupleInput))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);

        assertThat(
                        TypeExtractor.getMapReturnTypes(
                                new FirstOfArrayMap<String>(),
                                BasicArrayTypeInfo.STRING_ARRAY_TYPE_INFO))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);

        TypeInformation<PojoValue<String>> pojoInput =
                (TypeInformation)
                        TypeExtractor.createTypeInfo(
                                GenericHolder.class.getField("pojo").getGenericType());
        assertThat(TypeExtractor.getMapReturnTypes(new ValueOfPojoMap<String>(), pojoInput))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
    }

    @Test
    void extractsGenericArrayReturnTypesAndReportsUnboundTypeVariables() {
        TypeInformation<?> arrayInfo =
                TypeExtractor.getMapReturnTypes(
                        new ArrayReturningMap<String>(), BasicTypeInfo.STRING_TYPE_INFO);

        assertThat(arrayInfo).isInstanceOf(ObjectArrayTypeInfo.class);
        assertThat(((ObjectArrayTypeInfo<?, ?>) arrayInfo).getComponentInfo())
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getMapReturnTypes(
                                        new UnboundGenericMap<String>(), null))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("could not be determined");

        TypeInformation<?> missing =
                TypeExtractor.getMapReturnTypes(
                        new UnboundGenericMap<String>(), null, "unbound", true);
        assertThat(missing).isInstanceOf(MissingTypeInfo.class);
        assertThat(((MissingTypeInfo) missing).getFunctionName()).isEqualTo("unbound");
    }

    @Test
    void extractsLambdaReturnTypesWhenTypesCanBeInferred() {
        MapFunction<String, Integer> mapper = value -> value.length();
        FlatMapFunction<String, Long> flatMapper =
                (value, out) -> out.collect((long) value.length());
        JoinFunction<String, Integer, Double> joiner =
                (first, second) -> (double) (first.length() + second);

        assertThat(TypeExtractor.getMapReturnTypes(mapper, BasicTypeInfo.STRING_TYPE_INFO))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
        assertThat(
                        TypeExtractor.getJoinReturnTypes(
                                joiner,
                                BasicTypeInfo.STRING_TYPE_INFO,
                                BasicTypeInfo.INT_TYPE_INFO))
                .isEqualTo(BasicTypeInfo.DOUBLE_TYPE_INFO);

        // The compiler does not retain enough information about the Collector type parameter of
        // a flat-map lambda. This is reported instead of returning a wrong type.
        assertThatThrownBy(
                        () ->
                                TypeExtractor.getFlatMapReturnTypes(
                                        flatMapper, BasicTypeInfo.STRING_TYPE_INFO))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("generic type parameters of 'Collector' are missing");

        TypeInformation<?> missing =
                TypeExtractor.getFlatMapReturnTypes(
                        flatMapper, BasicTypeInfo.STRING_TYPE_INFO, "flatLambda", true);
        assertThat(missing).isInstanceOf(MissingTypeInfo.class);
        assertThat(((MissingTypeInfo) missing).getFunctionName()).isEqualTo("flatLambda");
    }

    @Test
    void resultTypeQueryableTakesPrecedenceOverGenericExtraction() {
        QueryableMap map = new QueryableMap();
        assertThat(TypeExtractor.getMapReturnTypes(map, BasicTypeInfo.STRING_TYPE_INFO))
                .isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
        assertThat(TypeExtractor.createTypeInfo(map, MapFunction.class, QueryableMap.class, 1))
                .isEqualTo(BasicTypeInfo.LONG_TYPE_INFO);
    }

    @Test
    void createTypeInfoClassOverloadsUseBaseClassAndInputTypes() {
        assertThat(
                        TypeExtractor.createTypeInfo(
                                MapFunction.class, StringToIntegerMap.class, 1, null, null))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);

        assertThat(
                        TypeExtractor.createTypeInfo(
                                MapFunction.class,
                                IdentityMap.class,
                                1,
                                BasicTypeInfo.STRING_TYPE_INFO,
                                null))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
    }

    @Test
    void returnsMissingTypeInfoWhenAllowed() {
        TypeInformation<?> missing =
                TypeExtractor.getMapReturnTypes(new RawMap(), null, "anonymousRawMap", true);

        assertThat(missing).isInstanceOf(MissingTypeInfo.class);
        assertThat(((MissingTypeInfo) missing).getFunctionName()).isEqualTo("anonymousRawMap");
        assertThat(((MissingTypeInfo) missing).getTypeException())
                .isInstanceOf(InvalidTypesException.class);
    }

    @Test
    void rejectsMissingTypeInformationWhenNotAllowed() {
        assertThatThrownBy(
                        () -> TypeExtractor.getMapReturnTypes(new RawMap(), null, "rawMap", false))
                .isInstanceOf(InvalidTypesException.class);
    }

    @Test
    @SuppressWarnings({"rawtypes", "unchecked"})
    void rejectsInputTypeMismatches() {
        assertThatThrownBy(
                        () ->
                                TypeExtractor.getMapReturnTypes(
                                        (MapFunction) new StringToIntegerMap(),
                                        (TypeInformation) BasicTypeInfo.INT_TYPE_INFO))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("Input mismatch");

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getJoinReturnTypes(
                                        (JoinFunction) new StringIntegerToLongJoin(),
                                        (TypeInformation) BasicTypeInfo.STRING_TYPE_INFO,
                                        (TypeInformation) BasicTypeInfo.LONG_TYPE_INFO))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("Input mismatch");

        TypeInformation<?> missing =
                TypeExtractor.getJoinReturnTypes(
                        (JoinFunction) new StringIntegerToLongJoin(),
                        (TypeInformation) BasicTypeInfo.STRING_TYPE_INFO,
                        (TypeInformation) BasicTypeInfo.LONG_TYPE_INFO,
                        "badJoin",
                        true);
        assertThat(missing).isInstanceOf(MissingTypeInfo.class);
        assertThat(((MissingTypeInfo) missing).getFunctionName()).isEqualTo("badJoin");
    }

    @Test
    void validatesUnaryOperatorArguments() {
        MapFunction<String, Integer> function = new StringToIntegerMap();

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getUnaryOperatorReturnType(
                                        function,
                                        MapFunction.class,
                                        -1,
                                        1,
                                        TypeExtractor.NO_INDEX,
                                        BasicTypeInfo.STRING_TYPE_INFO,
                                        null,
                                        false))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Input type argument index");

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getUnaryOperatorReturnType(
                                        function,
                                        MapFunction.class,
                                        0,
                                        -1,
                                        TypeExtractor.NO_INDEX,
                                        BasicTypeInfo.STRING_TYPE_INFO,
                                        null,
                                        false))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Output type argument index");

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getUnaryOperatorReturnType(
                                        function,
                                        MapFunction.class,
                                        0,
                                        1,
                                        null,
                                        BasicTypeInfo.STRING_TYPE_INFO,
                                        null,
                                        false))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Indices for output type arguments");
    }

    @Test
    void validatesBinaryOperatorArguments() {
        JoinFunction<String, Integer, Long> function = new StringIntegerToLongJoin();

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getBinaryOperatorReturnType(
                                        function,
                                        JoinFunction.class,
                                        -1,
                                        1,
                                        2,
                                        TypeExtractor.NO_INDEX,
                                        BasicTypeInfo.STRING_TYPE_INFO,
                                        BasicTypeInfo.INT_TYPE_INFO,
                                        null,
                                        false))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Input 1 type argument index");

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getBinaryOperatorReturnType(
                                        function,
                                        JoinFunction.class,
                                        0,
                                        -1,
                                        2,
                                        TypeExtractor.NO_INDEX,
                                        BasicTypeInfo.STRING_TYPE_INFO,
                                        BasicTypeInfo.INT_TYPE_INFO,
                                        null,
                                        false))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Input 2 type argument index");

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getBinaryOperatorReturnType(
                                        function,
                                        JoinFunction.class,
                                        0,
                                        1,
                                        -1,
                                        TypeExtractor.NO_INDEX,
                                        BasicTypeInfo.STRING_TYPE_INFO,
                                        BasicTypeInfo.INT_TYPE_INFO,
                                        null,
                                        false))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Output type argument index");

        assertThatThrownBy(
                        () ->
                                TypeExtractor.getBinaryOperatorReturnType(
                                        function,
                                        JoinFunction.class,
                                        0,
                                        1,
                                        2,
                                        null,
                                        BasicTypeInfo.STRING_TYPE_INFO,
                                        BasicTypeInfo.INT_TYPE_INFO,
                                        null,
                                        false))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("Indices for output type arguments");
    }

    // ------------------------------------------------------------------------
    //  Input formats and parameter reflection
    // ------------------------------------------------------------------------

    @Test
    void extractsInputFormatTypeAndUsesResultTypeQueryable() {
        assertThat(TypeExtractor.getInputFormatTypes(new StringInputFormat()))
                .isEqualTo(BasicTypeInfo.STRING_TYPE_INFO);
        assertThat(TypeExtractor.getInputFormatTypes(new QueryableInputFormat()))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
    }

    @Test
    void getParameterTypeFindsTypeArgumentsInInterfacesAndReportsMissingOnes() {
        assertThat(TypeExtractor.getParameterType(MapFunction.class, StringToIntegerMap.class, 0))
                .isEqualTo(String.class);
        assertThat(TypeExtractor.getParameterType(MapFunction.class, StringToIntegerMap.class, 1))
                .isEqualTo(Integer.class);

        assertThatThrownBy(() -> TypeExtractor.getParameterType(MapFunction.class, String.class, 0))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("could not be inferred");
    }

    // ------------------------------------------------------------------------
    //  Factories and registry
    // ------------------------------------------------------------------------

    @Test
    void usesAnnotatedTypeFactoryAndReturnsNullForUnannotatedTypes() throws Exception {
        assertThat(TypeExtractor.getTypeInfoFactory(AnnotatedPojo.class))
                .isInstanceOf(AnnotatedPojoFactory.class);
        assertThat(TypeExtractor.getTypeInfoFactory(PublicPojo.class)).isNull();
        assertThat(TypeExtractor.getTypeInfoFactory(PublicPojo.class.getField("name"))).isNull();

        TypeInformation<AnnotatedPojo> info = TypeExtractor.createTypeInfo(AnnotatedPojo.class);
        assertThat(info).isInstanceOf(GenericTypeInfo.class);
        assertThat(info.getTypeClass()).isEqualTo(AnnotatedPojo.class);
    }

    @Test
    void usesAnnotatedFieldFactoryDuringPojoExtraction() throws Exception {
        Field field = FieldAnnotatedPojo.class.getField("value");
        assertThat(TypeExtractor.getTypeInfoFactory(field)).isInstanceOf(FieldValueFactory.class);

        TypeInformation<FieldAnnotatedPojo> info =
                TypeExtractor.createTypeInfo(FieldAnnotatedPojo.class);
        assertThat(info).isInstanceOf(PojoTypeInfo.class);
        TypeInformation<?> fieldInfo = ((PojoTypeInfo<?>) info).getTypeAt("value");
        assertThat(fieldInfo).isInstanceOf(GenericTypeInfo.class);
        assertThat(fieldInfo.getTypeClass()).isEqualTo(FieldValue.class);
    }

    @Test
    void registeredFactoryIsUsedAndDuplicateRegistrationsAreRejected() {
        TypeExtractor.registerFactory(RegisteredPojo.class, RegisteredPojoFactory.class);

        TypeInformation<RegisteredPojo> info = TypeExtractor.createTypeInfo(RegisteredPojo.class);
        assertThat(info).isInstanceOf(GenericTypeInfo.class);
        assertThat(TypeExtractor.getTypeInfoFactory(RegisteredPojo.class))
                .isInstanceOf(RegisteredPojoFactory.class);

        assertThatThrownBy(
                        () ->
                                TypeExtractor.registerFactory(
                                        RegisteredPojo.class, OtherRegisteredPojoFactory.class))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("already registered");
    }

    @Test
    void registerFactoryRejectsNullAndInvalidFactoryClasses() {
        assertThatThrownBy(() -> TypeExtractor.registerFactory(null, RegisteredPojoFactory.class))
                .isInstanceOf(NullPointerException.class);
        assertThatThrownBy(
                        () -> TypeExtractor.registerFactory(UnregisteredPojo.class, (Class) null))
                .isInstanceOf(NullPointerException.class);

        @SuppressWarnings({"rawtypes", "unchecked"})
        Class<? extends TypeInfoFactory<?>> invalidFactory = (Class) String.class;
        assertThatThrownBy(
                        () ->
                                TypeExtractor.registerFactory(
