        MapFunction<String, Integer> mapper = value -> value.length();
        FlatMapFunction<String, Long> flatMapper =
                (value, out) -> out.collect((long) value.length());
        JoinFunction<String, Integer, Double> joiner =
                (first, second) -> (double) (first.length() + second);

        assertThat(TypeExtractor.getMapReturnTypes(mapper, BasicTypeInfo.STRING_TYPE_INFO))
                .isEqualTo(BasicTypeInfo.INT_TYPE_INFO);
        assertThat(
                        TypeExtractor.getJoinReturnTypes(
                                joiner,
                                BasicTypeInfo.STRING_TYPE_INFO,
                                BasicTypeInfo.INT_TYPE_INFO))
                .isEqualTo(BasicTypeInfo.DOUBLE_TYPE_INFO);

        // The compiler does not retain enough information about the Collector type parameter of
        // a flat-map lambda. This is reported instead of returning a wrong type.
        assertThatThrownBy(
                        () ->
                                TypeExtractor.getFlatMapReturnTypes(
                                        flatMapper, BasicTypeInfo.STRING_TYPE_INFO))
                .isInstanceOf(InvalidTypesException.class)
                .hasMessageContaining("generic type parameters of 'Collector' are missing");

        TypeInformation<?> missing =
                TypeExtractor.getFlatMapReturnTypes(
                        flatMapper, BasicTypeInfo.STRING_TYPE_INFO, "flatLambda", true);
        assertThat(missing).isInstanceOf(MissingTypeInfo.class);
        assertThat(((MissingTypeInfo) missing).getFunctionName()).isEqualTo("flatLambda");
    }

