    /** A local file system that participates in the distributed initialization code path. */
    private static final class DistributedLocalFileSystem extends LocalFileSystem {
        @Override
        public boolean isDistributedFS() {
            return true;
        }
    }

    /** A local file system that cannot create directories. */
    private static final class FailingMkdirFileSystem extends LocalFileSystem {
        @Override
        public boolean mkdirs(Path f) {
            return false;
        }
    }

    /** Records the write mode passed through the deprecated create methods. */
    private static final class WriteModeRecordingFileSystem extends LocalFileSystem {
        private WriteMode lastWriteMode;

        @Override
        public FSDataOutputStream create(Path f, WriteMode overwriteMode) {
            lastWriteMode = overwriteMode;
            return null;
        }
    }

    /** A file system whose URI is the one requested from its factory. */
    private static final class RecordingFileSystem extends LocalFileSystem {
        private final URI uri;

        private RecordingFileSystem(URI uri) {
            this.uri = uri;
        }

        @Override
        public URI getUri() {
            return uri;
        }
    }

    /**
     * Base factory for tests that need deterministic file system instances and registration data.
     */
    private static class RecordingFileSystemFactory implements FileSystemFactory, MetricsAware {
        private final String scheme;
        private final int priority;
        private final List<URI> createdUris = new ArrayList<>();
        private final List<MetricGroup> metricGroups = new ArrayList<>();
        private Configuration configuration;

        private RecordingFileSystemFactory(String scheme, int priority) {
            this.scheme = scheme;
            this.priority = priority;
        }

        @Override
        public String getScheme() {
            return scheme;
        }

        @Override
        public FileSystem create(URI fsUri) {
            createdUris.add(fsUri);
            return new RecordingFileSystem(fsUri);
        }

        @Override
        public void configure(Configuration config) {
            configuration = config;
        }

        @Override
        public int getPriority() {
            return priority;
        }

        @Override
        public void setMetricGroup(MetricGroup metricGroup) {
            metricGroups.add(metricGroup);
        }

        List<URI> createdUris() {
            return createdUris;
        }
    }

    private static final class LowPriorityRecordingFactory extends RecordingFileSystemFactory {
        private LowPriorityRecordingFactory() {
            super(PLUGIN_SCHEME, 1);
        }
    }

    private static final class HighPriorityRecordingFactory extends RecordingFileSystemFactory {
        private HighPriorityRecordingFactory() {
            super(PLUGIN_SCHEME, 10);
        }
    }

    /** A factory that intentionally does not opt into metrics. */
    private static final class PlainRecordingFileSystemFactory implements FileSystemFactory {
        private final String scheme;

        private PlainRecordingFileSystemFactory(String scheme) {
            this.scheme = scheme;
        }

        @Override
        public String getScheme() {
            return scheme;
        }

        @Override
        public FileSystem create(URI fsUri) {
            return new RecordingFileSystem(fsUri);
        }
    }

    /** Supplies explicitly constructed factories in place of a plugin directory. */
    private static final class TestingPluginManager implements PluginManager {
        private final List<FileSystemFactory> factories;

        private TestingPluginManager(FileSystemFactory... factories) {
            this.factories = List.of(factories);
        }

        @Override
        public <P> Iterator<P> load(Class<P> service) {
            if (service != FileSystemFactory.class) {
                return Collections.emptyIterator();
            }
            return factories.stream().map(service::cast).iterator();
        }
    }

    /** A metric group that records the child group requested by the production code. */
    private static final class RecordingMetricGroup extends UnregisteredMetricsGroup {
        private final List<String> addedGroupNames = new ArrayList<>();
        private final MetricGroup filesystemGroup = new UnregisteredMetricsGroup();

        @Override
        public MetricGroup addGroup(String name) {
            addedGroupNames.add(name);
            return filesystemGroup;
        }
    }
}

