        Record right = intRecord(1, null, 3, 4);
        right.updateBinaryRepresenation();

        left.unionFields(right);

        assertEquals(4, left.getNumFields());
        assertEquals(1, intAt(left, 0));
        assertTrue(left.isNull(1));
        assertEquals(3, intAt(left, 2));
        assertEquals(4, intAt(left, 3));

        Record copy = roundTrip(left);
        assertEquals(4, copy.getNumFields());
        assertEquals(1, intAt(copy, 0));
        assertTrue(copy.isNull(1));
        assertEquals(3, intAt(copy, 2));
        assertEquals(4, intAt(copy, 3));
    }

    @Test
    void testUnionFieldsResultSurvivesSerialization() throws Exception {
        Record left = intRecord(1, 2);
        Record right = intRecord(null, 20, 30);
        left.unionFields(right);

        Record copy = roundTrip(left);
        assertArrayEquals(
                new Integer[] {1, 2, 30},
                new Integer[] {intAt(copy, 0), intAt(copy, 1), intAt(copy, 2)});
    }

    // --------------------------------------------------------------------------------------------
    //                              copyTo / createCopy / copy
    // --------------------------------------------------------------------------------------------

    @Test
    void testCopyToCreatesIndependentRecord() {
        Record original = intRecord(1, 2);
        Record copy = new Record();

        original.copyTo(copy);

        assertEquals(2, copy.getNumFields());
        assertEquals(1, intAt(copy, 0));
        assertEquals(2, intAt(copy, 1));

        copy.setField(0, new IntValue(50));
        copy.removeField(1);
        assertEquals(2, original.getNumFields());
        assertEquals(1, intAt(original, 0));
        assertEquals(2, intAt(original, 1));

        original.setField(1, new IntValue(60));
        assertEquals(50, intAt(copy, 0));
    }

    @Test
    void testCopyToOverwritesTargetContent() {
        Record target = intRecord(7, 8, 9, 10);
        Record source = intRecord(1, 2);

        source.copyTo(target);

        assertEquals(2, target.getNumFields());
        assertEquals(1, intAt(target, 0));
        assertEquals(2, intAt(target, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> target.getField(2, IntValue.class));
    }

    @Test
    void testCopyToWithModifiedSourceFields() {
        Record source = new Record();
        source.setField(0, new IntValue(5));
        source.setField(1, new StringValue("abc"));

        Record target = new Record();
        source.copyTo(target);

        assertEquals(5, intAt(target, 0));
        assertEquals("abc", target.getField(1, StringValue.class).getValue());
    }

    @Test
    void testCopyAndCreateCopyAreEquivalent() throws Exception {
        Record original = intRecord(1, null, 3);

        Record copy = original.copy();
        Record created = original.createCopy();

        assertEquals(original.getNumFields(), copy.getNumFields());
        assertEquals(original.getNumFields(), created.getNumFields());
        for (int i = 0; i < original.getNumFields(); i++) {
            assertEquals(original.isNull(i), copy.isNull(i));
            assertEquals(original.isNull(i), created.isNull(i));
        }
        assertEquals(3, intAt(copy, 2));
        assertEquals(3, intAt(created, 2));
    }

    // --------------------------------------------------------------------------------------------
    //                          write / read / serialize / deserialize / copy
    // --------------------------------------------------------------------------------------------

    @Test
    void testWriteReadRoundTripWithMixedFields() throws Exception {
        Record record = new Record(3);
        record.setField(0, new IntValue(11));
        record.setField(1, null);
        record.setField(2, new StringValue("round trip"));

        Record copy = roundTrip(record);

        assertEquals(3, copy.getNumFields());
        assertEquals(11, intAt(copy, 0));
        assertTrue(copy.isNull(1));
        assertEquals("round trip", copy.getField(2, StringValue.class).getValue());
    }

    @Test
    void testWriteReadRoundTripForRecordsWithManyFields() throws Exception {
        Record record = new Record(65);
        for (int i = 0; i < 65; i++) {
            record.setField(i, i % 7 == 0 ? null : new IntValue(i * 3));
        }

        Record copy = roundTrip(record);

        assertEquals(65, copy.getNumFields());
        for (int i = 0; i < 65; i++) {
            if (i % 7 == 0) {
                assertTrue(copy.isNull(i), "Field " + i + " should be null");
            } else {
                assertEquals(i * 3, intAt(copy, i));
            }
        }
    }

    @Test
    void testWriteReadRoundTripForRecordsWithNineFields() throws Exception {
        Record record = intRecord(1, 2, 3, 4, null, 6, 7, 8, 9);

        Record copy = roundTrip(record);

        assertEquals(9, copy.getNumFields());
        assertTrue(copy.isNull(4));
        assertEquals(1, intAt(copy, 0));
        assertEquals(9, intAt(copy, 8));
    }

    @Test
    void testWriteReadRoundTripForEmptyRecord() throws Exception {
        Record copy = roundTrip(new Record());

        assertEquals(0, copy.getNumFields());
    }

    @Test
    void testSerializeReturnsNumberOfWrittenBytes() throws Exception {
        Record record = intRecord(1, 2, 3);
        DataOutputSerializer out = new DataOutputSerializer(16);

        long written = record.serialize(out);

        assertEquals(out.length(), written);
        assertTrue(written > 0);
    }

    @Test
    void testSerializeWritesSameBytesAsWrite() throws Exception {
        Record record = new Record(2);
        record.setField(0, new IntValue(7));
        record.setField(1, new StringValue("bytes"));

        DataOutputSerializer serializeOut = new DataOutputSerializer(64);
        record.serialize(serializeOut);
        DataOutputSerializer writeOut = new DataOutputSerializer(64);
        record.write(writeOut);

        assertArrayEquals(writeOut.getCopyOfBuffer(), serializeOut.getCopyOfBuffer());
    }

    @Test
    void testCopyBetweenViewsPreservesContent() throws Exception {
        Record source = new Record(2);
        source.setField(0, new IntValue(11));
        source.setField(1, new StringValue("hello"));

        DataOutputSerializer sourceOut = new DataOutputSerializer(64);
        source.write(sourceOut);
        byte[] serialized = sourceOut.getCopyOfBuffer();

        DataOutputSerializer targetOut = new DataOutputSerializer(64);
        Record copier = new Record();
        copier.copy(new DataInputDeserializer(serialized), targetOut);

        assertEquals(serialized.length, targetOut.length());

        Record result = new Record();
        result.read(new DataInputDeserializer(targetOut.getCopyOfBuffer()));
        assertEquals(2, result.getNumFields());
        assertEquals(11, intAt(result, 0));
        assertEquals("hello", result.getField(1, StringValue.class).getValue());
    }

    @Test
    void testDeserializeIsEquivalentToRead() throws Exception {
        Record record = intRecord(1, 2);
        DataOutputSerializer out = new DataOutputSerializer(64);
        record.write(out);

        Record deserialized = new Record();
        deserialized.deserialize(new DataInputDeserializer(out.getCopyOfBuffer()));

        assertEquals(2, deserialized.getNumFields());
        assertEquals(1, intAt(deserialized, 0));
        assertEquals(2, intAt(deserialized, 1));
    }

    @Test
    void testReadIntoReusedRecordReplacesContent() throws Exception {
        Record reused = intRecord(1, 2, 3, 4, 5);
        Record source = intRecord(7, 8);
        DataOutputSerializer out = new DataOutputSerializer(64);
        source.write(out);

        reused.read(new DataInputDeserializer(out.getCopyOfBuffer()));

        assertEquals(2, reused.getNumFields());
        assertEquals(7, intAt(reused, 0));
        assertEquals(8, intAt(reused, 1));
    }

    @Test
    void testReadFromTruncatedInputThrows() throws Exception {
        Record record = intRecord(1, 2, 3);
        DataOutputSerializer out = new DataOutputSerializer(64);
        record.write(out);
        byte[] truncated = Arrays.copyOf(out.getCopyOfBuffer(), 4);

        assertThrows(
                EOFException.class,
                () -> new Record().read(new DataInputDeserializer(truncated)));
    }

    @Test
    void testReadWithCorruptedHeaderThrowsRuntimeException() throws Exception {
        Record record = intRecord(1, 2);
        DataOutputSerializer out = new DataOutputSerializer(64);
        record.write(out);
        byte[] corrupted = out.getCopyOfBuffer();
        // turn the number of fields at the end of the record into a multi byte value
        corrupted[corrupted.length - 1] = (byte) 0xC8;

        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () -> new Record().read(new DataInputDeserializer(corrupted)));
        assertTrue(exception.getMessage().startsWith("Record deserialization error"));
    }

    // --------------------------------------------------------------------------------------------
    //                                     copyFrom
    // --------------------------------------------------------------------------------------------

    @Test
    void testCopyFromCopiesSelectedFieldsIntoSelectedPositions() throws Exception {
        Record source = new Record(2);
        source.setField(0, new IntValue(11));
        source.setField(1, new StringValue("hello"));
        source.updateBinaryRepresenation();

        Record target = intRecord(-1, -2, -3);
        target.copyFrom(source, new int[] {0, 1}, new int[] {2, 0});

        assertEquals(3, target.getNumFields());
        assertEquals("hello", target.getField(0, StringValue.class).getValue());
        assertEquals(-2, intAt(target, 1));

        Record copy = roundTrip(target);
        assertEquals(3, copy.getNumFields());
        assertEquals("hello", copy.getField(0, StringValue.class).getValue());
        assertEquals(-2, intAt(copy, 1));
        assertEquals(11, intAt(copy, 2));
    }

    @Test
    void testCopyFromExpandsTargetAndCopiesModifiedFields() {
        IntValue modified = new IntValue(5);
        Record source = new Record(1);
        source.setField(0, modified);

        Record target = new Record(0);
        target.copyFrom(source, new int[] {0}, new int[] {1});

        assertEquals(2, target.getNumFields());
        assertTrue(target.isNull(0));
        assertSame(modified, target.getField(1, IntValue.class));
    }

    @Test
    void testCopyFromNullSourceFieldNullifiesTargetField() {
        Record source = new Record(1);
        Record target = intRecord(5);

        target.copyFrom(source, new int[] {0}, new int[] {0});

        assertTrue(target.isNull(0));
    }

    // --------------------------------------------------------------------------------------------
    //                                   Java serialization
    // --------------------------------------------------------------------------------------------

    @Test
    void testJavaSerializationRoundTrip() throws Exception {
        Record record = new Record(3);
        record.setField(0, new IntValue(1));
        record.setField(2, new StringValue("abc"));

        byte[] serialized = InstantiationUtil.serializeObject(record);
        Record copy =
                InstantiationUtil.deserializeObject(
                        serialized, RecordTests.class.getClassLoader());

        assertEquals(3, copy.getNumFields());
        assertEquals(1, intAt(copy, 0));
        assertTrue(copy.isNull(1));
        assertEquals("abc", copy.getField(2, StringValue.class).getValue());
    }
}

