/** Tests for the {@link Record} data type. */
class RecordTests {

    // --------------------------------------------------------------------------------------------
    //                                     Test utilities
    // --------------------------------------------------------------------------------------------

    /** Serializes the record and reads it back into a fresh record (binary round trip). */
    private static Record roundTrip(Record record) throws IOException {
        DataOutputSerializer out = new DataOutputSerializer(1024);
        record.write(out);
        Record result = new Record();
        result.read(new DataInputDeserializer(out.getCopyOfBuffer()));
        return result;
    }

    /** Creates a record where the given (possibly {@code null}) values are stored as int fields. */
    private static Record intRecord(Integer... values) {
        Record record = new Record(values.length);
        for (int i = 0; i < values.length; i++) {
            record.setField(i, values[i] == null ? null : new IntValue(values[i]));
        }
        return record;
    }

    private static int intAt(Record record, int position) {
        return record.getField(position, IntValue.class).getValue();
    }

    // --------------------------------------------------------------------------------------------
    //                                   Construction / field count
    // --------------------------------------------------------------------------------------------

    @Test
    void testEmptyRecordHasNoFields() {
        Record record = new Record();

        assertEquals(0, record.getNumFields());
        assertEquals(-1, record.getBinaryLength());
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(0));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(0, IntValue.class));
    }

    @Test
    void testSingleValueConstructor() {
        Record record = new Record(new IntValue(42));

        assertEquals(1, record.getNumFields());
        assertFalse(record.isNull(0));
        assertEquals(42, intAt(record, 0));
    }

    @Test
    void testTwoValueConstructor() {
        Record record = new Record(new IntValue(1), new StringValue("hello"));

        assertEquals(2, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals("hello", record.getField(1, StringValue.class).getValue());
    }

    @Test
    void testConstructorAcceptsNullFields() {
        Record single = new Record((Value) null);
        assertEquals(1, single.getNumFields());
        assertTrue(single.isNull(0));
        assertNull(single.getField(0, IntValue.class));

        Record pair = new Record((Value) null, new IntValue(3));
        assertEquals(2, pair.getNumFields());
        assertTrue(pair.isNull(0));
        assertEquals(3, intAt(pair, 1));
    }

    @Test
    void testNumFieldsConstructorCreatesNullFields() {
        Record record = new Record(5);

        assertEquals(5, record.getNumFields());
        for (int i = 0; i < 5; i++) {
            assertTrue(record.isNull(i), "Field " + i + " should be null");
            assertNull(record.getField(i, IntValue.class));
        }
    }

    @Test
    void testMakeSpaceDoesNotChangeNumberOfFields() {
        Record record = new Record();
        record.makeSpace(8);

        assertEquals(0, record.getNumFields());

        record.setField(0, new IntValue(7));
        assertEquals(1, record.getNumFields());
        assertEquals(7, intAt(record, 0));
    }

    @Test
    void testSetNumFieldsExpandsRecordWithNullFields() {
        Record record = new Record(new IntValue(1));
        record.setNumFields(4);

        assertEquals(4, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        for (int i = 1; i < 4; i++) {
            assertTrue(record.isNull(i));
        }
    }

    @Test
    void testSetNumFieldsTruncatesRecord() {
        Record record = intRecord(1, 2, 3, 4);
        record.setNumFields(2);

        assertEquals(2, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals(2, intAt(record, 1));
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(2));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(2, IntValue.class));
    }

    @Test
    void testSetNumFieldsToZeroClearsRecordButKeepsItUsable() {
        Record record = intRecord(1, 2);
        record.setNumFields(0);

        assertEquals(0, record.getNumFields());
        assertThrows(IndexOutOfBoundsException.class, () -> record.isNull(0));

        record.setField(0, new IntValue(9));
        assertEquals(1, record.getNumFields());
        assertEquals(9, intAt(record, 0));
    }

    // --------------------------------------------------------------------------------------------
