    // --------------------------------------------------------------------------------------------

    @Test
    void testSetFieldExpandsRecordBeyondCurrentSize() throws Exception {
        Record record = new Record();
        record.setField(4, new IntValue(5));

        assertEquals(5, record.getNumFields());
        for (int i = 0; i < 4; i++) {
            assertTrue(record.isNull(i));
        }
        assertEquals(5, intAt(record, 4));

        Record copy = roundTrip(record);
        assertEquals(5, copy.getNumFields());
        assertTrue(copy.isNull(0));
        assertTrue(copy.isNull(3));
        assertEquals(5, intAt(copy, 4));
    }

    @Test
    void testSetFieldToNullMarksFieldAsNull() throws Exception {
        Record record = intRecord(1);
        record.setField(0, null);

        assertEquals(1, record.getNumFields());
        assertTrue(record.isNull(0));
        assertNull(record.getField(0, IntValue.class));
        assertTrue(roundTrip(record).isNull(0));
    }

    @Test
    void testSetFieldWithNegativePositionThrows() {
        Record record = new Record();

        assertThrows(IndexOutOfBoundsException.class, () -> record.setField(-1, new IntValue(1)));
    }

    @Test
    void testAddFieldAppendsFields() throws Exception {
        Record record = new Record(1);
        record.setField(0, new IntValue(1));
        record.addField(new StringValue("s"));
        record.addField(null);

        assertEquals(3, record.getNumFields());
        assertEquals(1, intAt(record, 0));
        assertEquals("s", record.getField(1, StringValue.class).getValue());
        assertTrue(record.isNull(2));

        Record copy = roundTrip(record);
        assertEquals(3, copy.getNumFields());
        assertEquals("s", copy.getField(1, StringValue.class).getValue());
        assertTrue(copy.isNull(2));
    }

