        assertThrows(NullPointerException.class, () -> record.getField(0, (Value) null));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(1, new IntValue()));
        assertThrows(IndexOutOfBoundsException.class, () -> record.getField(-1, new IntValue()));
    }

    // --------------------------------------------------------------------------------------------
    //                          getFieldInto / getFieldsInto(CheckingNull)
    // --------------------------------------------------------------------------------------------

    @Test
    void testGetFieldIntoReadsBinaryField() throws Exception {
        Record record = roundTrip(intRecord(23));

        IntValue target = new IntValue();
        assertTrue(record.getFieldInto(0, target));
        assertEquals(23, target.getValue());
    }

    @Test
    void testGetFieldIntoReturnsFalseForNullFieldAndKeepsTarget() {
        Record record = new Record(1);
        IntValue target = new IntValue(-3);

        assertFalse(record.getFieldInto(0, target));
        assertEquals(-3, target.getValue());
    }

    @Test
    void testGetFieldIntoHandlesModifiedFields() {
        Record record = new Record();
        record.setField(0, new IntValue(33));

        IntValue target = new IntValue();
        assertTrue(record.getFieldInto(0, target));
        assertEquals(33, target.getValue());
        assertEquals(33, intAt(record, 0));
    }

    @Test
    void testGetFieldIntoOutOfRangeThrows() {
        Record record = new Record(1);

        assertThrows(IndexOutOfBoundsException.class, () -> record.getFieldInto(1, new IntValue()));
        assertThrows(
                IndexOutOfBoundsException.class, () -> record.getFieldInto(-1, new IntValue()));
    }

    @Test
    void testGetFieldsIntoFillsAllRequestedFields() throws Exception {
        Record record = roundTrip(intRecord(1, 2, 3));

        Value[] targets = {new IntValue(), new IntValue()};
        assertTrue(record.getFieldsInto(new int[] {0, 2}, targets));
        assertEquals(1, ((IntValue) targets[0]).getValue());
        assertEquals(3, ((IntValue) targets[1]).getValue());
    }

    @Test
    void testGetFieldsIntoStopsAtFirstNullField() throws Exception {
        Record record = roundTrip(intRecord(1, null, 3));

        Value[] targets = {new IntValue(), new IntValue(-1), new IntValue(-2)};
        assertFalse(record.getFieldsInto(new int[] {0, 1, 2}, targets));
        assertEquals(1, ((IntValue) targets[0]).getValue());
        assertEquals(-1, ((IntValue) targets[1]).getValue());
        assertEquals(-2, ((IntValue) targets[2]).getValue());
    }

    @Test
    void testGetFieldsIntoCheckingNullThrowsForNullField() throws Exception {
        Record record = roundTrip(intRecord(1, null));

        Value[] targets = {new IntValue(), new IntValue()};
        NullKeyFieldException exception =
                assertThrows(
                        NullKeyFieldException.class,
                        () -> record.getFieldsIntoCheckingNull(new int[] {0, 1}, targets));
        assertEquals(1, exception.getFieldNumber());
        assertEquals(1, ((IntValue) targets[0]).getValue());
    }

    @Test
    void testGetFieldsIntoCheckingNullSucceedsForNonNullFields() throws Exception {
        Record record = roundTrip(intRecord(4, 5));

        Value[] targets = {new IntValue(), new IntValue()};
        record.getFieldsIntoCheckingNull(new int[] {0, 1}, targets);
        assertEquals(4, ((IntValue) targets[0]).getValue());
        assertEquals(5, ((IntValue) targets[1]).getValue());
    }

    // --------------------------------------------------------------------------------------------
    //                                        equalsFields
    // --------------------------------------------------------------------------------------------

    @Test
    void testEqualsFieldsComparesRequestedPositions() throws Exception {
        Record record = roundTrip(new Record(new IntValue(1), new StringValue("x")));

        Value[] holders = {new IntValue(), new StringValue()};
        assertTrue(
                record.equalsFields(
                        new int[] {0, 1},
                        new Value[] {new IntValue(1), new StringValue("x")},
                        holders));

        Value[] otherHolders = {new IntValue(), new StringValue()};
        assertFalse(
                record.equalsFields(
                        new int[] {0, 1},
                        new Value[] {new IntValue(2), new StringValue("x")},
                        otherHolders));
    }

    @Test
    void testEqualsFieldsReturnsFalseForNullField() throws Exception {
        Record record = roundTrip(intRecord((Integer) null));

        assertFalse(
                record.equalsFields(
                        new int[] {0}, new Value[] {new IntValue(1)}, new Value[] {new IntValue()}));
    }

    // --------------------------------------------------------------------------------------------
    //                                 removeField / isNull / setNull
    // --------------------------------------------------------------------------------------------

    @Test
    void testRemoveFieldShiftsRemainingFields() throws Exception {
        Record record = roundTrip(intRecord(1, 2, 3));
        record.removeField(1);

        assertEquals(2, record.getNumFields());
        assertEquals(1, intAt(record, 0));
