            record.setField(i, i % 7 == 0 ? null : new IntValue(i * 3));
        }

        Record copy = roundTrip(record);

        assertEquals(65, copy.getNumFields());
        for (int i = 0; i < 65; i++) {
            if (i % 7 == 0) {
