        source.setField(1, new StringValue("hello"));

        DataOutputSerializer sourceOut = new DataOutputSerializer(64);
        source.write(sourceOut);
        byte[] serialized = sourceOut.getCopyOfBuffer();

        DataOutputSerializer targetOut = new DataOutputSerializer(64);
        Record copier = new Record();
        copier.copy(new DataInputDeserializer(serialized), targetOut);

        assertEquals(serialized.length, targetOut.length());

        Record result = new Record();
        result.read(new DataInputDeserializer(targetOut.getCopyOfBuffer()));
        assertEquals(2, result.getNumFields());
        assertEquals(11, intAt(result, 0));
        assertEquals("hello", result.getField(1, StringValue.class).getValue());
