    @Test
    void testReadWithCorruptedHeaderThrowsRuntimeException() throws Exception {
        Record record = intRecord(1, 2);
        DataOutputSerializer out = new DataOutputSerializer(64);
        record.write(out);
        byte[] corrupted = out.getCopyOfBuffer();
        // turn the number of fields at the end of the record into a multi byte value
        corrupted[corrupted.length - 1] = (byte) 0xC8;

        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () -> new Record().read(new DataInputDeserializer(corrupted)));
        assertTrue(exception.getMessage().startsWith("Record deserialization error"));
