        final String schema =
                "{\"type\":\"record\",\"name\":\"PrimitiveRecord\",\"namespace\":\"com.example\","
                        + "\"fields\":["
                        + "{\"name\":\"f_int\",\"type\":\"int\"},"
                        + "{\"name\":\"f_long\",\"type\":\"long\"},"
                        + "{\"name\":\"f_float\",\"type\":\"float\"},"
                        + "{\"name\":\"f_double\",\"type\":\"double\"},"
                        + "{\"name\":\"f_boolean\",\"type\":\"boolean\"},"
                        + "{\"name\":\"f_string\",\"type\":\"string\"},"
                        + "{\"name\":\"f_bytes\",\"type\":\"bytes\"},"
                        + "{\"name\":\"f_null\",\"type\":\"null\"}]}";

        final TypeInformation<Row> typeInfo = AvroSchemaConverter.convertToTypeInfo(schema);

        final RowTypeInfo rowInfo = assertInstanceOf(RowTypeInfo.class, typeInfo);
        assertArrayEquals(
                new String[] {
                    "f_int",
                    "f_long",
                    "f_float",
                    "f_double",
                    "f_boolean",
                    "f_string",
                    "f_bytes",
                    "f_null"
