    @Test
    void testConvertToSchemaRecordWithNestedRecordAndDefaults() {
        final RowType rowType =
                (RowType)
                        DataTypes.ROW(
                                        DataTypes.FIELD("id", DataTypes.INT().notNull()),
                                        DataTypes.FIELD("name", DataTypes.STRING()),
                                        DataTypes.FIELD(
                                                "nested",
                                                DataTypes.ROW(
                                                                DataTypes.FIELD(
                                                                        "value",
                                                                        DataTypes.BIGINT()
                                                                                .notNull()))
                                                        .notNull()))
                                .notNull()
                                .getLogicalType();

        final Schema schema = AvroSchemaConverter.convertToSchema(rowType);

        assertEquals(Schema.Type.RECORD, schema.getType());
        assertEquals("record", schema.getName());
        assertEquals("org.apache.flink.avro.generated", schema.getNamespace());
        assertEquals(3, schema.getFields().size());
        assertEquals("id", schema.getFields().get(0).name());
        assertEquals("name", schema.getFields().get(1).name());
        assertEquals("nested", schema.getFields().get(2).name());

        final Schema.Field idField = schema.getField("id");
        assertEquals(Schema.Type.INT, idField.schema().getType());
        assertFalse(idField.hasDefaultValue());

        final Schema.Field nameField = schema.getField("name");
        assertEquals(Schema.Type.UNION, nameField.schema().getType());
        assertEquals(Schema.Type.NULL, nameField.schema().getTypes().get(0).getType());
        assertEquals(Schema.Type.STRING, nameField.schema().getTypes().get(1).getType());
        assertTrue(nameField.hasDefaultValue());

        final Schema nested = schema.getField("nested").schema();
        assertEquals(Schema.Type.RECORD, nested.getType());
        assertEquals("record_nested", nested.getName());
        assertEquals(Schema.Type.LONG, nested.getField("value").schema().getType());
        assertFalse(nested.getField("value").hasDefaultValue());
    }

