    @Test
    void testExtractValueTypeToAvroMap() {
        final LogicalType valueType = DataTypes.BIGINT().notNull().getLogicalType();
        final MapType mapType =
                new MapType(DataTypes.STRING().notNull().getLogicalType(), valueType);
        assertEquals(valueType, AvroSchemaConverter.extractValueTypeToAvroMap(mapType));

        final MultisetType multisetType =
                new MultisetType(DataTypes.STRING().notNull().getLogicalType());
        final LogicalType multisetValue =
                AvroSchemaConverter.extractValueTypeToAvroMap(multisetType);
        assertInstanceOf(IntType.class, multisetValue);
        assertTrue(multisetValue.isNullable());

        final MapType invalidMapType =
                new MapType(
                        DataTypes.INT().notNull().getLogicalType(),
                        DataTypes.STRING().notNull().getLogicalType());
        assertThrows(
                UnsupportedOperationException.class,
                () -> AvroSchemaConverter.extractValueTypeToAvroMap(invalidMapType));
    }

