        }

        byte[] binary = new byte[] {1, 2, 3, -1};
        ColumnVector binaryVector = createVectorFromConstant(new VarBinaryType(), binary, batchSize);
        HeapBytesVector binaryHeap = assertInstanceOf(HeapBytesVector.class, binaryVector);
        for (int i = 0; i < batchSize; i++) {
            assertArrayEquals(binary, binaryHeap.getBytes(i).getBytes());
        }

