        HeapByteVector tiny =
                assertInstanceOf(
                        HeapByteVector.class,
                        createVectorFromConstant(new TinyIntType(), (short) 7, batchSize));
        HeapShortVector small =
                assertInstanceOf(
                        HeapShortVector.class,
                        createVectorFromConstant(new SmallIntType(), 300, batchSize));
        HeapIntVector integer =
                assertInstanceOf(
                        HeapIntVector.class,
                        createVectorFromConstant(new IntType(), 42L, batchSize));
        HeapLongVector bigint =
                assertInstanceOf(
                        HeapLongVector.class,
                        createVectorFromConstant(new BigIntType(), 12345, batchSize));
        HeapFloatVector floatVector =
                assertInstanceOf(
                        HeapFloatVector.class,
