        HeapDoubleVector doubleVector =
                assertInstanceOf(
                        HeapDoubleVector.class,
                        createVectorFromConstant(new DoubleType(), 2.5f, batchSize));

        for (int i = 0; i < batchSize; i++) {
            assertTrue(bool.getBoolean(i));
            assertEquals((byte) 7, tiny.getByte(i));
            assertEquals((short) 300, small.getShort(i));
            assertEquals(42, integer.getInt(i));
            assertEquals(12345L, bigint.getLong(i));
            assertEquals(1.5f, floatVector.getFloat(i));
            assertEquals(2.5d, doubleVector.getDouble(i));
