                        new LogicalType[] {new IntType(), new VarCharType()},
                        new String[] {"x", "y"});
        RowType rowType =
                RowType.of(
                        new LogicalType[] {
                            new ArrayType(new IntType()),
                            new MapType(new VarCharType(), new IntType()),
                            new MultisetType(new VarCharType()),
                            nestedRow
                        },
                        new String[] {"arr", "mp", "ms", "rw"});
        MessageType schema =
                ParquetSchemaConverter.convertToParquetMessageType(
                        "test", rowType, new Configuration());

        List<ParquetField> fields =
                buildFieldsList(rowType.getFields(), rowType.getFieldNames(), columnIO(schema));

        assertEquals(4, fields.size());

        ParquetGroupField array = assertInstanceOf(ParquetGroupField.class, fields.get(0));
        assertInstanceOf(ArrayType.class, array.getType());
        assertFalse(array.isRequired());
        assertEquals(1, array.getChildren().size());
        ParquetPrimitiveField arrayElement =
                assertInstanceOf(ParquetPrimitiveField.class, array.getChildren().get(0));
        assertEquals(new IntType(), arrayElement.getType());
        assertArrayEquals(new String[] {"arr", "list", "element"}, arrayElement.getDescriptor().getPath());
        assertEquals(1, arrayElement.getRepetitionLevel());
        assertEquals(3, arrayElement.getDefinitionLevel());

        ParquetGroupField map = assertInstanceOf(ParquetGroupField.class, fields.get(1));
        assertInstanceOf(MapType.class, map.getType());
        assertEquals(2, map.getChildren().size());
        ParquetPrimitiveField mapKey =
                assertInstanceOf(ParquetPrimitiveField.class, map.getChildren().get(0));
        ParquetPrimitiveField mapValue =
                assertInstanceOf(ParquetPrimitiveField.class, map.getChildren().get(1));
        assertEquals(new VarCharType(), mapKey.getType());
        assertEquals(new IntType(), mapValue.getType());
        assertArrayEquals(new String[] {"mp", "key_value", "key"}, mapKey.getDescriptor().getPath());
        assertArrayEquals(
                new String[] {"mp", "key_value", "value"}, mapValue.getDescriptor().getPath());
        assertTrue(mapKey.isRequired());
        assertFalse(mapValue.isRequired());

        ParquetGroupField multiset = assertInstanceOf(ParquetGroupField.class, fields.get(2));
        assertInstanceOf(MultisetType.class, multiset.getType());
        assertEquals(2, multiset.getChildren().size());
        ParquetPrimitiveField multisetKey =
                assertInstanceOf(ParquetPrimitiveField.class, multiset.getChildren().get(0));
        ParquetPrimitiveField multisetValue =
                assertInstanceOf(ParquetPrimitiveField.class, multiset.getChildren().get(1));
        assertEquals(new VarCharType(), multisetKey.getType());
        assertEquals(new IntType(), multisetValue.getType());
        assertArrayEquals(
                new String[] {"ms", "key_value", "value"},
                multisetValue.getDescriptor().getPath());

        ParquetGroupField row = assertInstanceOf(ParquetGroupField.class, fields.get(3));
        assertEquals(nestedRow, row.getType());
        assertEquals(2, row.getChildren().size());
        assertEquals(new IntType(), row.getChildren().get(0).getType());
        assertEquals(new VarCharType(), row.getChildren().get(1).getType());
    }

