        java.nio.file.Path file = dir.resolve("data.parquet");
        MessageType schema =
                parse("message test { required int32 id; optional binary name (UTF8); }");
        Configuration conf = new Configuration();

        try (ParquetWriter<Group> writer =
                ExampleParquetWriter.builder(new org.apache.hadoop.fs.Path(file.toUri()))
                        .withType(schema)
                        .withConf(conf)
                        .withCompressionCodec(CompressionCodecName.UNCOMPRESSED)
                        .build()) {
            SimpleGroupFactory factory = new SimpleGroupFactory(schema);

            Group first = factory.newGroup();
            first.add("id", 1);
            first.add("name", "alice");
            writer.write(first);

            Group second = factory.newGroup();
            second.add("id", 2);
            writer.write(second);

            Group third = factory.newGroup();
            third.add("id", 3);
            third.add("name", "carol");
            writer.write(third);
