    @Test
    void testGenPartColumnarRowReaderReadsSelectedAndPartitionColumns(@TempDir java.nio.file.Path dir)
            throws Exception {
        java.nio.file.Path file = writeThreeRowParquetFile(dir);

        String[] fieldNames = new String[] {"id", "name", "part"};
        DataType[] fieldTypes =
                TypeConversions.fromLogicalToDataType(
                        new LogicalType[] {new IntType(), new VarCharType(), new VarCharType()});
        Map<String, Object> partitionSpec = new HashMap<>();
        partitionSpec.put("part", "p1");

        try (ParquetColumnarRowSplitReader reader =
                genPartColumnarRowReader(
                        false,
                        true,
                        new Configuration(),
                        fieldNames,
                        fieldTypes,
                        partitionSpec,
                        new int[] {0, 1, 2},
                        2,
                        new org.apache.flink.core.fs.Path(file.toUri()),
                        0,
                        Files.size(file))) {
            assertFalse(reader.reachedEnd());

            ColumnarRowData first = reader.nextRecord();
            assertEquals(1, first.getInt(0));
            assertEquals("alice", first.getString(1).toString());
            assertEquals("p1", first.getString(2).toString());

            ColumnarRowData second = reader.nextRecord();
            assertEquals(2, second.getInt(0));
            assertTrue(second.isNullAt(1));
            assertEquals("p1", second.getString(2).toString());

            // Reading the next record requires the next batch to be loaded first.
            assertFalse(reader.reachedEnd());
            ColumnarRowData third = reader.nextRecord();
            assertEquals(3, third.getInt(0));
            assertEquals("carol", third.getString(1).toString());
            assertEquals("p1", third.getString(2).toString());

            assertTrue(reader.reachedEnd());
        }
    }

