        ParquetGroupField element =
                assertInstanceOf(ParquetGroupField.class, array.getChildren().get(0));
        assertEquals(nestedRow, element.getType());
        assertEquals(2, element.getChildren().size());
        ParquetPrimitiveField x =
                assertInstanceOf(ParquetPrimitiveField.class, element.getChildren().get(0));
