class CheckpointCoordinatorTests {

    @Test
    void testMasterHookRegistrationAndShutdown() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            TestingMasterHook hook = new TestingMasterHook("hook");

            assertThat(context.coordinator.addMasterHook(hook)).isTrue();
            assertThat(context.coordinator.addMasterHook(hook)).isFalse();
            assertThat(context.coordinator.getNumberOfRegisteredMasterHooks()).isEqualTo(1);

            assertThatThrownBy(() -> context.coordinator.addMasterHook(new TestingMasterHook(" ")))
                    .isInstanceOf(IllegalArgumentException.class);
            assertThatThrownBy(() -> context.coordinator.addMasterHook(null))
                    .isInstanceOf(NullPointerException.class);

            context.coordinator.shutdown();

            assertThat(hook.closeCount).isEqualTo(1);
            assertThat(context.coordinator.getNumberOfRegisteredMasterHooks()).isZero();
        }
    }

    @Test
    void testCheckpointCompletesAndIsExposedByTheStore() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerCheckpoint(false);

            assertThat(future).isNotDone();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isEqualTo(1);
            assertThat(context.coordinator.isTriggering()).isFalse();

            long checkpointId = singlePendingCheckpointId(context);
            assertThat(context.acknowledge(checkpointId)).isTrue();

            CompletedCheckpoint completedCheckpoint = future.get(10, TimeUnit.SECONDS);
            assertThat(completedCheckpoint.getCheckpointID()).isEqualTo(checkpointId);
            assertThat(completedCheckpoint.getProperties().isSavepoint()).isFalse();
            assertThat(completedCheckpoint.getExternalPointer()).isEqualTo("test-location");
            assertThat(completedCheckpoint.getOperatorStates()).isEmpty();

            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isZero();
            assertThat(context.coordinator.getNumberOfRetainedSuccessfulCheckpoints()).isEqualTo(1);
            assertThat(context.coordinator.getSuccessfulCheckpoints())
                    .containsExactly(completedCheckpoint);
            assertThat(context.coordinator.getCheckpointStore()).isSameAs(context.store);

            assertThat(context.storageAccess.baseLocationInitializationCount).isEqualTo(1);
            assertThat(context.storageAccess.lastCheckpointLocationId).isEqualTo(checkpointId);
            assertThat(context.triggerCheckpointCalls).isEqualTo(1);
            assertThat(context.triggerSynchronousSavepointCalls).isZero();
        }
    }

    @Test
    void testCheckpointTypeIsConvertedToSnapshotType() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerCheckpoint(
                            org.apache.flink.core.execution.CheckpointType.FULL);

            assertThat(future).isNotDone();
            PendingCheckpoint pendingCheckpoint =
                    context.coordinator.getPendingCheckpoints().values().iterator().next();
            assertThat(pendingCheckpoint.getProps().getCheckpointType())
                    .isEqualTo(CheckpointType.FULL_CHECKPOINT);

            context.acknowledge(pendingCheckpoint.getCheckpointID());
            assertThat(future.get(10, TimeUnit.SECONDS).getCheckpointID())
                    .isEqualTo(pendingCheckpoint.getCheckpointID());
        }
    }

