    @Test
    void testSavepointUsesSavepointLocationAndIsNotStoredAsCheckpoint() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerSavepoint(
                            "file:///savepoints", SavepointFormatType.CANONICAL);

            assertThat(future).isNotDone();
            long checkpointId = singlePendingCheckpointId(context);
            assertThat(
                            context.coordinator
                                    .getPendingCheckpoints()
                                    .get(checkpointId)
                                    .getProps()
                                    .isSavepoint())
                    .isTrue();

            context.acknowledge(checkpointId);

            CompletedCheckpoint savepoint = future.get(10, TimeUnit.SECONDS);
            assertThat(savepoint.getProperties().isSavepoint()).isTrue();
            assertThat(context.coordinator.getNumberOfRetainedSuccessfulCheckpoints()).isZero();
            assertThat(context.storageAccess.lastSavepointLocationId).isEqualTo(checkpointId);
            assertThat(context.storageAccess.lastSavepointTarget).isEqualTo("file:///savepoints");
        }
    }

