    @Test
    void testDeclineAbortsPendingCheckpoint() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerCheckpoint(false);
            long checkpointId = singlePendingCheckpointId(context);
            CheckpointException declineReason =
                    new CheckpointException(CheckpointFailureReason.CHECKPOINT_DECLINED);

            context.coordinator.receiveDeclineMessage(
                    new DeclineCheckpoint(
                            context.job, context.attemptId, checkpointId, declineReason),
                    "test-location");

            assertThat(future).isCompletedExceptionally();
            assertThat(checkpointFailure(future).getCheckpointFailureReason())
                    .isEqualTo(CheckpointFailureReason.CHECKPOINT_DECLINED);
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isZero();
            assertThat(context.coordinator.getNumQueuedRequests()).isZero();
            assertThat(context.storageLocation.disposeOnFailureCount).isEqualTo(1);
        }
    }

    @Test
    void testInvalidAndUnknownCheckpointMessagesAreHandled() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            assertThat(context.coordinator.receiveAcknowledgeMessage(null, "")).isFalse();
            context.coordinator.receiveDeclineMessage(null, "");
            assertThat(
                            context.coordinator.receiveAcknowledgeMessage(
                                    new AcknowledgeCheckpoint(new JobID(), context.attemptId, 42L),
                                    ""))
                    .isFalse();

            CheckpointException declineReason =
                    new CheckpointException(CheckpointFailureReason.CHECKPOINT_DECLINED);
            assertThatThrownBy(
                            () ->
                                    context.coordinator.receiveDeclineMessage(
                                            new DeclineCheckpoint(
                                                    new JobID(),
                                                    context.attemptId,
                                                    42L,
                                                    declineReason),
                                            ""))
                    .isInstanceOf(IllegalArgumentException.class)
                    .hasMessageContaining("Received DeclineCheckpoint message for job");

            assertThat(
                            context.coordinator.receiveAcknowledgeMessage(
                                    new AcknowledgeCheckpoint(context.job, context.attemptId, 42L),
                                    ""))
                    .isFalse();
            assertThat(context.statsTracker.lastIncompleteCheckpointId).isEqualTo(42L);
            assertThat(context.statsTracker.lastIncompleteAttemptId).isEqualTo(context.attemptId);
        }
    }

    @Test
    void testCheckpointExpiresWhenCancellerRuns() throws Exception {
        CheckpointCoordinatorConfiguration configuration =
                configuration().setCheckpointTimeout(1234L).build();
        try (TestContext context = new TestContext(configuration)) {
            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerCheckpoint(false);
            long checkpointId = singlePendingCheckpointId(context);
            assertThat(context.timer.getScheduledTaskCount()).isEqualTo(1);
            assertThat(context.timer.getLastDelayMillis()).isEqualTo(1234L);

            context.timer.runNextScheduledTask();

            assertThat(future).isCompletedExceptionally();
            assertThat(checkpointFailure(future).getCheckpointFailureReason())
                    .isEqualTo(CheckpointFailureReason.CHECKPOINT_EXPIRED);
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isZero();
            assertThat(context.coordinator.getRecentExpiredCheckpoints())
                    .containsExactly(checkpointId);

            assertThat(context.acknowledgeWithoutState(checkpointId)).isTrue();
            assertThat(context.coordinator.getNumberOfRetainedSuccessfulCheckpoints()).isZero();
        }
    }

    @Test
    void testQueuedTriggerRunsAfterPendingCheckpointIsAborted() throws Exception {
        CheckpointCoordinatorConfiguration configuration =
                configuration().setMaxConcurrentCheckpoints(1).build();
        try (TestContext context = new TestContext(configuration)) {
            CompletableFuture<CompletedCheckpoint> first =
                    context.coordinator.triggerCheckpoint(false);
            long firstId = singlePendingCheckpointId(context);

            CompletableFuture<CompletedCheckpoint> second =
                    context.coordinator.triggerCheckpoint(false);
            assertThat(second).isNotDone();
            assertThat(context.coordinator.getNumQueuedRequests()).isEqualTo(1);
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isEqualTo(1);

            context.coordinator.receiveDeclineMessage(
                    new DeclineCheckpoint(
                            context.job,
                            context.attemptId,
                            firstId,
                            new CheckpointException(CheckpointFailureReason.CHECKPOINT_DECLINED)),
                    "test-location");

            assertThat(first).isCompletedExceptionally();
            assertThat(context.coordinator.getNumQueuedRequests()).isZero();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isEqualTo(1);
            long secondId = singlePendingCheckpointId(context);
            assertThat(secondId).isNotEqualTo(firstId);

            context.acknowledge(secondId);
            assertThat(second.get(10, TimeUnit.SECONDS).getCheckpointID()).isEqualTo(secondId);
        }
    }

    @Test
    void testAbortPendingCheckpointsFailsAllInFlightRequests() throws Exception {
        CheckpointCoordinatorConfiguration configuration =
                configuration().setMaxConcurrentCheckpoints(2).build();
        try (TestContext context = new TestContext(configuration)) {
            CompletableFuture<CompletedCheckpoint> first =
                    context.coordinator.triggerCheckpoint(false);
            CompletableFuture<CompletedCheckpoint> second =
                    context.coordinator.triggerCheckpoint(false);
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isEqualTo(2);

            context.coordinator.abortPendingCheckpoints(
                    new CheckpointException(
                            CheckpointFailureReason.CHECKPOINT_COORDINATOR_SUSPEND));

            assertThat(first).isCompletedExceptionally();
            assertThat(checkpointFailure(first).getCheckpointFailureReason())
                    .isEqualTo(CheckpointFailureReason.CHECKPOINT_COORDINATOR_SUSPEND);
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isZero();
            assertThat(second).isCompletedExceptionally();
            assertThat(checkpointFailure(second).getCheckpointFailureReason())
                    .isEqualTo(CheckpointFailureReason.CHECKPOINT_COORDINATOR_SUSPEND);
        }
    }

    @Test
    void testShutdownAbortsInFlightCheckpointAndRejectsNewWork() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerCheckpoint(false);
            long checkpointId = singlePendingCheckpointId(context);

            context.coordinator.shutdown();

            assertThat(context.coordinator.isShutdown()).isTrue();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isZero();
            assertThat(future).isCompletedExceptionally();
            assertThat(checkpointFailure(future).getCheckpointFailureReason())
                    .isEqualTo(CheckpointFailureReason.CHECKPOINT_COORDINATOR_SHUTDOWN);

            assertThat(context.acknowledge(checkpointId)).isFalse();
            context.coordinator.receiveDeclineMessage(
                    new DeclineCheckpoint(
                            context.job,
                            context.attemptId,
                            checkpointId,
                            new CheckpointException(CheckpointFailureReason.CHECKPOINT_DECLINED)),
                    "test-location");

            CompletableFuture<CompletedCheckpoint> afterShutdown =
                    context.coordinator.triggerCheckpoint(false);
            assertThat(afterShutdown).isCompletedExceptionally();
            assertThat(checkpointFailure(afterShutdown).getCheckpointFailureReason())
                    .isEqualTo(CheckpointFailureReason.CHECKPOINT_COORDINATOR_SHUTDOWN);
        }
    }

    @Test
    void testActiveTriggerDelayRespectsMinimumPauseAndPendingCheckpoints() throws Exception {
        CheckpointCoordinatorConfiguration configuration =
                configuration().setMinPauseBetweenCheckpoints(1000L).build();
        try (TestContext context = new TestContext(configuration)) {
            assertThat(context.coordinator.getActiveCheckpointTriggerDelay())
                    .contains(Duration.ofMillis(1000));

            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerCheckpoint(false);
            assertThat(context.coordinator.getActiveCheckpointTriggerDelay()).isEmpty();

            context.acknowledge(singlePendingCheckpointId(context));
            future.get(10, TimeUnit.SECONDS);
            assertThat(context.coordinator.getActiveCheckpointTriggerDelay())
                    .contains(Duration.ofMillis(1000));

            context.clock.advanceTime(400L, TimeUnit.MILLISECONDS);
            assertThat(context.coordinator.getActiveCheckpointTriggerDelay())
                    .contains(Duration.ofMillis(600));

            context.clock.advanceTime(700L, TimeUnit.MILLISECONDS);
            assertThat(context.coordinator.getActiveCheckpointTriggerDelay())
                    .contains(Duration.ZERO);
        }
    }

