    @Test
    void testPeriodicSchedulerStartStopAndConfiguration() throws Exception {
        try (TestContext context =
                new TestContext(configuration().setMinPauseBetweenCheckpoints(0L).build())) {
            assertThat(context.coordinator.isPeriodicCheckpointingConfigured()).isTrue();
            assertThat(context.coordinator.isPeriodicCheckpointingStarted()).isFalse();

            context.coordinator.startCheckpointScheduler();
            assertThat(context.coordinator.isPeriodicCheckpointingStarted()).isTrue();
            assertThat(context.timer.getScheduledTaskCount()).isEqualTo(1);

            context.timer.runNextScheduledTask();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isEqualTo(1);

            context.coordinator.stopCheckpointScheduler();
            assertThat(context.coordinator.isPeriodicCheckpointingStarted()).isFalse();
            assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isZero();
        }
    }

