    @Test
    void testActivatorDeactivatorIsCachedAndStopsSchedulerOnJobStatusChange() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            context.coordinator.startCheckpointScheduler();

            CheckpointCoordinatorDeActivator activator =
                    context.coordinator.createActivatorDeactivator(true);
            assertThat(context.coordinator.createActivatorDeactivator(true)).isSameAs(activator);

            activator.jobStatusChanges(context.job, JobStatus.RUNNING, 0L);
            assertThat(context.coordinator.isPeriodicCheckpointingStarted()).isTrue();

            activator.jobStatusChanges(context.job, JobStatus.FAILED, 1L);
            assertThat(context.coordinator.isPeriodicCheckpointingStarted()).isFalse();
        }
    }

    @Test
    void testRestoreLatestCheckpointedState() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            CompletableFuture<CompletedCheckpoint> future =
                    context.coordinator.triggerCheckpoint(false);
            long checkpointId = singlePendingCheckpointId(context);
            context.acknowledge(checkpointId);
            future.get(10, TimeUnit.SECONDS);

            OptionalLong restored =
                    context.coordinator.restoreLatestCheckpointedStateToSubtasks(emptySet());
            assertThat(restored).hasValue(checkpointId);
            assertThat(context.coordinator.restoreLatestCheckpointedStateToAll(emptySet(), false))
                    .isTrue();
            assertThat(context.coordinator.restoreInitialCheckpointIfPresent(emptySet(), false))
                    .isTrue();

            assertThat(context.statsTracker.restoredCheckpointIds)
                    .containsExactly(checkpointId, checkpointId, checkpointId);
        }
    }

