    @Test
    void testMetricsReportingIsDelegatedToTracker() throws Exception {
        try (TestContext context = new TestContext(configuration().build())) {
            CheckpointMetrics metrics = new CheckpointMetrics();
            SubTaskInitializationMetrics initMetrics =
                    new SubTaskInitializationMetrics(
                            1L,
                            2L,
                            Collections.singletonMap("key", 1L),
                            InitializationStatus.COMPLETED);

            context.coordinator.reportCheckpointMetrics(7L, context.attemptId, metrics);
            context.coordinator.reportInitializationMetrics(context.attemptId, initMetrics);

            assertThat(context.statsTracker.lastIncompleteCheckpointId).isEqualTo(7L);
            assertThat(context.statsTracker.lastIncompleteAttemptId).isEqualTo(context.attemptId);
            assertThat(context.statsTracker.lastIncompleteMetrics).isSameAs(metrics);
            assertThat(context.statsTracker.lastInitializationAttemptId)
                    .isEqualTo(context.attemptId);
            assertThat(context.statsTracker.lastInitializationMetrics).isSameAs(initMetrics);
        }
    }

