    private static CheckpointCoordinatorConfiguration.CheckpointCoordinatorConfigurationBuilder
            configuration() {
        return CheckpointCoordinatorConfiguration.builder()
                .setCheckpointInterval(1000L)
                .setCheckpointIntervalDuringBacklog(100L)
                .setCheckpointTimeout(60000L)
                .setMinPauseBetweenCheckpoints(10L)
                .setMaxConcurrentCheckpoints(1)
                .setTolerableCheckpointFailureNumber(10);
    }

    private static long singlePendingCheckpointId(TestContext context) {
        assertThat(context.coordinator.getNumberOfPendingCheckpoints()).isEqualTo(1);
        return context.coordinator.getPendingCheckpoints().keySet().iterator().next();
    }

    private static CheckpointException checkpointFailure(CompletableFuture<?> future) {
        try {
            future.get(10, TimeUnit.SECONDS);
            fail("The future should have completed exceptionally.");
            return null;
        } catch (ExecutionException e) {
            assertThat(e.getCause()).isInstanceOf(CheckpointException.class);
            return (CheckpointException) e.getCause();
        } catch (Exception e) {
            throw new AssertionError("Unexpected exception while waiting for failure", e);
        }
    }

    private static TestCheckpointPlan createPlan(Execution execution) {
        return new TestCheckpointPlan(execution);
    }

    private static final class TestContext implements AutoCloseable {
        private final JobID job = new JobID();
        private final ExecutionAttemptID attemptId = ExecutionAttemptID.randomId();
        private final ManualClock clock = new ManualClock();
        private final TestingScheduledExecutor timer = new TestingScheduledExecutor();
        private final StandaloneCompletedCheckpointStore store =
                new StandaloneCompletedCheckpointStore(2);
        private final CheckpointsCleaner checkpointsCleaner = new CheckpointsCleaner(false);
        private final TestingCheckpointStatsTracker statsTracker =
                new TestingCheckpointStatsTracker();
        private final TestingCheckpointStorageLocation storageLocation =
                new TestingCheckpointStorageLocation();
        private final TestingCheckpointStorageAccess storageAccess =
                new TestingCheckpointStorageAccess(storageLocation);
        private final TestingCheckpointStorage storage =
                new TestingCheckpointStorage(storageAccess, null);
        private final ExecutionVertex executionVertex;
        private final ExecutionJobVertex executionJobVertex;
        private final Execution execution;
        private final CheckpointCoordinator coordinator;
        private int triggerCheckpointCalls;
        private int triggerSynchronousSavepointCalls;

        private TestContext(CheckpointCoordinatorConfiguration configuration) {
            executionVertex = org.mockito.Mockito.mock(ExecutionVertex.class);
            executionJobVertex = org.mockito.Mockito.mock(ExecutionJobVertex.class);
            org.mockito.Mockito.when(executionVertex.getJobVertex()).thenReturn(executionJobVertex);
            org.mockito.Mockito.when(executionJobVertex.getJobVertexId())
                    .thenReturn(new JobVertexID());
            org.mockito.Mockito.when(executionJobVertex.getParallelism()).thenReturn(1);
            execution = createExecution();
            try {
                coordinator =
                        new CheckpointCoordinator(
                                job,
                                configuration,
                                emptyList(),
                                new StandaloneCheckpointIDCounter(),
                                store,
                                storage,
                                Runnable::run,
                                checkpointsCleaner,
                                timer,
                                new CheckpointFailureManager(
                                        CheckpointFailureManager.UNLIMITED_TOLERABLE_FAILURE_NUMBER,
                                        new NoOpFailJobCallback()),
                                () -> CompletableFuture.completedFuture(createPlan(execution)),
                                clock,
                                statsTracker,
                                VertexFinishedStateChecker::new);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        private Execution createExecution() {
            Execution mockedExecution = org.mockito.Mockito.mock(Execution.class);
            org.mockito.Mockito.when(mockedExecution.getAttemptId()).thenReturn(attemptId);
            org.mockito.Mockito.when(mockedExecution.getVertex()).thenReturn(executionVertex);
            org.mockito.Mockito.when(
                            mockedExecution.triggerCheckpoint(
                                    org.mockito.ArgumentMatchers.anyLong(),
                                    org.mockito.ArgumentMatchers.anyLong(),
                                    org.mockito.ArgumentMatchers.any()))
                    .thenAnswer(
                            ignored -> {
                                ++triggerCheckpointCalls;
                                return CompletableFuture.completedFuture(Acknowledge.get());
                            });
            org.mockito.Mockito.when(
                            mockedExecution.triggerSynchronousSavepoint(
                                    org.mockito.ArgumentMatchers.anyLong(),
                                    org.mockito.ArgumentMatchers.anyLong(),
                                    org.mockito.ArgumentMatchers.any()))
                    .thenAnswer(
                            ignored -> {
                                ++triggerSynchronousSavepointCalls;
                                return CompletableFuture.completedFuture(Acknowledge.get());
                            });
            return mockedExecution;
        }

        private boolean acknowledge(long checkpointId) throws CheckpointException {
            return coordinator.receiveAcknowledgeMessage(
                    new AcknowledgeCheckpoint(
                            job,
                            attemptId,
                            checkpointId,
                            new CheckpointMetrics(),
                            TaskStateSnapshot.FINISHED_ON_RESTORE),
                    "test-location");
        }

        private boolean acknowledgeWithoutState(long checkpointId) throws CheckpointException {
            return coordinator.receiveAcknowledgeMessage(
                    new AcknowledgeCheckpoint(job, attemptId, checkpointId), "test-location");
        }

        @Override
        public void close() throws Exception {
            if (!coordinator.isShutdown()) {
                coordinator.shutdown();
            }
        }
    }

    private static final class TestingMasterHook implements MasterTriggerRestoreHook<Void> {
        private final String identifier;
        private int closeCount;

        private TestingMasterHook(String identifier) {
            this.identifier = identifier;
        }

        @Override
        public String getIdentifier() {
            return identifier;
        }

        @Override
        public CompletableFuture<Void> triggerCheckpoint(
                long checkpointId, long timestamp, Executor executor) {
            return CompletableFuture.completedFuture(null);
