    @Test
    void testMasterStateRoundTrip() throws Exception {
        final MasterState state = new MasterState("the-master-state", new byte[] {1, 2, 3}, 42);

        final byte[] data =
                TestSerializer.toBytes(
                        dos -> TestSerializer.INSTANCE.serializeMasterState(state, dos));
