    @Test
    void testDeserializeMasterStateRejectsNonPositiveLength() throws Exception {
        for (int length : new int[] {0, -17}) {
            final byte[] data =
                    TestSerializer.toBytes(
                            dos -> {
                                dos.writeInt(MASTER_STATE_MAGIC_NUMBER);
                                dos.writeInt(length);
                            });

            assertThatThrownBy(
                            () ->
                                    TestSerializer.INSTANCE.deserializeMasterState(
                                            TestSerializer.input(data)))
                    .as("length %s", length)
                    .isInstanceOf(IOException.class)
                    .hasMessageContaining("found zero or negative length");
        }
    }

    @Test
    void testDeserializeMasterStateRejectsTrailingBytes() throws Exception {
        final byte[] payload =
                TestSerializer.toBytes(
                        dos -> {
                            dos.writeInt(1); // version
                            dos.writeUTF("master"); // name
                            dos.writeInt(2); // number of payload bytes
                            dos.write(new byte[] {7, 7});
                            dos.writeByte(0xAB); // trailing garbage
                        });
        final byte[] data =
                TestSerializer.toBytes(
                        dos -> {
                            dos.writeInt(MASTER_STATE_MAGIC_NUMBER);
                            dos.writeInt(payload.length);
                            dos.write(payload);
                        });

        assertThatThrownBy(
                        () ->
                                TestSerializer.INSTANCE.deserializeMasterState(
                                        TestSerializer.input(data)))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("found trailing bytes in master state");
    }

