    @Test
    void testMetadataRoundTrip() throws Exception {
        final List<MasterState> masterStates =
                Arrays.asList(
                        new MasterState("first", new byte[] {1}, 1),
                        new MasterState("second", new byte[] {2, 3}, 2));

        final OperatorState firstOperator = createOperatorState("op-uid-1", "op-name-1", 2, 4);
        firstOperator.putState(0, createSubtaskState());
        firstOperator.putState(1, OperatorSubtaskState.builder().build());

        final OperatorState secondOperator = createOperatorState("op-uid-2", "op-name-2", 1, 1);

        final CheckpointMetadata metadata =
                new CheckpointMetadata(
                        4711L, Arrays.asList(firstOperator, secondOperator), masterStates);

        final byte[] data =
                TestSerializer.toBytes(
                        dos ->
                                TestSerializer.INSTANCE.serializeMetadata(
                                        metadata, dos, TestSerializer.withoutExclusiveDir()));
        final CheckpointMetadata deserialized =
                TestSerializer.fromBytes(
                        data, dis -> TestSerializer.INSTANCE.deserializeMetadata(dis, null));

        assertThat(deserialized.getCheckpointId()).isEqualTo(4711L);

        assertThat(deserialized.getMasterStates()).hasSize(2);
        final List<MasterState> deserializedMasterStates =
                new ArrayList<>(deserialized.getMasterStates());
        assertThat(deserializedMasterStates.get(0).name()).isEqualTo("first");
        assertThat(deserializedMasterStates.get(1).bytes()).containsExactly(2, 3);

        assertThat(deserialized.getOperatorStates()).hasSize(2);
        final List<OperatorState> deserializedOperators =
                new ArrayList<>(deserialized.getOperatorStates());

        final OperatorState operator1 = deserializedOperators.get(0);
        assertThat(operator1.getOperatorName()).hasValue("op-name-1");
        assertThat(operator1.getOperatorUid()).hasValue("op-uid-1");
        assertThat(operator1.getParallelism()).isEqualTo(2);
        assertThat(operator1.getMaxParallelism()).isEqualTo(4);
        assertThat(operator1.getNumberCollectedStates()).isEqualTo(2);
        assertThat(operator1.getState(0).getManagedKeyedState().iterator().next())
                .isEqualTo(createSubtaskState().getManagedKeyedState().iterator().next());
        assertThat(operator1.getState(1).getManagedOperatorState()).isEmpty();

        final OperatorState operator2 = deserializedOperators.get(1);
        assertThat(operator2.getOperatorUid()).hasValue("op-uid-2");
        assertThat(operator2.getParallelism()).isEqualTo(1);
        assertThat(operator2.getNumberCollectedStates()).isZero();
    }

