    @Test
    void testDeserializeMetadataResolvesRelativeHandlesAgainstExternalPointer() throws Exception {
        final String pointer = createCheckpointDirectory().toString();
        final Path exclusiveDir =
                new MetadataV2V3SerializerBase.DeserializationContext(pointer)
                        .getExclusiveDirPath();

        final RelativeFileStateHandle relativeHandle =
                new RelativeFileStateHandle(
                        new Path(exclusiveDir, "kv/keyed-state"), "kv/keyed-state", 32L);
        final KeyGroupRangeOffsets offsets = new KeyGroupRangeOffsets(KeyGroupRange.of(0, 1));
        offsets.setKeyGroupOffset(0, 0L);
        offsets.setKeyGroupOffset(1, 32L);

        final OperatorState operatorState =
                createOperatorState("relative-uid", "relative-op", 1, 1);
        operatorState.putState(
                0,
                OperatorSubtaskState.builder()
                        .setManagedKeyedState(
                                KeyGroupsStateHandle.restore(
                                        offsets, relativeHandle, new StateHandleID("relative")))
                        .build());

        final byte[] data =
                TestSerializer.toBytes(
                        dos ->
                                TestSerializer.INSTANCE.serializeMetadata(
                                        new CheckpointMetadata(
                                                3L,
                                                Collections.singletonList(operatorState),
                                                Collections.emptyList()),
                                        dos,
                                        MetadataV2V3SerializerBase.SerializationContext
                                                .withExclusiveDir(exclusiveDir)));

        final CheckpointMetadata deserialized =
                TestSerializer.fromBytes(
                        data, dis -> TestSerializer.INSTANCE.deserializeMetadata(dis, pointer));

        final OperatorState deserializedOperator =
                new ArrayList<>(deserialized.getOperatorStates()).get(0);
        final KeyedStateHandle deserializedKeyedState =
                deserializedOperator.getState(0).getManagedKeyedState().iterator().next();

        assertThat(deserializedKeyedState).isInstanceOf(KeyGroupsStateHandle.class);
        final StreamStateHandle delegate =
                ((KeyGroupsStateHandle) deserializedKeyedState).getDelegateStateHandle();
        assertThat(delegate).isInstanceOf(RelativeFileStateHandle.class);
        assertThat(((RelativeFileStateHandle) delegate).getRelativePath())
                .isEqualTo("kv/keyed-state");
        assertThat(delegate).isEqualTo(relativeHandle);
        // the relative reference was resolved against the checkpoint directory of the pointer
        assertThat(((RelativeFileStateHandle) delegate).getFilePath())
                .isEqualTo(new Path(exclusiveDir, "kv/keyed-state"));
    }

