    @Test
    void testIncrementalRemoteKeyedStateHandleRoundTrip() throws Exception {
        final UUID backendIdentifier = UUID.randomUUID();
        final KeyGroupRange range = KeyGroupRange.of(0, 1);
        final List<HandleAndLocalPath> sharedState =
                Collections.singletonList(
                        HandleAndLocalPath.of(
                                createByteStreamStateHandle("shared"), "shared-path"));
        final List<HandleAndLocalPath> privateState =
                Collections.singletonList(
                        HandleAndLocalPath.of(
                                createByteStreamStateHandle("private"), "private-path"));
        final IncrementalRemoteKeyedStateHandle handle =
                IncrementalRemoteKeyedStateHandle.restore(
                        backendIdentifier,
                        range,
                        11L,
                        sharedState,
                        privateState,
                        createByteStreamStateHandle("meta"),
                        1234L,
                        new StateHandleID("incremental-id"));

        final byte[] data =
                TestSerializer.keyedHandleBytes(handle, TestSerializer.withoutExclusiveDir());

        assertThat(data[0]).isEqualTo(INCREMENTAL_KEY_GROUPS_HANDLE_V2);
        final KeyedStateHandle deserialized = TestSerializer.keyedHandle(data, null);

        assertThat(deserialized).isInstanceOf(IncrementalRemoteKeyedStateHandle.class);
        final IncrementalRemoteKeyedStateHandle deserializedHandle =
                (IncrementalRemoteKeyedStateHandle) deserialized;
        assertThat(deserializedHandle.getBackendIdentifier()).isEqualTo(backendIdentifier);
        assertThat(deserializedHandle.getKeyGroupRange()).isEqualTo(range);
        assertThat(deserializedHandle.getCheckpointId()).isEqualTo(11L);
        assertThat(deserializedHandle.getCheckpointedSize()).isEqualTo(1234L);
        assertThat(deserializedHandle.getStateHandleId())
                .isEqualTo(new StateHandleID("incremental-id"));
        assertThat(deserializedHandle.getMetaDataStateHandle())
                .isEqualTo(createByteStreamStateHandle("meta"));
        assertThat(deserializedHandle.getSharedState()).hasSize(1);
        assertThat(deserializedHandle.getSharedState().get(0).getLocalPath())
                .isEqualTo("shared-path");
        assertThat(deserializedHandle.getPrivateState()).hasSize(1);
        assertThat(deserializedHandle.getPrivateState().get(0).getLocalPath())
                .isEqualTo("private-path");
    }

