    private static final byte[] TEST_DATA = new byte[] {1, 2, 3, 4};

    private static ByteStreamStateHandle createByteStreamStateHandle(String handleName) {
        return new ByteStreamStateHandle(handleName, TEST_DATA);
    }

    private static KeyGroupsStateHandle createKeyGroupsStateHandle(
            int startKeyGroup, int endKeyGroup) {
        final KeyGroupRange range = KeyGroupRange.of(startKeyGroup, endKeyGroup);
        final KeyGroupRangeOffsets offsets = new KeyGroupRangeOffsets(range);
        long offset = 0L;
        for (int keyGroup : range) {
            offsets.setKeyGroupOffset(keyGroup, offset);
            offset += 100L;
        }
        return KeyGroupsStateHandle.restore(
                offsets,
                createByteStreamStateHandle("keyed-state"),
                new StateHandleID("keyed-state-id"));
    }

    private static OperatorStreamStateHandle createOperatorStreamStateHandle(String name) {
        final Map<String, OperatorStateHandle.StateMetaInfo> partitions = new LinkedHashMap<>();
        partitions.put(
                name,
                new OperatorStateHandle.StateMetaInfo(
                        new long[] {0L}, OperatorStateHandle.Mode.SPLIT_DISTRIBUTE));
        return new OperatorStreamStateHandle(partitions, createByteStreamStateHandle(name));
    }

    private static OperatorSubtaskState createSubtaskState() {
        return OperatorSubtaskState.builder()
                .setManagedOperatorState(createOperatorStreamStateHandle("managed-operator"))
                .setRawOperatorState(createOperatorStreamStateHandle("raw-operator"))
                .setManagedKeyedState(createKeyGroupsStateHandle(0, 1))
                .setRawKeyedState(createKeyGroupsStateHandle(2, 3))
                .build();
    }

    private static OperatorState createOperatorState(
            String operatorUid, String operatorName, int parallelism, int maxParallelism) {
        return new OperatorState(
