     */
    private static final class TestSerializer extends MetadataV2V3SerializerBase {

        private static final TestSerializer INSTANCE = new TestSerializer();

        @Override
        protected void serializeOperatorState(
                OperatorState operatorState, DataOutputStream dos, SerializationContext context)
                throws IOException {
            dos.writeUTF(operatorState.getOperatorName().orElse(""));
            dos.writeUTF(operatorState.getOperatorUid().orElse(""));
            dos.writeInt(operatorState.getParallelism());
            dos.writeInt(operatorState.getMaxParallelism());
            dos.writeInt(operatorState.getNumberCollectedStates());
            for (Map.Entry<Integer, OperatorSubtaskState> subtaskState :
                    operatorState.getSubtaskStates().entrySet()) {
                dos.writeInt(subtaskState.getKey());
                serializeSubtaskState(subtaskState.getValue(), dos, context);
            }
        }

        @Override
        protected OperatorState deserializeOperatorState(
                DataInputStream dis, DeserializationContext context) throws IOException {
            final String operatorName = dis.readUTF();
            final String operatorUid = dis.readUTF();
            final int parallelism = dis.readInt();
            final int maxParallelism = dis.readInt();
            final int numberOfStates = dis.readInt();

            final OperatorState operatorState =
                    new OperatorState(
                            operatorName.isEmpty() ? null : operatorName,
                            operatorUid.isEmpty() ? null : operatorUid,
                            new OperatorID(),
                            parallelism,
                            maxParallelism);

            for (int i = 0; i < numberOfStates; i++) {
                final int subtaskIndex = dis.readInt();
                operatorState.putState(subtaskIndex, deserializeSubtaskState(dis, context));
            }
            return operatorState;
        }

