        @FunctionalInterface
        private interface ThrowingWriter {
            void write(DataOutputStream dos) throws IOException;
        }

        @FunctionalInterface
        private interface ThrowingReader<T> {
            T read(DataInputStream dis) throws IOException;
        }

        static DataOutputStream output() {
            return new DataOutputStream(new ByteArrayOutputStream());
        }

        static DataInputStream input(byte[] data) {
            return new DataInputStream(new ByteArrayInputStream(data));
        }

        static byte[] toBytes(ThrowingWriter writer) throws IOException {
            final ByteArrayOutputStream baos = new ByteArrayOutputStream();
            try (DataOutputStream dos = new DataOutputStream(baos)) {
                writer.write(dos);
            }
            return baos.toByteArray();
        }

        static <T> T fromBytes(byte[] data, ThrowingReader<T> reader) throws IOException {
            try (DataInputStream dis = input(data)) {
                final T result = reader.read(dis);
                assertThat(dis.available()).as("bytes left unread after deserialization").isZero();
                return result;
            }
        }

        static SerializationContext withoutExclusiveDir() {
            return SerializationContext.withoutExclusiveDir();
        }

        static byte[] keyedHandleBytes(KeyedStateHandle handle, SerializationContext context)
                throws IOException {
            return toBytes(dos -> serializeKeyedStateHandle(handle, dos, context));
        }

        static KeyedStateHandle keyedHandle(byte[] data, @Nullable DeserializationContext context)
                throws IOException {
            return fromBytes(data, dis -> deserializeKeyedStateHandle(dis, context));
        }

        static byte[] streamHandleBytes(StreamStateHandle handle, SerializationContext context)
                throws IOException {
            return toBytes(dos -> serializeStreamStateHandle(handle, dos, context));
        }

        static StreamStateHandle streamHandle(byte[] data, @Nullable DeserializationContext context)
                throws IOException {
            return fromBytes(data, dis -> deserializeStreamStateHandle(dis, context));
        }

        static byte[] operatorHandleBytes(OperatorStateHandle handle, SerializationContext context)
                throws IOException {
            return toBytes(dos -> INSTANCE.serializeOperatorStateHandle(handle, dos, context));
        }

        static OperatorStateHandle operatorHandle(
                byte[] data, @Nullable DeserializationContext context) throws IOException {
            return fromBytes(data, dis -> INSTANCE.deserializeOperatorStateHandle(dis, context));
        }
    }
