import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.concurrent.LinkedBlockingQueue;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link MutableHashTable}. */
class MutableHashTableTests {

    private static final int MIN_MEMORY_SEGMENTS = 33;
    private static final int SEGMENT_SIZE = 1024;

    private CountingIOManagerAsync ioManager;
    private final List<MutableHashTable<Integer, Integer>> openTables = new ArrayList<>();

    @BeforeEach
    void setUp(@TempDir Path tempDir) {
        ioManager = new CountingIOManagerAsync(tempDir.toString());
    }

    @AfterEach
    void tearDown() throws Exception {
        for (MutableHashTable<Integer, Integer> table : openTables) {
            table.close();
        }
        ioManager.close();
    }

    @Test
    void constructorValidatesMemoryConfiguration() {
        assertThrows(
                NullPointerException.class, () -> newHashTable(null, IntSerializer.INSTANCE, true));

        assertThrows(
                IllegalArgumentException.class,
                () ->
                        newHashTable(
                                createMemory(MIN_MEMORY_SEGMENTS - 1, SEGMENT_SIZE),
                                IntSerializer.INSTANCE,
                                true));

        assertThrows(
                IllegalArgumentException.class,
                () ->
                        newHashTable(
                                createMemory(MIN_MEMORY_SEGMENTS, 300),
                                IntSerializer.INSTANCE,
                                true));

        assertThrows(
                IllegalArgumentException.class,
                () ->
                        newHashTable(
                                createMemory(MIN_MEMORY_SEGMENTS, 64),
                                IntSerializer.INSTANCE,
                                true));
    }

    @Test
    void computesNumberOfWriteBehindBuffers() {
        assertAll(
                () -> assertEquals(0, MutableHashTable.getNumWriteBehindBuffers(16)),
                () -> assertEquals(1, MutableHashTable.getNumWriteBehindBuffers(32)),
                () -> assertEquals(1, MutableHashTable.getNumWriteBehindBuffers(64)),
                () -> assertEquals(2, MutableHashTable.getNumWriteBehindBuffers(128)),
                () -> assertEquals(2, MutableHashTable.getNumWriteBehindBuffers(256)),
                () -> assertEquals(3, MutableHashTable.getNumWriteBehindBuffers(1024)),
                () -> assertEquals(6, MutableHashTable.getNumWriteBehindBuffers(1 << 20)));
    }

    @Test
    void computesInitialPartitioningFanOut() {
        assertAll(
                () -> assertEquals(10, MutableHashTable.getPartitioningFanOutNoEstimates(0)),
                () -> assertEquals(10, MutableHashTable.getPartitioningFanOutNoEstimates(99)),
                () -> assertEquals(10, MutableHashTable.getPartitioningFanOutNoEstimates(109)),
                () -> assertEquals(11, MutableHashTable.getPartitioningFanOutNoEstimates(110)),
                () -> assertEquals(127, MutableHashTable.getPartitioningFanOutNoEstimates(1270)),
                () -> assertEquals(127, MutableHashTable.getPartitioningFanOutNoEstimates(100000)));
    }

    @Test
    void computesInitialTableSizeAndSaturatesOnOverflow() {
        assertAll(
                () -> assertEquals(4, MutableHashTable.getInitialTableSize(1, 1024, 10, 4)),
                () -> assertEquals(67, MutableHashTable.getInitialTableSize(33, 1024, 10, 12)),
                () ->
                        assertEquals(
                                Integer.MAX_VALUE,
                                MutableHashTable.getInitialTableSize(
                                        Integer.MAX_VALUE, 1 << 20, 10, 1)));
    }

    @Test
    void assignsBucketsToPartitions() {
        assertAll(
                () -> assertEquals(0, MutableHashTable.assignPartition(10, (byte) 10)),
                () -> assertEquals(3, MutableHashTable.assignPartition(13, (byte) 10)),
                () -> assertEquals(7, MutableHashTable.assignPartition(7, (byte) 127)));
    }

    @Test
    void hashesRecordsDifferentlyForEachRecursionLevel() {
        assertAll(
                () -> assertEquals(1018971279, MutableHashTable.hash(42, 0)),
                () -> assertEquals(358296722, MutableHashTable.hash(42, 1)),
                () -> assertEquals(993045052, MutableHashTable.hash(42, 3)),
                () -> assertNotEquals(MutableHashTable.hash(42, 0), MutableHashTable.hash(42, 2)),
                () -> assertTrue(MutableHashTable.hash(Integer.MIN_VALUE, 0) >= 0),
                () -> assertTrue(MutableHashTable.hash(Integer.MAX_VALUE, 3) >= 0));
    }

    @Test
    void exposesConfiguredProbeSideComparator() {
        TypeComparator<Integer> probeComparator = new IntComparator(true);
        MutableHashTable<Integer, Integer> table =
                new MutableHashTable<>(
                        IntSerializer.INSTANCE,
                        IntSerializer.INSTANCE,
                        new IntComparator(true),
                        probeComparator,
                        new SameTypePairComparator<>(new IntComparator(true)),
                        createMemory(MIN_MEMORY_SEGMENTS, SEGMENT_SIZE),
                        ioManager,
                        true);
        openTables.add(table);

        assertSame(probeComparator, table.getProbeSideComparator());
        assertEquals(17, table.getProbeSideComparator().hash(17));
    }

    @Test
    void nextSegmentLendsAnAvailableMemorySegment() throws IOException {
        List<MemorySegment> memory = createMemory(MIN_MEMORY_SEGMENTS, SEGMENT_SIZE);
        MutableHashTable<Integer, Integer> table =
                newHashTable(memory, IntSerializer.INSTANCE, true);
        openTables.add(table);

        MemorySegment last = memory.get(memory.size() - 1);
        assertSame(last, table.nextSegment());
        assertEquals(MIN_MEMORY_SEGMENTS - 1, table.getFreedMemory().size());
    }

    @Test
    void inMemoryLookupReturnsAllMatchingBuildRecords() throws Exception {
        MutableHashTable<Integer, Integer> table =
                openTable(Arrays.asList(1, 2, 2, 3, 3, 3), Collections.emptyList());

        assertEquals(Arrays.asList(2, 2), collectAndSort(table.getMatchesFor(2)));
        assertEquals(Arrays.asList(3, 3, 3), collectAndSort(table.getMatchesFor(3)));
        assertTrue(collect(table.getMatchesFor(4)).isEmpty());
    }

    @Test
    void lookupTraversesOverflowBucketsForManyDuplicateKeys() throws Exception {
        List<Integer> build = new ArrayList<>();
        for (int i = 0; i < 25; i++) {
            build.add(7);
        }
        MutableHashTable<Integer, Integer> table = openTable(build, Collections.emptyList());

        assertEquals(Collections.nCopies(25, 7), collectAndSort(table.getMatchesFor(7)));
        assertTrue(collect(table.getMatchesFor(8)).isEmpty());
    }

    @Test
    void iterationExposesEachProbeRecordAndItsMatches() throws Exception {
        MutableHashTable<Integer, Integer> table =
                openTable(Arrays.asList(10, 20, 20, 30), Arrays.asList(20, 999, 10));

        List<Integer> probes = new ArrayList<>();
        List<List<Integer>> matches = new ArrayList<>();
        while (table.nextRecord()) {
            probes.add(table.getCurrentProbeRecord());
            matches.add(collectAndSort(table.getBuildSideIterator()));
        }

        assertEquals(Arrays.asList(20, 999, 10), probes);
        assertEquals(
                Arrays.asList(Arrays.asList(20, 20), Collections.emptyList(), Arrays.asList(10)),
                matches);
        assertFalse(table.nextRecord());
    }

    @Test
    void buildOuterJoinEmitsEachUnmatchedBuildRecordOnce() throws Exception {
        MutableHashTable<Integer, Integer> table = newTable(true);
        table.open(iterator(Arrays.asList(1, 2, 2, 3, 4)), iterator(Arrays.asList(2, 7)), true);

        List<Integer> probes = new ArrayList<>();
        List<List<Integer>> matches = new ArrayList<>();
        List<Integer> unmatched = new ArrayList<>();
        while (table.nextRecord()) {
            Integer probe = table.getCurrentProbeRecord();
            probes.add(probe);
            if (probe == null) {
                unmatched.addAll(collect(table.getBuildSideIterator()));
            } else {
                matches.add(collectAndSort(table.getBuildSideIterator()));
            }
        }

        assertEquals(Arrays.asList(2, 7, null), probes);
        assertEquals(Arrays.asList(Arrays.asList(2, 2), Collections.emptyList()), matches);
        Collections.sort(unmatched);
        assertEquals(Arrays.asList(1, 3, 4), unmatched);
    }

    @Test
    void closeReturnsAllMemoryAndRejectsAccessWhileOpen() throws Exception {
        List<MemorySegment> memory = createMemory(MIN_MEMORY_SEGMENTS, SEGMENT_SIZE);
        MutableHashTable<Integer, Integer> table =
                newHashTable(memory, IntSerializer.INSTANCE, true);
        openTables.add(table);

        assertEquals(MIN_MEMORY_SEGMENTS, table.getFreedMemory().size());
        table.open(iterator(Arrays.asList(5)), iterator(Collections.emptyList()));
        assertThrows(IllegalStateException.class, table::getFreedMemory);

        table.close();
        assertEquals(MIN_MEMORY_SEGMENTS, table.getFreedMemory().size());
        assertEquals(MIN_MEMORY_SEGMENTS, new HashSet<>(table.getFreedMemory()).size());

        table.close();
        assertEquals(MIN_MEMORY_SEGMENTS, table.getFreedMemory().size());
    }

    @Test
    void openCannotBeCalledTwiceButTableCanBeReusedAfterClose() throws Exception {
        MutableHashTable<Integer, Integer> table = newTable(true);
        table.open(iterator(Arrays.asList(5)), iterator(Collections.emptyList()));

        assertThrows(
                IllegalStateException.class,
                () -> table.open(iterator(Arrays.asList(6)), iterator(Collections.emptyList())));

        table.close();
        table.open(iterator(Arrays.asList(9)), iterator(Collections.emptyList()));

        assertEquals(Collections.singletonList(9), collect(table.getMatchesFor(9)));
        assertTrue(collect(table.getMatchesFor(5)).isEmpty());
    }

    @Test
    void spilledJoinWithBloomFilterReturnsAllMatches() throws Exception {
        assertSpilledJoinMatches(true);
    }

    @Test
    void spilledJoinWithoutBloomFilterReturnsAllMatches() throws Exception {
        assertSpilledJoinMatches(false);
    }

    private void assertSpilledJoinMatches(boolean useBloomFilters) throws Exception {
        List<Integer> build = new ArrayList<>();
        List<Integer> probe = new ArrayList<>();
        for (int i = 0; i < 3000; i++) {
            build.add(i % 500);
        }
        for (int i = 0; i < 1500; i += 3) {
            probe.add(i % 500);
        }
        probe.add(10000);

        MutableHashTable<Integer, Integer> table = newTable(useBloomFilters);
        table.open(iterator(build), iterator(probe));

        List<Integer> expectedProbes = new ArrayList<>(probe);
        List<Integer> actualProbes = new ArrayList<>();
        List<Integer> allMatches = new ArrayList<>();
        while (table.nextRecord()) {
            actualProbes.add(table.getCurrentProbeRecord());
            allMatches.addAll(collect(table.getBuildSideIterator()));
        }

        // Probe records may be emitted in partition order after spilling. The unmatched
        // probe may also be discarded by a bloom filter before it is re-read.
        expectedProbes.removeIf(value -> value == 10000);
        actualProbes.removeIf(value -> value == 10000);
        Collections.sort(expectedProbes);
        Collections.sort(actualProbes);
        assertEquals(expectedProbes, actualProbes);
        assertEquals(3000, allMatches.size());
        assertEquals(6, Collections.frequency(allMatches, 0));
        assertTrue(
                ioManager.getCreatedBlockChannelWriters() > 0,
                "Expected the join to spill at least one partition");

        table.close();
        assertEquals(MIN_MEMORY_SEGMENTS, table.getFreedMemory().size());
    }

    private MutableHashTable<Integer, Integer> openTable(List<Integer> build, List<Integer> probe)
            throws IOException {
        MutableHashTable<Integer, Integer> table = newTable(true);
        table.open(iterator(build), iterator(probe));
        return table;
    }

    private MutableHashTable<Integer, Integer> newTable(boolean useBloomFilters) {
        MutableHashTable<Integer, Integer> table =
                newHashTable(
                        createMemory(MIN_MEMORY_SEGMENTS, SEGMENT_SIZE),
                        IntSerializer.INSTANCE,
                        useBloomFilters);
        openTables.add(table);
        return table;
    }

    private MutableHashTable<Integer, Integer> newHashTable(
            List<MemorySegment> memory, IntSerializer serializer, boolean useBloomFilters) {
        TypeComparator<Integer> buildComparator = new IntComparator(true);
        TypeComparator<Integer> probeComparator = new IntComparator(true);
        TypePairComparator<Integer, Integer> pairComparator =
                new SameTypePairComparator<>(new IntComparator(true));
        return new MutableHashTable<>(
                serializer,
                serializer,
                buildComparator,
                probeComparator,
                pairComparator,
                memory,
                ioManager,
                useBloomFilters);
    }

    private static List<MemorySegment> createMemory(int count, int segmentSize) {
        List<MemorySegment> memory = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            memory.add(MemorySegmentFactory.allocateUnpooledSegment(segmentSize));
        }
        return memory;
    }

    private static MutableObjectIterator<Integer> iterator(List<Integer> values) {
        return new ListMutableObjectIterator(values);
    }

    private static List<Integer> collect(MutableObjectIterator<Integer> iterator)
            throws IOException {
        List<Integer> result = new ArrayList<>();
        Integer next;
        while ((next = iterator.next()) != null) {
            result.add(next);
        }
        return result;
    }

    private static List<Integer> collectAndSort(MutableObjectIterator<Integer> iterator)
            throws IOException {
        List<Integer> result = collect(iterator);
        Collections.sort(result);
        return result;
    }

    private static final class CountingIOManagerAsync extends IOManagerAsync {

        private int createdBlockChannelWriters;

        private CountingIOManagerAsync(String tempDir) {
            super(tempDir);
        }

        @Override
        public BlockChannelWriter<MemorySegment> createBlockChannelWriter(
                FileIOChannel.ID channelID, LinkedBlockingQueue<MemorySegment> returnQueue)
                throws IOException {
            createdBlockChannelWriters++;
            return super.createBlockChannelWriter(channelID, returnQueue);
        }

        private int getCreatedBlockChannelWriters() {
            return createdBlockChannelWriters;
        }
    }

    private static final class ListMutableObjectIterator implements MutableObjectIterator<Integer> {

        private final List<Integer> values;
        private int index;

        private ListMutableObjectIterator(List<Integer> values) {
            this.values = values;
        }

        @Override
        public Integer next(Integer reuse) {
            return index < values.size() ? values.get(index++) : null;
        }

        @Override
        public Integer next() {
            return next(null);
        }
    }
}

