        assertEquals("100", subtaskStore.getMetric(transientMetricName));
        assertEquals("100", attemptStore.getMetric(transientMetricName));

        updateSingleSubtaskAttempts(metricStore, JOB_ID_OBJECT, VERTEX_ID, 0, 0, false, 0);

        assertEquals("100", taskStore.getMetric("0." + transientMetricName));
        assertEquals("100", subtaskStore.getMetric(transientMetricName));

