        metricStore.add(new GaugeDump(taskScope(0, 0), transientMetricName, "10"));
        metricStore.add(new GaugeDump(taskScope(1, 0), transientMetricName, "20"));

        Map<Integer, CurrentAttempts> vertexAttempts = new HashMap<>();
        vertexAttempts.put(0, currentAttempts(0, true, 0));
        vertexAttempts.put(1, currentAttempts(0, false, 0));
        metricStore.updateCurrentExecutionAttempts(
                Collections.singletonList(
                        jobDetails(
                                JOB_ID_OBJECT,
                                Collections.singletonMap(VERTEX_ID, vertexAttempts))));

        TaskMetricStore taskStore = metricStore.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals(
                new HashSet<>(Arrays.asList(0, 1)),
                taskStore.getAllSubtaskMetricStores().keySet());
        assertNull(taskStore.getMetric("0." + transientMetricName));
        assertEquals("20", taskStore.getMetric("1." + transientMetricName));
        assertNull(taskStore.getSubtaskMetricStore(0).getMetric(transientMetricName));
        assertEquals(
                "20", taskStore.getSubtaskMetricStore(1).getMetric(transientMetricName));
