                        Arrays.asList(
                                new CounterDump(
                                        new JobManagerQueryScopeInfo(), "jmCounter", 1L),
                                new GaugeDump(taskScope(0, 0), "taskGauge", "taskValue")));

        metricStore.addAll(dumps);

        assertEquals(
                "1", metricStore.getJobManagerMetricStore().getMetric("jmCounter"));
        assertEquals(
                "taskValue",
                metricStore
                        .getTaskMetricStore(JOB_ID, VERTEX_ID)
                        .getMetric("0.taskGauge"));
    }

    // ---------------------------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------------------------

    private static TaskQueryScopeInfo taskScope(int subtaskIndex, int attemptNumber) {
        return new TaskQueryScopeInfo(JOB_ID, VERTEX_ID, subtaskIndex, attemptNumber);
    }

    private static CurrentAttempts currentAttempts(
            int representativeAttempt, boolean terminal, Integer... currentAttempts) {
        Set<Integer> attempts = new HashSet<>(Arrays.asList(currentAttempts));
        return new CurrentAttempts(representativeAttempt, attempts, terminal);
    }

    private static JobDetails jobDetails(
            JobID jobID, Map<String, Map<Integer, CurrentAttempts>> currentExecutionAttempts) {
        return new JobDetails(
                jobID,
                "job",
                0L,
                -1L,
                0L,
                JobStatus.RUNNING,
                0L,
                new int[ExecutionState.values().length],
                1,
                currentExecutionAttempts);
    }

    private static void updateSingleSubtaskAttempts(
            MetricStore metricStore,
            JobID jobID,
            String vertexID,
            int subtaskIndex,
            int representativeAttempt,
            boolean terminal,
            Integer... currentAttempts) {
        Map<String, Map<Integer, CurrentAttempts>> attempts = new HashMap<>();
        attempts.put(
                vertexID,
                Collections.singletonMap(
                        subtaskIndex,
                        currentAttempts(representativeAttempt, terminal, currentAttempts)));
        metricStore.updateCurrentExecutionAttempts(
                Collections.singletonList(jobDetails(jobID, attempts)));
    }
