        Map<String, Map<Integer, CurrentAttempts>> firstJobAttempts = new HashMap<>();
        firstJobAttempts.put(VERTEX_ID, Collections.singletonMap(0, currentAttempts(3, false, 3)));
        firstJobAttempts.put(
                OTHER_VERTEX_ID, Collections.singletonMap(1, currentAttempts(4, false, 4)));
        Map<String, Map<Integer, CurrentAttempts>> secondJobAttempts = new HashMap<>();
        secondJobAttempts.put(
                VERTEX_ID, Collections.singletonMap(0, currentAttempts(5, false, 5)));

        metricStore.updateCurrentExecutionAttempts(
                Arrays.asList(
                        jobDetails(JOB_ID_OBJECT, firstJobAttempts),
                        jobDetails(OTHER_JOB_ID_OBJECT, secondJobAttempts)));

        Map<String, Map<String, Map<Integer, Integer>>> representativeAttempts =
                metricStore.getRepresentativeAttempts();
        assertEquals(2, representativeAttempts.size());
        assertEquals(
                Integer.valueOf(3),
                representativeAttempts.get(JOB_ID).get(VERTEX_ID).get(0));
        assertEquals(
                Integer.valueOf(4),
                representativeAttempts.get(JOB_ID).get(OTHER_VERTEX_ID).get(1));
        assertEquals(
                Integer.valueOf(5),
                representativeAttempts.get(OTHER_JOB_ID).get(VERTEX_ID).get(0));
    }

    @Test
    void updateCurrentExecutionAttemptsRetainsOnlyActiveSubtasks() {
        MetricStore metricStore = new MetricStore();
        metricStore.add(new GaugeDump(taskScope(0, 0), "metric", "subtask-zero"));
        metricStore.add(new GaugeDump(taskScope(1, 0), "metric", "subtask-one"));

        updateSingleSubtaskAttempts(metricStore, JOB_ID_OBJECT, VERTEX_ID, 0, 0, false, 0);

        TaskMetricStore taskStore = metricStore.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals(Collections.singleton(0), taskStore.getAllSubtaskMetricStores().keySet());
        assertEquals("subtask-zero", taskStore.getMetric("0.metric"));
        assertNull(taskStore.getMetric("1.metric"));
        assertNull(taskStore.getSubtaskMetricStore(1));
    }

    @Test
    void updateCurrentExecutionAttemptsRetainsOnlyCurrentAttempts() {
        MetricStore metricStore = new MetricStore();
        metricStore.add(new GaugeDump(taskScope(0, 0), "metric", "attempt-zero"));
        metricStore.add(new GaugeDump(taskScope(0, 1), "metric", "attempt-one"));
        metricStore.add(new GaugeDump(taskScope(0, 2), "metric", "attempt-two"));

        updateSingleSubtaskAttempts(metricStore, JOB_ID_OBJECT, VERTEX_ID, 0, 2, false, 1, 2);

        SubtaskMetricStore subtaskStore =
                metricStore.getTaskMetricStore(JOB_ID, VERTEX_ID).getSubtaskMetricStore(0);
        assertEquals(
                new HashSet<>(Arrays.asList(1, 2)),
                subtaskStore.getAllAttemptsMetricStores().keySet());
        assertNull(subtaskStore.getAttemptsMetricStore(0));
        assertNotNull(subtaskStore.getAttemptsMetricStore(1));
        assertNotNull(subtaskStore.getAttemptsMetricStore(2));
    }

    @Test
    void terminalSubtaskRemovesTransientMetricsButKeepsRegularMetrics() {
        MetricStore metricStore = new MetricStore();
        String transientMetricName = MetricNames.TASK_BUSY_TIME;

        metricStore.add(new GaugeDump(taskScope(0, 0), transientMetricName, "100"));
        metricStore.add(new CounterDump(taskScope(0, 0), "numRecords", 8L));

        TaskMetricStore taskStore = metricStore.getTaskMetricStore(JOB_ID, VERTEX_ID);
        SubtaskMetricStore subtaskStore = taskStore.getSubtaskMetricStore(0);
        ComponentMetricStore attemptStore = subtaskStore.getAttemptsMetricStore(0);
        assertEquals("100", taskStore.getMetric("0." + transientMetricName));
        assertEquals("100", subtaskStore.getMetric(transientMetricName));
        assertEquals("100", attemptStore.getMetric(transientMetricName));

        updateSingleSubtaskAttempts(metricStore, JOB_ID_OBJECT, VERTEX_ID, 0, 0, false, 0);

        assertEquals("100", taskStore.getMetric("0." + transientMetricName));
        assertEquals("100", subtaskStore.getMetric(transientMetricName));

        updateSingleSubtaskAttempts(metricStore, JOB_ID_OBJECT, VERTEX_ID, 0, 0, true, 0);

        TaskMetricStore updatedTaskStore = metricStore.getTaskMetricStore(JOB_ID, VERTEX_ID);
        SubtaskMetricStore updatedSubtaskStore =
                updatedTaskStore.getSubtaskMetricStore(0);
        ComponentMetricStore updatedAttemptStore =
                updatedSubtaskStore.getAttemptsMetricStore(0);
        assertNull(updatedTaskStore.getMetric("0." + transientMetricName));
        assertNull(updatedSubtaskStore.getMetric(transientMetricName));
        assertNull(updatedAttemptStore.getMetric(transientMetricName));

        assertEquals("8", updatedTaskStore.getMetric("0.numRecords"));
        assertEquals("8", updatedSubtaskStore.getMetric("numRecords"));
        assertEquals("8", updatedAttemptStore.getMetric("numRecords"));
    }

    @Test
    void terminalSubtaskRemovesTransientMetricsOnlyForThatSubtask() {
        MetricStore metricStore = new MetricStore();
        String transientMetricName = MetricNames.TASK_IDLE_TIME;

        metricStore.add(new GaugeDump(taskScope(0, 0), transientMetricName, "10"));
        metricStore.add(new GaugeDump(taskScope(1, 0), transientMetricName, "20"));

        Map<Integer, CurrentAttempts> vertexAttempts = new HashMap<>();
        vertexAttempts.put(0, currentAttempts(0, true, 0));
        vertexAttempts.put(1, currentAttempts(0, false, 0));
        metricStore.updateCurrentExecutionAttempts(
                Collections.singletonList(
                        jobDetails(
                                JOB_ID_OBJECT,
                                Collections.singletonMap(VERTEX_ID, vertexAttempts))));

        TaskMetricStore taskStore = metricStore.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals(
                new HashSet<>(Arrays.asList(0, 1)),
                taskStore.getAllSubtaskMetricStores().keySet());
        assertNull(taskStore.getMetric("0." + transientMetricName));
        assertEquals("20", taskStore.getMetric("1." + transientMetricName));
        assertNull(taskStore.getSubtaskMetricStore(0).getMetric(transientMetricName));
        assertEquals(
                "20", taskStore.getSubtaskMetricStore(1).getMetric(transientMetricName));
    }

    // ---------------------------------------------------------------------------------------------
    // Bulk addition
    // ---------------------------------------------------------------------------------------------

    @Test
    void addAllAddsEveryDump() {
        MetricStore metricStore = new MetricStore();
        List<MetricDump> dumps =
                new ArrayList<>(
                        Arrays.asList(
                                new CounterDump(
                                        new JobManagerQueryScopeInfo(), "jmCounter", 1L),
                                new GaugeDump(taskScope(0, 0), "taskGauge", "taskValue")));

        metricStore.addAll(dumps);

        assertEquals(
                "1", metricStore.getJobManagerMetricStore().getMetric("jmCounter"));
        assertEquals(
                "taskValue",
                metricStore
                        .getTaskMetricStore(JOB_ID, VERTEX_ID)
                        .getMetric("0.taskGauge"));
    }

    // ---------------------------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------------------------

    private static TaskQueryScopeInfo taskScope(int subtaskIndex, int attemptNumber) {
        return new TaskQueryScopeInfo(JOB_ID, VERTEX_ID, subtaskIndex, attemptNumber);
    }

    private static CurrentAttempts currentAttempts(
            int representativeAttempt, boolean terminal, Integer... currentAttempts) {
        Set<Integer> attempts = new HashSet<>(Arrays.asList(currentAttempts));
        return new CurrentAttempts(representativeAttempt, attempts, terminal);
    }

    private static JobDetails jobDetails(
            JobID jobID, Map<String, Map<Integer, CurrentAttempts>> currentExecutionAttempts) {
        return new JobDetails(
                jobID,
                "job",
                0L,
                -1L,
                0L,
                JobStatus.RUNNING,
                0L,
                new int[ExecutionState.values().length],
                1,
                currentExecutionAttempts);
    }

    private static void updateSingleSubtaskAttempts(
            MetricStore metricStore,
            JobID jobID,
            String vertexID,
            int subtaskIndex,
            int representativeAttempt,
            boolean terminal,
            Integer... currentAttempts) {
        Map<String, Map<Integer, CurrentAttempts>> attempts = new HashMap<>();
        attempts.put(
                vertexID,
                Collections.singletonMap(
                        subtaskIndex,
                        currentAttempts(representativeAttempt, terminal, currentAttempts)));
        metricStore.updateCurrentExecutionAttempts(
                Collections.singletonList(jobDetails(jobID, attempts)));
    }
}

