        return new TaskDeploymentDescriptor(
                jobId,
                new TaskDeploymentDescriptor.Offloaded<>(new PermanentBlobKey()),
                new TaskDeploymentDescriptor.Offloaded<>(new PermanentBlobKey()),
                newExecutionAttemptID(),
                new AllocationID(),
                null,
                Collections.emptyList(),
                Collections.emptyList());
    }

    private static <T> T get(CompletableFuture<T> future) throws Exception {
        return future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
    }

    private static Throwable failureOf(CompletableFuture<?> future) {
        try {
            future.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
        } catch (ExecutionException e) {
            return e.getCause();
        } catch (InterruptedException | TimeoutException e) {
            throw new AssertionError("The future did not complete as expected.", e);
        }
        fail("Expected the future to fail.");
        return null;
    }

    /** The set of services and stand-ins which surround the {@link TaskExecutor} under test. */
    private static final class TestContext implements AutoCloseable {

        private final File tempDirectory;
        private final Configuration configuration;
        private final ExecutorService ioExecutor =
                Executors.newSingleThreadExecutor(
                        runnable -> {
                            final Thread thread = new Thread(runnable, "test-io-executor");
                            thread.setDaemon(true);
                            return thread;
                        });

        private final TestRpcService rpcService = new TestRpcService();
        private final TestingHeartbeatServices heartbeatServices = new TestingHeartbeatServices();

        private final TaskManagerServices taskExecutorServices = mock(TaskManagerServices.class);
