            return scheduledDelays;
        }

        void completeTermination() {
            terminationFuture.complete(null);
        }

        @Override
        public void runAsync(Runnable runnable) {
            try {
                executeInMainThread(runnable);
            } catch (RuntimeException | Error e) {
                throw e;
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public <V> CompletableFuture<V> callAsync(Callable<V> callable, Duration callTimeout) {
            try {
                return CompletableFuture.completedFuture(executeInMainThread(callable));
            } catch (Throwable t) {
                final CompletableFuture<V> future = new CompletableFuture<>();
                future.completeExceptionally(t);
                return future;
            }
        }

        @Override
        public void scheduleRunAsync(Runnable runnable, long delay) {
            scheduledDelays.add(delay);
        }

        @Override
        public void start() {
            // no-op
        }

        @Override
        public void stop() {
            completeTermination();
        }

        @Override
        public String getAddress() {
            return "localhost:1234";
        }

        @Override
        public String getHostname() {
            return "localhost";
        }

        @Override
        public CompletableFuture<Void> getTerminationFuture() {
            return terminationFuture;
        }
    }

    /**
     * A {@link ScheduledExecutor} which executes all commands immediately on the calling thread.
     */
    private static final class InlineScheduledExecutor implements ScheduledExecutor {

        @Override
        public void execute(Runnable command) {
            command.run();
        }

        @Override
        public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
            return new CompletedScheduledFuture<>(Executors.callable(command, null));
        }

        @Override
        public <V> ScheduledFuture<V> schedule(Callable<V> callable, long delay, TimeUnit unit) {
            return new CompletedScheduledFuture<>(callable);
        }

        @Override
        public ScheduledFuture<?> scheduleAtFixedRate(
                Runnable command, long initialDelay, long period, TimeUnit unit) {
            throw new UnsupportedOperationException("Not supported.");
        }

        @Override
        public ScheduledFuture<?> scheduleWithFixedDelay(
                Runnable command, long initialDelay, long delay, TimeUnit unit) {
            throw new UnsupportedOperationException("Not supported.");
        }
    }

    /** An already completed {@link ScheduledFuture}. */
    private static final class CompletedScheduledFuture<V> extends FutureTask<V>
            implements ScheduledFuture<V> {

        private CompletedScheduledFuture(Callable<V> callable) {
            super(callable);
            run();
        }

        @Override
        public long getDelay(TimeUnit unit) {
            return 0L;
        }

        @Override
        public int compareTo(Delayed o) {
            return 0;
        }
    }
