    @Test
    void testIsZooKeeperRecoveryMode() {
        assertThat(ZooKeeperUtils.isZooKeeperRecoveryMode(new Configuration())).isFalse();

        final Configuration zookeeperConfiguration = new Configuration();
        zookeeperConfiguration.set(HighAvailabilityOptions.HA_MODE, "ZOOKEEPER");
        assertThat(ZooKeeperUtils.isZooKeeperRecoveryMode(zookeeperConfiguration)).isTrue();

        final Configuration lowerCaseConfiguration = new Configuration();
        lowerCaseConfiguration.set(HighAvailabilityOptions.HA_MODE, "zookeeper");
        assertThat(ZooKeeperUtils.isZooKeeperRecoveryMode(lowerCaseConfiguration)).isTrue();

        final Configuration kubernetesConfiguration = new Configuration();
        kubernetesConfiguration.set(HighAvailabilityOptions.HA_MODE, "KUBERNETES");
        assertThat(ZooKeeperUtils.isZooKeeperRecoveryMode(kubernetesConfiguration)).isFalse();

        final Configuration standaloneConfiguration = new Configuration();
        standaloneConfiguration.set(HighAvailabilityOptions.HA_MODE, "standalone");
        assertThat(ZooKeeperUtils.isZooKeeperRecoveryMode(standaloneConfiguration)).isFalse();
    }

