    @Test
    void testWriteAndReadLeaderInformationRoundTrip() throws Exception {
        final String connectionInformationPath = "/leader/connection_info";
        final LeaderInformation leaderInformation =
                LeaderInformation.known(UUID.randomUUID(), "localhost:6123");

        ZooKeeperUtils.writeLeaderInformationToZooKeeper(
                leaderInformation, client, () -> true, connectionInformationPath);

        final Stat stat = client.checkExists().forPath(connectionInformationPath);
        assertThat(stat).isNotNull();
        assertThat(stat.getEphemeralOwner())
                .isEqualTo(client.getZookeeperClient().getZooKeeper().getSessionId());

        assertThat(
                        ZooKeeperUtils.readLeaderInformation(
                                client.getData().forPath(connectionInformationPath)))
                .isEqualTo(leaderInformation);
    }

    @Test
    void testWriteLeaderInformationUpdatesExistingNode() throws Exception {
        final String connectionInformationPath = "/leader/connection_info";
        ZooKeeperUtils.writeLeaderInformationToZooKeeper(
                LeaderInformation.known(UUID.randomUUID(), "first:1"),
                client,
                () -> true,
                connectionInformationPath);

        final long ephemeralOwner =
                client.checkExists().forPath(connectionInformationPath).getEphemeralOwner();

        final LeaderInformation updatedLeaderInformation =
                LeaderInformation.known(UUID.randomUUID(), "second:2");
        ZooKeeperUtils.writeLeaderInformationToZooKeeper(
                updatedLeaderInformation, client, () -> true, connectionInformationPath);

        assertThat(client.checkExists().forPath(connectionInformationPath).getEphemeralOwner())
                .isEqualTo(ephemeralOwner);
        assertThat(
                        ZooKeeperUtils.readLeaderInformation(
                                client.getData().forPath(connectionInformationPath)))
                .isEqualTo(updatedLeaderInformation);
    }

