    @Test
    void testCreateTreeCacheNotifiesCallbackOnNodeChanges() throws Exception {
        final AtomicInteger callbackInvocations = new AtomicInteger();

        try (TreeCache treeCache =
                ZooKeeperUtils.createTreeCache(
                        client, "/watched", callbackInvocations::incrementAndGet)) {
            treeCache.start();

            client.create()
                    .creatingParentsIfNeeded()
                    .forPath("/watched", "initial".getBytes(StandardCharsets.UTF_8));
            awaitCounter(callbackInvocations, 1);

            client.setData().forPath("/watched", "updated".getBytes(StandardCharsets.UTF_8));
            awaitCounter(callbackInvocations, 2);

            client.delete().forPath("/watched");
            awaitCounter(callbackInvocations, 3);

            assertThat(callbackInvocations.get()).isGreaterThanOrEqualTo(3);
        }
    }

    @Test
    void testCreateTreeCacheOnlyObservesTheGivenNode() throws Exception {
        client.create().creatingParentsIfNeeded().forPath("/watched", bytes("parent"));
        client.create().creatingParentsIfNeeded().forPath("/watched/child", bytes("child"));

        try (TreeCache treeCache = ZooKeeperUtils.createTreeCache(client, "/watched", () -> {})) {
            treeCache.start();

            awaitCondition(() -> treeCache.getCurrentData("/watched") != null);

            assertThat(treeCache.getCurrentData("/watched").getData()).isEqualTo(bytes("parent"));
            assertThat(treeCache.getCurrentData("/watched/child")).isNull();
            assertThat(treeCache.getCurrentChildren("/watched")).isEmpty();
        }
    }

    @Test
    void testCreateTreeCacheWithCustomSelectorCachesAcceptedChildren() throws Exception {
        client.create().creatingParentsIfNeeded().forPath("/custom", bytes("parent"));
        client.create().creatingParentsIfNeeded().forPath("/custom/child", bytes("child"));

        final TreeCacheSelector selector =
                new TreeCacheSelector() {
                    @Override
                    public boolean traverseChildren(String childPath) {
                        return true;
                    }

                    @Override
                    public boolean acceptChild(String childPath) {
                        return "/custom/child".equals(childPath);
                    }
                };

        try (TreeCache treeCache = ZooKeeperUtils.createTreeCache(client, "/custom", selector)) {
            treeCache.start();

            awaitCondition(() -> treeCache.getCurrentData("/custom/child") != null);

            assertThat(treeCache.getCurrentData("/custom/child").getData())
                    .isEqualTo(bytes("child"));
        }
    }

    @ParameterizedTest
