    @Test
    void testStartCuratorFrameworkConnectsUsingConfiguredNamespace() throws Exception {
        final String clusterId = "/cluster-" + UUID.randomUUID();
        final Configuration configuration = zooKeeperConfiguration();
        configuration.set(HighAvailabilityOptions.HA_CLUSTER_ID, clusterId);
        configuration.set(
                HighAvailabilityOptions.ZOOKEEPER_MAX_CLOSE_WAIT, Duration.ofMillis(1000L));
        configuration.set(HighAvailabilityOptions.ZOOKEEPER_SIMULATED_SESSION_EXP_PERCENT, 100);
        configuration.set(HighAvailabilityOptions.ZOOKEEPER_TOLERATE_SUSPENDED_CONNECTIONS, true);
        configuration.set(
                HighAvailabilityOptions.ZOOKEEPER_CLIENT_AUTHORIZATION,
                Collections.singletonMap("digest", "user:password"));

        final AtomicReference<Throwable> fatalError = new AtomicReference<>();
        final CuratorFrameworkWithUnhandledErrorListener curatorFrameworkWrapper =
                ZooKeeperUtils.startCuratorFramework(configuration, fatalError::set);
        final CuratorFramework curatorFramework = curatorFrameworkWrapper.asCuratorFramework();

        try {
            assertThat(curatorFramework.getState()).isEqualTo(CuratorFrameworkState.STARTED);
            assertThat(curatorFramework.getNamespace()).isEqualTo("flink" + clusterId);

            curatorFramework.create().creatingParentsIfNeeded().forPath("/probe", bytes("value"));

            assertThat(curatorFramework.getData().forPath("/probe")).isEqualTo(bytes("value"));
            assertThat(fatalError.get()).isNull();
        } finally {
            curatorFrameworkWrapper.close();
        }

        assertThat(curatorFramework.getState()).isEqualTo(CuratorFrameworkState.STOPPED);
    }

