    @Test
    void testStartCuratorFrameworkFromBuilderStartsClientAndForwardsFatalErrors() throws Exception {
        final CuratorFrameworkFactory.Builder builder =
                CuratorFrameworkFactory.builder()
                        .connectString(testingServer.getConnectString())
                        .namespace("builder-client")
                        .retryPolicy(new RetryOneTime(100));
        final AtomicReference<Throwable> fatalError = new AtomicReference<>();

        final CuratorFrameworkWithUnhandledErrorListener curatorFrameworkWrapper =
                ZooKeeperUtils.startCuratorFramework(builder, fatalError::set);

        try {
            final CuratorFramework curatorFramework = curatorFrameworkWrapper.asCuratorFramework();
            assertThat(curatorFramework.getState()).isEqualTo(CuratorFrameworkState.STARTED);
            assertThat(curatorFramework.getNamespace()).isEqualTo("builder-client");

            curatorFramework.blockUntilConnected();
            curatorFramework.create().creatingParentsIfNeeded().forPath("/node", bytes("data"));
            assertThat(curatorFramework.getData().forPath("/node")).isEqualTo(bytes("data"));
            assertThat(fatalError.get()).isNull();

            final Throwable failure = new RuntimeException("expected failure");
            getUnhandledErrorListener(curatorFrameworkWrapper)
                    .unhandledError("unhandled error", failure);
            assertThat(fatalError.get()).isSameAs(failure);
        } finally {
            curatorFrameworkWrapper.close();
        }
