    private static SharedStateRegistryFactory createSharedStateRegistryFactory() {
        return (executor, checkpoints, recoveryClaimMode) -> new SharedStateRegistryImpl(executor);
    }

    private static LeaderRetrievalListener createLeaderRetrievalListener(
            CompletableFuture<LeaderInformation> retrievedLeaderInformation) {
        return new LeaderRetrievalListener() {
            @Override
            public void notifyLeaderAddress(String leaderAddress, UUID leaderSessionID) {
                if (leaderAddress != null) {
                    retrievedLeaderInformation.complete(
                            LeaderInformation.known(leaderSessionID, leaderAddress));
                }
            }

            @Override
            public void handleError(Exception exception) {
                retrievedLeaderInformation.completeExceptionally(exception);
            }
        };
    }

    private static UnhandledErrorListener getUnhandledErrorListener(
            CuratorFrameworkWithUnhandledErrorListener curatorFrameworkWrapper) throws Exception {
        final Field listenerField =
                CuratorFrameworkWithUnhandledErrorListener.class.getDeclaredField("listener");
        listenerField.setAccessible(true);
        return (UnhandledErrorListener) listenerField.get(curatorFrameworkWrapper);
    }

    private static ZooKeeperLeaderRetrievalDriver.LeaderInformationClearancePolicy
            getLeaderInformationClearancePolicy(
                    ZooKeeperLeaderRetrievalDriverFactory leaderRetrievalDriverFactory)
                    throws Exception {
        final Field clearancePolicyField =
                ZooKeeperLeaderRetrievalDriverFactory.class.getDeclaredField(
                        "leaderInformationClearancePolicy");
        clearancePolicyField.setAccessible(true);
        return (ZooKeeperLeaderRetrievalDriver.LeaderInformationClearancePolicy)
                clearancePolicyField.get(leaderRetrievalDriverFactory);
    }

    private static byte[] bytes(String value) {
        return value.getBytes(StandardCharsets.UTF_8);
    }

    private static void awaitCondition(BooleanSupplier condition) throws Exception {
        final long deadline = System.currentTimeMillis() + 30_000L;
        while (!condition.getAsBoolean()) {
            if (System.currentTimeMillis() > deadline) {
                fail("Condition was not fulfilled within the timeout.");
            }
            Thread.sleep(20L);
        }
    }

    private static void awaitCounter(AtomicInteger counter, int expectedMinimum) throws Exception {
        awaitCondition(() -> counter.get() >= expectedMinimum);
    }
