    private static final class RecordingInvocationHandler implements InvocationHandler {
        private final Map<String, Object> returns = new HashMap<>();
        private final List<String> invocations = new ArrayList<>();
        private final Map<String, Integer> invocationCounts = new HashMap<>();
        private final Map<String, List<Object[]>> invocationArguments = new HashMap<>();

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            if (method.getDeclaringClass() == Object.class) {
                switch (method.getName()) {
                    case "toString":
                        return "RecordingProxy";
                    case "hashCode":
                        return System.identityHashCode(proxy);
                    case "equals":
                        return proxy == args[0];
                    default:
                        throw new UnsupportedOperationException(method.getName());
                }
            }

            String methodName = method.getName();
            invocations.add(methodName);
            invocationCounts.merge(methodName, 1, Integer::sum);
            invocationArguments
                    .computeIfAbsent(methodName, ignored -> new ArrayList<>())
                    .add(args == null ? new Object[0] : args.clone());

            if (returns.containsKey(methodName)) {
                return returns.get(methodName);
            }
            return defaultValue(method.getReturnType());
        }

        private int count(String methodName) {
            return invocationCounts.getOrDefault(methodName, 0);
        }

        private List<Object[]> arguments(String methodName) {
            return invocationArguments.getOrDefault(methodName, Collections.emptyList());
        }
    }

