    @Test
    void rawKeyedStateInputsSkipUnsetOffsets() throws Exception {
        byte[] data = new byte[] {10, 11, 20, 21, 30, 31};
        KeyGroupRangeOffsets offsets =
                new KeyGroupRangeOffsets(
                        0,
                        3,
                        new long[] {0L, 2L, 4L, KeyedStateCheckpointOutputStream.NO_OFFSET_SET});
        KeyGroupsStateHandle handle =
                new KeyGroupsStateHandle(offsets, new ByteStreamStateHandle("keyed-state", data));
        TestFixture fixture = createFixture(PrioritizedOperatorSubtaskState.emptyNotRestored());
        StateObject.StateObjectSizeStatsCollector stats =
                StateObject.StateObjectSizeStatsCollector.create();
        StreamTaskStateInitializerImpl initializer = createInitializer(fixture);

        CloseableIterable<KeyGroupStatePartitionStreamProvider> iterable =
                initializer.rawKeyedStateInputs(
                        Collections.singleton(
                                        StateObjectCollection.<KeyedStateHandle>singleton(handle))
                                .iterator(),
                        stats);
        Iterator<KeyGroupStatePartitionStreamProvider> iterator = iterable.iterator();

        assertTrue(iterator.hasNext());
        KeyGroupStatePartitionStreamProvider first = iterator.next();
        assertEquals(0, first.getKeyGroupId());
        assertEquals(10, first.getStream().read());
        KeyGroupStatePartitionStreamProvider second = iterator.next();
        assertEquals(1, second.getKeyGroupId());
        assertEquals(20, second.getStream().read());
