    private static final class TestStateBackend implements StateBackend {
        private static final long serialVersionUID = 1L;

        private CheckpointableKeyedStateBackend<?> keyedBackend;
        private AsyncKeyedStateBackend<?> asyncBackend;
        private OperatorStateBackend operatorBackend;
        private boolean supportsAsync;
        private Exception operatorFailure;
        private StateBackend.KeyedStateBackendParameters<?> keyedParameters;
        private StateBackend.OperatorStateBackendParameters operatorParameters;
        private int keyedCreationAttempts;
        private int asyncCreationAttempts;
        private int operatorCreationAttempts;

        @SuppressWarnings("unchecked")
        @Override
        public <K> CheckpointableKeyedStateBackend<K> createKeyedStateBackend(
                KeyedStateBackendParameters<K> parameters) throws Exception {
            keyedCreationAttempts++;
            keyedParameters = parameters;
            return (CheckpointableKeyedStateBackend<K>) keyedBackend;
        }

        @SuppressWarnings("unchecked")
        @Override
        public <K> AsyncKeyedStateBackend<K> createAsyncKeyedStateBackend(
                KeyedStateBackendParameters<K> parameters) throws Exception {
            asyncCreationAttempts++;
            keyedParameters = parameters;
            return (AsyncKeyedStateBackend<K>) asyncBackend;
        }

        @Override
        public OperatorStateBackend createOperatorStateBackend(
                OperatorStateBackendParameters parameters) throws Exception {
            operatorCreationAttempts++;
            operatorParameters = parameters;
            if (operatorFailure != null) {
                throw operatorFailure;
            }
            return operatorBackend;
        }

        @Override
        public boolean supportsAsyncKeyedStateBackend() {
            return supportsAsync;
        }
    }

    private static final class RecordingInvocationHandler implements InvocationHandler {
        private final Map<String, Object> returns = new HashMap<>();
        private final List<String> invocations = new ArrayList<>();
        private final Map<String, Integer> invocationCounts = new HashMap<>();
        private final Map<String, List<Object[]>> invocationArguments = new HashMap<>();

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            if (method.getDeclaringClass() == Object.class) {
                switch (method.getName()) {
                    case "toString":
                        return "RecordingProxy";
                    case "hashCode":
                        return System.identityHashCode(proxy);
                    case "equals":
                        return proxy == args[0];
                    default:
                        throw new UnsupportedOperationException(method.getName());
                }
            }

            String methodName = method.getName();
            invocations.add(methodName);
            invocationCounts.merge(methodName, 1, Integer::sum);
            invocationArguments
                    .computeIfAbsent(methodName, ignored -> new ArrayList<>())
                    .add(args == null ? new Object[0] : args.clone());

            if (returns.containsKey(methodName)) {
                return returns.get(methodName);
            }
            return defaultValue(method.getReturnType());
        }

        private int count(String methodName) {
            return invocationCounts.getOrDefault(methodName, 0);
        }

        private List<Object[]> arguments(String methodName) {
            return invocationArguments.getOrDefault(methodName, Collections.emptyList());
        }
    }

    private static final class TestKeyContext implements KeyContext {
        private Object currentKey;

        @Override
        public void setCurrentKey(Object key) {
            currentKey = key;
        }

        @Override
        public Object getCurrentKey() {
            return currentKey;
        }
    }

    private static Object defaultValue(Class<?> returnType) {
        if (!returnType.isPrimitive()) {
            return null;
        }
        if (returnType == boolean.class) {
            return false;
        }
        if (returnType == char.class) {
            return '\0';
        }
        if (returnType == byte.class) {
            return (byte) 0;
        }
        if (returnType == short.class) {
            return (short) 0;
        }
        if (returnType == int.class) {
            return 0;
        }
        if (returnType == long.class) {
            return 0L;
        }
        if (returnType == float.class) {
            return 0.0f;
        }
        if (returnType == double.class) {
            return 0.0d;
        }
        return null;
    }

    private static final class CapturingTimeServiceManagerProvider
            implements InternalTimeServiceManager.Provider {
        private static final long serialVersionUID = 1L;

        private InternalTimeServiceManager<?> manager = newTimerManager();
        private Exception failure;
        private int invocations;
        private TaskIOMetricGroup taskIOMetricGroup;
        private PriorityQueueSetFactory factory;
        private KeyGroupRange keyGroupRange;
        private ClassLoader userClassLoader;
        private KeyContext keyContext;
        private ProcessingTimeService processingTimeService;
        private Iterable<KeyGroupStatePartitionStreamProvider> rawKeyedStates;
        private StreamTaskCancellationContext cancellationContext;

        @SuppressWarnings("unchecked")
        @Override
        public <K> InternalTimeServiceManager<K> create(
                TaskIOMetricGroup taskIOMetricGroup,
                PriorityQueueSetFactory factory,
                KeyGroupRange keyGroupRange,
                ClassLoader userClassloader,
                KeyContext keyContext,
                ProcessingTimeService processingTimeService,
                Iterable<KeyGroupStatePartitionStreamProvider> rawKeyedStates,
                StreamTaskCancellationContext cancellationContext)
                throws Exception {
            invocations++;
            this.taskIOMetricGroup = taskIOMetricGroup;
            this.factory = factory;
            this.keyGroupRange = keyGroupRange;
            this.userClassLoader = userClassloader;
            this.keyContext = keyContext;
            this.processingTimeService = processingTimeService;
            this.rawKeyedStates = rawKeyedStates;
            this.cancellationContext = cancellationContext;
            if (failure != null) {
                throw failure;
            }
            return (InternalTimeServiceManager<K>) manager;
        }
    }
}

