    private static SqlValidatorImpl newValidator() {
        CalciteSchema rootSchema = CalciteSchema.createRootSchema(true);
        rootSchema.add(
                "T",
                new AbstractTable() {
                    @Override
                    public RelDataType getRowType(RelDataTypeFactory typeFactory) {
                        return typeFactory
                                .builder()
                                .add("A", SqlTypeName.INTEGER)
                                .add("B", SqlTypeName.VARCHAR, 10)
                                .add("C", SqlTypeName.INTEGER)
                                .build();
                    }
                });

        CalciteCatalogReader catalogReader =
                new CalciteCatalogReader(
                        rootSchema,
                        Collections.emptyList(),
                        TYPE_FACTORY,
                        CalciteConnectionConfig.DEFAULT);

        return (SqlValidatorImpl)
                SqlValidatorUtil.newValidator(
                        OPERATOR_TABLE, catalogReader, TYPE_FACTORY, SqlValidator.Config.DEFAULT);
    }

    private static SqlNode parse(String sql) throws Exception {
        return SqlParser.create(sql).parseQuery();
    }

    private static CalciteContextException assertValidationError(String sql, String expected)
            throws Exception {
        SqlValidatorImpl validator = newValidator();
        CalciteContextException exception =
                assertThrows(CalciteContextException.class, () -> validator.validate(parse(sql)));
        assertTrue(
                exception.getMessage().contains(expected),
                () ->
                        "Expected message to contain <"
                                + expected
                                + "> but was: "
                                + exception.getMessage());
        return exception;
    }

