        assertEquals("X", validator.deriveAlias(select.getSelectList().get(0), 0));
        assertEquals("B", validator.deriveAlias(select.getSelectList().get(1), 1));
        assertNull(validator.deriveAlias(select.getSelectList().get(2), -1));
        assertEquals("EXPR$3", validator.deriveAlias(select.getSelectList().get(3), 3));
    }

    @Test
    void makeNullaryCallCreatesCallForNiladicFunction() {
