        CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.getValidatedNodeType(identifier));
        assertTrue(
                exception.getMessage().contains("Unknown identifier 'Q'"), exception.getMessage());

        validator.setValidatedNodeType(identifier, TYPE_FACTORY.createSqlType(SqlTypeName.INTEGER));
        assertEquals(
                SqlTypeName.INTEGER, validator.getValidatedNodeType(identifier).getSqlTypeName());

        validator.removeValidatedNodeType(identifier);
        assertNull(validator.getValidatedNodeTypeIfKnown(identifier));

        validator.setValidatedNodeType(identifier, validator.getUnknownType());
        assertNull(validator.getValidatedNodeTypeIfKnown(identifier));
    }

    @Test
    void getValidatedOperandTypesReadsRegisteredOperands() throws Exception {
        SqlCall call = (SqlCall) ((SqlSelect) parse("SELECT ABS(-1)")).getSelectList().get(0);
        assertNull(validator.getValidatedOperandTypes(call));

        List<RelDataType> operandTypes =
                Arrays.asList(
                        TYPE_FACTORY.createSqlType(SqlTypeName.INTEGER),
                        TYPE_FACTORY.createSqlType(SqlTypeName.VARCHAR, 5));
        validator.callToOperandTypesMap.put(call, operandTypes);

        assertSame(operandTypes, validator.getValidatedOperandTypes(call));
