        RelDataType parameterRowType = validator.getParameterRowType(validated);
        assertEquals(2, parameterRowType.getFieldCount());
        assertEquals("?0", parameterRowType.getFieldList().get(0).getName());
        assertEquals(
                SqlTypeName.INTEGER,
                parameterRowType.getFieldList().get(0).getType().getSqlTypeName());
        assertEquals("?1", parameterRowType.getFieldList().get(1).getName());
        assertEquals(
