    @Test
    void getFieldOriginsReportsColumnOriginForDirectReferenceOnly() throws Exception {
        SqlNode validated = validator.validate(parse("SELECT A AS X, B || 'z' AS Y FROM T"));

        List<List<String>> origins = validator.getFieldOrigins(validated);
        assertEquals(2, origins.size());
        assertEquals(Arrays.asList("T", "A"), origins.get(0));
        assertNull(origins.get(1));
    }

    @Test
    void expandQualifiesIdentifierAndRemembersOriginal() throws Exception {
        SqlNode validated = validator.validate(parse("SELECT A FROM T"));
        SqlSelect select = (SqlSelect) validated;
        SqlNode original = select.getSelectList().get(0);

        SqlNode expanded = validator.expand(original, validator.getSelectScope(select));

        assertTrue(expanded instanceof SqlIdentifier);
        assertEquals(Arrays.asList("T", "A"), ((SqlIdentifier) expanded).names);
        assertSame(original, validator.getOriginal(expanded));
    }

    @Test
    void setOriginalKeepsFirstMapping() {
        SqlNode expression = SqlLiteral.createExactNumeric("1", SqlParserPos.ZERO);
        SqlNode firstOriginal = SqlLiteral.createExactNumeric("2", SqlParserPos.ZERO);
        SqlNode secondOriginal = SqlLiteral.createExactNumeric("3", SqlParserPos.ZERO);

        assertSame(expression, validator.getOriginal(expression));
        validator.setOriginal(expression, firstOriginal);
        assertSame(firstOriginal, validator.getOriginal(expression));
        validator.setOriginal(expression, secondOriginal);
        assertSame(firstOriginal, validator.getOriginal(expression));
    }

    // ---------------------------------------------------------------------
    // Window resolution and name completion
    // ---------------------------------------------------------------------

    @Test
    void resolveWindowResolvesNamedWindowAndRejectsUnknownWindow() throws Exception {
        SqlNode validated =
                validator.validate(
                        parse("SELECT SUM(A) OVER W FROM T WINDOW W AS (PARTITION BY B)"));
        SqlSelect select = (SqlSelect) validated;

        SqlWindow window =
                validator.resolveWindow(
                        new SqlIdentifier("W", SqlParserPos.ZERO),
                        validator.getSelectScope(select));
        assertEquals("W", window.getDeclName().getSimple());
        assertEquals(1, window.getPartitionList().size());

        CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.resolveWindow(
                                        new SqlIdentifier("NOPE", SqlParserPos.ZERO),
                                        validator.getSelectScope(select)));
        assertTrue(
                exception.getMessage().contains("Window 'NOPE' not found"), exception.getMessage());
    }

    @Test
    void lookupNameCompletionHintsListsTableColumns() throws Exception {
        SqlNode validated = validator.validate(parse("SELECT A FROM T"));
        SqlSelect select = (SqlSelect) validated;

        List<SqlMoniker> hints = new ArrayList<>();
        validator.lookupNameCompletionHints(
                validator.getSelectScope(select), Arrays.asList("T", ""), SqlParserPos.ZERO, hints);

        assertEquals(3, hints.size());
        assertEquals(Collections.singletonList("A"), hints.get(0).getFullyQualifiedNames());
        assertEquals(Collections.singletonList("B"), hints.get(1).getFullyQualifiedNames());
        assertEquals(Collections.singletonList("C"), hints.get(2).getFullyQualifiedNames());
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static SqlValidatorImpl newValidator() {
        CalciteSchema rootSchema = CalciteSchema.createRootSchema(true);
        rootSchema.add(
                "T",
                new AbstractTable() {
                    @Override
                    public RelDataType getRowType(RelDataTypeFactory typeFactory) {
                        return typeFactory
                                .builder()
                                .add("A", SqlTypeName.INTEGER)
                                .add("B", SqlTypeName.VARCHAR, 10)
                                .add("C", SqlTypeName.INTEGER)
                                .build();
                    }
                });

        CalciteCatalogReader catalogReader =
                new CalciteCatalogReader(
                        rootSchema,
                        Collections.emptyList(),
                        TYPE_FACTORY,
                        CalciteConnectionConfig.DEFAULT);

        return (SqlValidatorImpl)
                SqlValidatorUtil.newValidator(
                        OPERATOR_TABLE, catalogReader, TYPE_FACTORY, SqlValidator.Config.DEFAULT);
    }

    private static SqlNode parse(String sql) throws Exception {
        return SqlParser.create(sql).parseQuery();
    }

    private static CalciteContextException assertValidationError(String sql, String expected)
            throws Exception {
        SqlValidatorImpl validator = newValidator();
        CalciteContextException exception =
                assertThrows(CalciteContextException.class, () -> validator.validate(parse(sql)));
        assertTrue(
                exception.getMessage().contains(expected),
                () ->
                        "Expected message to contain <"
                                + expected
                                + "> but was: "
                                + exception.getMessage());
        return exception;
    }

    private CalciteContextException assertLiteralError(SqlLiteral literal, String expected) {
        CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class, () -> validator.validateLiteral(literal));
        assertTrue(
                exception.getMessage().contains(expected),
                () ->
                        "Expected message to contain <"
                                + expected
                                + "> but was: "
                                + exception.getMessage());
        return exception;
    }
}

