        builder.variable(corVar);
        builder.values(new String[] {"rk", "rv"}, 1, 100).as("right");
        builder.filter(builder.equals(builder.field(0), builder.field(corVar.get(), 0)));
        builder.aggregate(builder.groupKey(), builder.count(builder.field(1)));
        builder.correlate(joinType, corVar.get().id, correlationKey);
        RelNode root = builder.build();
        assertThat(root).isInstanceOf(Correlate.class);
        return new CorrelatedQuery(corVar.get(), root);
    }

    private static RelBuilder newBuilder() {
        SqlTypeFactoryImpl typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        RelOptCluster cluster =
                RelOptCluster.create(
                        new HepPlanner(new HepProgramBuilder().build()),
                        new RexBuilder(typeFactory));
        return RelFactories.LOGICAL_BUILDER.create(cluster, null);
    }

    private static RelBuilder newBuilderFor(RelNode root) {
        return RelFactories.LOGICAL_BUILDER.create(root.getCluster(), null);
    }

    private static final class CorrelatedQuery {
        private final RexCorrelVariable corVar;
        private final RelNode root;

        private CorrelatedQuery(RexCorrelVariable corVar, RelNode root) {
            this.corVar = corVar;
            this.root = root;
        }
    }
}

