    private static final RelOptTable.ViewExpander VIEW_EXPANDER =
            (rowType, queryString, schemaPath, viewPath) -> {
                throw new UnsupportedOperationException("Views are not used by these tests");
            };

    private RelDataTypeFactory typeFactory;
    private CalciteCatalogReader catalogReader;
    private SqlValidator validator;
    private RelOptCluster cluster;
    private SqlToRelConverter converter;

    @BeforeEach
    void setUp() {
        typeFactory = new SqlTypeFactoryImpl(org.apache.calcite.rel.type.RelDataTypeSystem.DEFAULT);

        final CalciteSchema rootSchema = CalciteSchema.createRootSchema(false);
        rootSchema.add("t", new TestTable("id", "name"));
        rootSchema.add("u", new TestTable("id", "score"));

        catalogReader =
                new CalciteCatalogReader(
                        rootSchema,
                        Collections.emptyList(),
                        typeFactory,
                        CalciteConnectionConfig.DEFAULT);

        validator =
                SqlValidatorUtil.newValidator(
                        SqlStdOperatorTable.instance(),
                        catalogReader,
                        typeFactory,
                        SqlValidator.Config.DEFAULT.withTypeCoercionEnabled(true));

        final VolcanoPlanner planner = new VolcanoPlanner();
        for (RelTraitDef<?> traitDef :
                Arrays.asList(
                        ConventionTraitDef.INSTANCE,
                        RelCollationTraitDef.INSTANCE,
                        RelDistributionTraitDef.INSTANCE)) {
            planner.addRelTraitDef(traitDef);
        }
        cluster = RelOptCluster.create(planner, new RexBuilder(typeFactory));
        converter = newConverter(SqlToRelConverter.CONFIG);
    }

    @Test
    void defaultConfigExposesDocumentedValuesAndIsReturnedByConfigFactory() {
        final SqlToRelConverter.Config config = SqlToRelConverter.config();

        assertSame(SqlToRelConverter.CONFIG, config);
        assertTrue(config.isDecorrelationEnabled());
        assertFalse(config.isTrimUnusedFields());
        assertTrue(config.isCreateValuesRel());
        assertFalse(config.isExplain());
        assertFalse(config.isExpand());
        assertEquals(
                SqlToRelConverter.DEFAULT_IN_SUB_QUERY_THRESHOLD, config.getInSubQueryThreshold());
        assertEquals(20, config.getInSubQueryThreshold());
        assertTrue(config.isRemoveSortInSubQuery());
        assertSame(HintStrategyTable.EMPTY, config.getHintStrategyTable());
        assertTrue(config.isAddJsonTypeOperatorEnabled());
    }

    @Test
    void configIsImmutableAndCopiesEveryOption() {
        final SqlToRelConverter.Config original = SqlToRelConverter.CONFIG;
        final UnaryOperator<RelBuilder.Config> transform =
                c -> c.withPushJoinCondition(false).withSimplify(false);

        final SqlToRelConverter.Config custom =
                original.withDecorrelationEnabled(false)
                        .withTrimUnusedFields(true)
                        .withCreateValuesRel(false)
                        .withExplain(true)
                        .withExpand(true)
                        .withInSubQueryThreshold(3)
                        .withRemoveSortInSubQuery(false)
                        .withRelBuilderConfigTransform(transform)
                        .withHintStrategyTable(HintStrategyTable.EMPTY)
                        .withAddJsonTypeOperatorEnabled(false);

        assertFalse(custom.isDecorrelationEnabled());
        assertTrue(custom.isTrimUnusedFields());
        assertFalse(custom.isCreateValuesRel());
        assertTrue(custom.isExplain());
        assertTrue(custom.isExpand());
        assertEquals(3, custom.getInSubQueryThreshold());
        assertFalse(custom.isRemoveSortInSubQuery());
        assertFalse(custom.isAddJsonTypeOperatorEnabled());
        final RelBuilder.Config relBuilderConfig =
                custom.getRelBuilderConfigTransform().apply(RelBuilder.Config.DEFAULT);
        assertFalse(relBuilderConfig.pushJoinCondition());
        assertFalse(relBuilderConfig.simplify());

        // The original, shared default configuration must not be mutated.
        assertTrue(original.isDecorrelationEnabled());
        assertFalse(original.isTrimUnusedFields());
        assertEquals(
                SqlToRelConverter.DEFAULT_IN_SUB_QUERY_THRESHOLD,
                original.getInSubQueryThreshold());
    }

    @Test
    void addRelBuilderConfigTransformComposesWithExistingTransform() {
        final SqlToRelConverter.Config config =
                SqlToRelConverter.CONFIG.addRelBuilderConfigTransform(
                        c -> c.withPushJoinCondition(false));

        final RelBuilder.Config transformed =
                config.getRelBuilderConfigTransform().apply(RelBuilder.Config.DEFAULT);
        // The default converter transform enables this option; the appended transform disables it.
        assertFalse(transformed.pushJoinCondition());
    }

    @Test
    void converterUsesSuppliedConfigurationAndExposesClusterCollaborators() {
        final SqlToRelConverter.Config config =
                SqlToRelConverter.CONFIG
                        .withInSubQueryThreshold(7)
                        .withDecorrelationEnabled(false)
                        .withTrimUnusedFields(true);
        final SqlToRelConverter customConverter = newConverter(config);

        assertSame(config, customConverter.config);
        assertSame(cluster, customConverter.getCluster());
        assertSame(cluster.getRexBuilder(), customConverter.getRexBuilder());
        assertSame(typeFactory, customConverter.getRexBuilder().getTypeFactory());
        assertEquals(7, customConverter.getInSubqueryThreshold());
        assertFalse(customConverter.enableDecorrelation());
        assertTrue(customConverter.isTrimUnusedFields());
        assertEquals(0, customConverter.getDynamicParamCount());
    }

    @Test
