                        NullPointerException.class,
                        () ->
                                new SqlToRelConverter(
                                        VIEW_EXPANDER,
                                        validator,
                                        catalogReader,
                                        cluster,
                                        StandardConvertletTable.INSTANCE,
                                        null));
        assertTrue(error.getMessage().contains("config"));
    }

    @Test
    void isOrderedRecognizesOrderedSelectsWithAndOrderByNodes() {
        assertTrue(SqlToRelConverter.isOrdered(parse("SELECT id FROM t ORDER BY id")));
        assertTrue(SqlToRelConverter.isOrdered(parse("SELECT id FROM t ORDER BY id DESC")));
        assertTrue(
                SqlToRelConverter.isOrdered(
                        parse("WITH x AS (SELECT id FROM t) SELECT id FROM x ORDER BY id")));
        assertTrue(
                SqlToRelConverter.isOrdered(parse("SELECT id FROM t ORDER BY id OFFSET 1 ROWS")));
    }

    @Test
    void isOrderedReturnsFalseForUnorderedOrNonQueryTopLevelNodes() {
        assertFalse(SqlToRelConverter.isOrdered(parse("SELECT id FROM t")));
        assertFalse(
                SqlToRelConverter.isOrdered(
                        parse("WITH x AS (SELECT id FROM t) SELECT id FROM x")));
        assertFalse(SqlToRelConverter.isOrdered(parse("INSERT INTO t SELECT id FROM u")));
        assertFalse(
                SqlToRelConverter.isOrdered(
                        parse("(SELECT id FROM t ORDER BY id) UNION ALL (SELECT id FROM t)")));
    }

    @Test
    void convertQueryConvertsProjectionFilterAndDescendingSort() {
        final RelRoot root =
                convertQuery("SELECT id, name FROM t WHERE id > 10 ORDER BY name DESC");

        assertEquals(SqlKind.SELECT, root.kind);
        assertEquals(Arrays.asList("id", "name"), root.validatedRowType.getFieldNames());
        assertEquals(Arrays.asList("id", "name"), root.rel.getRowType().getFieldNames());

        assertNotNull(firstNodeOfType(root.rel, LogicalProject.class));
        final Filter filter = firstNodeOfType(root.rel, Filter.class);
        assertNotNull(filter);
        assertEquals(SqlKind.GREATER_THAN, filter.getCondition().getKind());

        final Sort sort = firstNodeOfType(root.rel, Sort.class);
        assertNotNull(sort);
        final RelCollation collation = sort.getCollation();
        assertEquals(1, collation.getFieldCollations().size());
        assertEquals(
                org.apache.calcite.rel.RelFieldCollation.Direction.DESCENDING,
                collation.getFieldCollations().get(0).getDirection());
    }

    @Test
    void convertQueryPreservesOffsetAndFetchOnSort() {
        final RelRoot root =
                convertQuery("SELECT id FROM t ORDER BY id OFFSET 2 ROWS FETCH NEXT 5 ROWS ONLY");

        final Sort sort = firstNodeOfType(root.rel, Sort.class);
        assertNotNull(sort);
        assertEquals(2, RexLiteral.intValue(sort.offset));
        assertEquals(5, RexLiteral.intValue(sort.fetch));
    }

    @Test
    void queryHintsAreCapitalizedAndPropagatedDuringConversion() {
        final SqlToRelConverter hintConverter =
                newConverter(
                        SqlToRelConverter.CONFIG.withHintStrategyTable(
                                FlinkHintStrategies.createHintStrategyTable()));

        final RelRoot root =
                hintConverter.convertQuery(
                        validate(
                                "SELECT /*+ broadcast(u) */ t.id FROM t JOIN u "
                                        + "ON t.id = u.id"),
                        false,
                        true);

        assertNotNull(firstNodeOfType(root.rel, LogicalJoin.class));
        assertTrue(
                root.hints.stream().anyMatch(hint -> "BROADCAST".equalsIgnoreCase(hint.hintName)));
        assertTrue(allHints(root.rel).stream().anyMatch(hint -> "BROADCAST".equals(hint.hintName)));
    }

    @Test
    void containsQueryHintsAttachesInternalQueryBlockAlias() {
        final SqlToRelConverter.Config config =
                SqlToRelConverter.CONFIG.withHintStrategyTable(
                        FlinkHintStrategies.createHintStrategyTable());
        final String sql = "SELECT * FROM (SELECT * FROM t JOIN u ON t.id = u.id) AS j";

        final SqlToRelConverter withoutQueryHints = newConverter(config);
        final RelRoot rootWithoutAlias = withoutQueryHints.convertQuery(validate(sql), false, true);
        assertFalse(
                allHints(rootWithoutAlias.rel).stream()
                        .anyMatch(hint -> FlinkHints.HINT_ALIAS.equals(hint.hintName)));

        final SqlToRelConverter withQueryHints = newConverter(config);
        withQueryHints.containsQueryHints();
        final RelRoot rootWithAlias = withQueryHints.convertQuery(validate(sql), false, true);

        assertTrue(
                allHints(rootWithAlias.rel).stream()
                        .anyMatch(
                                hint ->
                                        FlinkHints.HINT_ALIAS.equals(hint.hintName)
                                                && hint.listOptions.contains("j")));
    }

    @Test
    void convertQueryConvertsDistinctToAggregate() {
        final RelRoot root = convertQuery("SELECT DISTINCT id FROM t");

        final Aggregate aggregate = firstNodeOfType(root.rel, Aggregate.class);
        assertNotNull(aggregate);
        assertEquals(1, aggregate.getGroupCount());
        assertEquals(0, aggregate.getAggCallList().size());
        assertEquals(Arrays.asList("id"), root.rel.getRowType().getFieldNames());
    }

    @Test
    void convertQueryConvertsUnionAllToLogicalUnion() {
        final RelRoot root = convertQuery("SELECT id FROM t UNION ALL SELECT id FROM u");

        final LogicalUnion union = assertInstanceOf(LogicalUnion.class, root.rel);
        assertTrue(union.all);
        assertEquals(2, union.getInputs().size());
        assertEquals(Arrays.asList("id"), union.getRowType().getFieldNames());
        assertEquals(SqlKind.UNION, root.kind);
    }

    @Test
    void convertQueryExpandsWithClause() {
        final RelRoot root =
                convertQuery("WITH x AS (SELECT id FROM t WHERE id > 1) SELECT id FROM x");

        assertEquals(SqlKind.WITH, root.kind);
        assertEquals(Arrays.asList("id"), root.rel.getRowType().getFieldNames());
        assertNotNull(firstNodeOfType(root.rel, Filter.class));
        assertNotNull(firstNodeOfType(root.rel, LogicalTableScan.class));
    }

    @Test
    void convertQueryInfersDynamicParameterCountAndType() {
        final RelRoot root = convertQuery("SELECT id + ? FROM t");

        assertEquals(1, converter.getDynamicParamCount());
        assertEquals(SqlTypeName.INTEGER, converter.getDynamicParamType(0).getSqlTypeName());
        final RexCall projectExpression =
                assertInstanceOf(RexCall.class, ((LogicalProject) root.rel).getProjects().get(0));
        assertTrue(projectExpression.getOperands().get(1) instanceof RexDynamicParam);
        assertEquals(0, ((RexDynamicParam) projectExpression.getOperands().get(1)).getIndex());
    }

    @Test
    void convertDynamicParamRegistersParameterAndReturnsRexParameter() {
        final SqlSelect select = (SqlSelect) validate("SELECT ? + id FROM t");
        final SqlCall expression = (SqlCall) select.getSelectList().get(0);
        final SqlDynamicParam sqlParam =
                assertInstanceOf(SqlDynamicParam.class, expression.operand(0));

        final RexDynamicParam rexParam = converter.convertDynamicParam(sqlParam);

        assertEquals(0, rexParam.getIndex());
        assertEquals(1, converter.getDynamicParamCount());
        assertEquals(SqlTypeName.INTEGER, converter.getDynamicParamType(0).getSqlTypeName());
        assertThrows(IndexOutOfBoundsException.class, () -> converter.getDynamicParamType(1));
    }

    @Test
    void convertExpressionConvertsArithmeticWithoutAQuery() {
        final SqlNode expression = parseExpression("1 + 2");
        final RexNode rex = converter.convertExpression(expression);

        final RexCall call = assertInstanceOf(RexCall.class, rex);
        assertEquals(SqlKind.PLUS, call.getKind());
        assertEquals(SqlTypeName.INTEGER, rex.getType().getSqlTypeName());
        assertEquals(2, call.operandCount());
    }

    @Test
    void convertExpressionMapsIdentifiersUsingProvidedInputReferences() {
        final SqlNode expression = parseExpression("x + 1");
        final RexInputRef inputRef =
                converter
                        .getRexBuilder()
                        .makeInputRef(typeFactory.createSqlType(SqlTypeName.INTEGER), 0);
        final Map<String, RexNode> names = new LinkedHashMap<>();
        names.put("x", inputRef);

        final RexCall call =
                assertInstanceOf(RexCall.class, converter.convertExpression(expression, names));

        assertEquals(SqlKind.PLUS, call.getKind());
        assertSame(inputRef, call.getOperands().get(0));
    }

    @Test
    void convertValuesCreatesLogicalValuesWithTwoRows() {
        final SqlCall values = (SqlCall) parse("VALUES (1, 'a'), (2, 'b')");
        final RelNode rel = converter.convertValues((SqlCall) validator.validate(values), null);

        final LogicalValues logicalValues = assertInstanceOf(LogicalValues.class, rel);
        assertEquals(2, logicalValues.getTuples().size());
        assertEquals(2, logicalValues.getRowType().getFieldCount());
        assertEquals(1, logicalValues.getTuples().get(0).get(0).getValueAs(Integer.class));
    }

    @Test
    void toRelBuildsTableScanAndPreservesTableRowType() {
        final RelOptTable table = catalogReader.getTable(Arrays.asList("t"));
        final RelNode scan = converter.toRel(table, Collections.emptyList());

        final LogicalTableScan tableScan = assertInstanceOf(LogicalTableScan.class, scan);
        assertEquals(Arrays.asList("id", "name"), tableScan.getRowType().getFieldNames());
        assertEquals(table, tableScan.getTable());
    }

    @Test
    void convertedNonCorrelatedSubqueryMapIsLiveAndAdditive() {
        final SqlSelect select = (SqlSelect) validate("SELECT 1 FROM t");
        final RexNode one = converter.convertExpression(select.getSelectList().get(0));
        final Map<SqlNode, RexNode> additions = new HashMap<>();
        additions.put(select, one);

        converter.addConvertedNonCorrSubqs(additions);

        assertSame(one, converter.getMapConvertedNonCorrSubqs().get(select));
        assertSame(
                converter.getMapConvertedNonCorrSubqs(), converter.getMapConvertedNonCorrSubqs());
        assertEquals(1, converter.getMapConvertedNonCorrSubqs().size());
    }

    @Test
    void explainDynamicParameterCounterReturnsPreviousValueAndCanBeSet() {
        final SqlToRelConverter explainConverter =
                newConverter(SqlToRelConverter.CONFIG.withExplain(true));

        assertEquals(0, explainConverter.getDynamicParamCountInExplain(false));
        assertEquals(0, explainConverter.getDynamicParamCountInExplain(true));
        assertEquals(1, explainConverter.getDynamicParamCountInExplain(true));
        assertEquals(2, explainConverter.getDynamicParamCountInExplain(false));

        explainConverter.setDynamicParamCountInExplain(9);
        assertEquals(9, explainConverter.getDynamicParamCountInExplain(false));
    }

    private SqlToRelConverter newConverter(SqlToRelConverter.Config config) {
        return new SqlToRelConverter(
                VIEW_EXPANDER,
                validator,
                catalogReader,
                cluster,
                StandardConvertletTable.INSTANCE,
                config);
    }

    private RelRoot convertQuery(String sql) {
        return converter.convertQuery(validate(sql), false, true);
    }

    private SqlNode validate(String sql) {
        return validator.validate(parse(sql));
    }

    private static SqlParser.Config parserConfig() {
        return SqlParser.config().withUnquotedCasing(Casing.TO_LOWER);
    }

    private static SqlNode parse(String sql) {
        try {
            return SqlParser.create(sql, parserConfig()).parseQuery();
        } catch (Exception e) {
            throw new AssertionError("Could not parse SQL: " + sql, e);
        }
    }

    private static SqlNode parseExpression(String expression) {
        try {
            return SqlParser.create(expression, parserConfig()).parseExpression();
        } catch (Exception e) {
            throw new AssertionError("Could not parse expression: " + expression, e);
        }
    }

    private static <T extends RelNode> T firstNodeOfType(RelNode root, Class<T> type) {
        final List<T> nodes = nodesOfType(root, type);
        return nodes.isEmpty() ? null : nodes.get(0);
    }

    private static List<RelHint> allHints(RelNode root) {
        final List<RelHint> hints = new ArrayList<>();
        new RelVisitor() {
            @Override
            public void visit(RelNode node, int ordinal, RelNode parent) {
                if (node instanceof Hintable) {
                    hints.addAll(((Hintable) node).getHints());
                }
                super.visit(node, ordinal, parent);
            }
        }.go(root);
        return hints;
    }

    private static <T extends RelNode> List<T> nodesOfType(RelNode root, Class<T> type) {
        final List<T> nodes = new ArrayList<>();
        new RelVisitor() {
            @Override
            public void visit(RelNode node, int ordinal, RelNode parent) {
                if (type.isInstance(node)) {
                    nodes.add(type.cast(node));
                }
                super.visit(node, ordinal, parent);
            }
        }.go(root);
        return nodes;
    }

    private static final class TestTable extends AbstractTable {
        private final String[] columnNames;

        private TestTable(String... columnNames) {
            this.columnNames = columnNames;
        }

        @Override
        public RelDataType getRowType(RelDataTypeFactory typeFactory) {
            final RelDataTypeFactory.Builder builder = typeFactory.builder();
            for (String columnName : columnNames) {
                final SqlTypeName type =
                        "name".equals(columnName) ? SqlTypeName.VARCHAR : SqlTypeName.INTEGER;
                builder.add(columnName, type);
            }
            return builder.build();
        }
    }
}

