                                "cd_b_f"),
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(2),
                                3,
                                SqlTypeName.BIGINT,
                                "cd_c_f"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        final LogicalAggregate groupingSetsAggregate =
                findAggregates(rewritten).stream()
                        .filter(agg -> agg.getGroupSets().size() > 1)
                        .findFirst()
                        .get();
        // the filter argument becomes part of the grouping sets of the intermediate aggregate
        assertThat(groupingSetsAggregate.getGroupSet().toString()).isEqualTo("{0, 1, 2, 3}");
        assertThat(
                        groupingSetsAggregate.getGroupSets().stream()
                                .map(ImmutableBitSet::toString)
                                .collect(Collectors.toList()))
                .containsExactlyInAnyOrder("{0, 1, 3}", "{0, 2, 3}");

        // the flag columns merge the grouping set marker with the aggregate filter
        final LogicalProject flagProject =
                findNodes(rewritten, LogicalProject.class).stream()
                        .filter(
                                project ->
                                        project.getProjects().stream()
                                                .anyMatch(node -> node.getKind() == SqlKind.AND))
                        .findFirst()
                        .get();
        long conjunctions = 0;
        for (RexNode projection : flagProject.getProjects()) {
            if (projection.getKind() == SqlKind.AND) {
                conjunctions++;
                final RexCall and = asCall(projection);
                assertThat(and.getOperands()).hasSize(2);
                assertThat(and.getOperands().get(0).getKind()).isEqualTo(SqlKind.EQUALS);
                // the flag column of the input relation is the second operand
                assertThat(((RexInputRef) and.getOperands().get(1)).getIndex()).isEqualTo(3);
            }
        }
        assertThat(conjunctions).isEqualTo(2);
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testGroupingSetsRewriteReturnsZeroForCountOnEmptyGroup() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                false,
                                false,
                                new ArrayList<>(),
                                -1,
                                SqlTypeName.BIGINT,
                                "cnt"),
                        countDistinctB());

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        // COUNT(*) must return 0 (and not NULL) if the input is empty; the rule therefore wraps
        // the aggregated count into a CASE expression with 0 as default value.
        final LogicalProject project = (LogicalProject) rewritten;
        final RexCall caseCall = asCall(project.getProjects().get(0));
        assertThat(caseCall.getOperator()).isEqualTo(SqlStdOperatorTable.CASE);
        assertThat(caseCall.getOperands()).hasSize(3);
        assertThat(caseCall.getOperands().get(0).getKind()).isEqualTo(SqlKind.IS_NOT_NULL);
        assertThat(caseCall.getOperands().get(2)).isInstanceOf(RexLiteral.class);
        assertThat(((RexLiteral) caseCall.getOperands().get(2)).getValueAs(BigDecimal.class))
                .isEqualTo(BigDecimal.ZERO);
