 * aggregate calls into plans made of several aggregates (and possibly joins or grouping sets). Each
 * test builds a small logical aggregate on top of an empty values relation, fires the rule in a
 * {@link HepPlanner} and inspects the shape of the rewritten plan.
 */
class FlinkAggregateExpandDistinctAggregatesRuleTests {

    private static final RelDataTypeFactory TYPE_FACTORY = new JavaTypeFactoryImpl();

    private RelOptCluster cluster;
    private RelNode input;

    @BeforeEach
    void setUp() {
        final HepPlanner planner = new HepPlanner(new HepProgramBuilder().build());
        cluster = RelOptCluster.create(planner, new RexBuilder(TYPE_FACTORY));
        final RelDataType rowType =
                TYPE_FACTORY
                        .builder()
                        .add("a", SqlTypeName.INTEGER)
                        .add("b", SqlTypeName.INTEGER)
                        .add("c", SqlTypeName.DOUBLE)
                        .add(
                                "flag",
                                TYPE_FACTORY.createTypeWithNullability(
                                        TYPE_FACTORY.createSqlType(SqlTypeName.BOOLEAN), false))
                        .build();
        input = LogicalValues.createEmpty(cluster, rowType);
    }

    // ------------------------------------------------------------------------------------------
    // Rule configuration
    // ------------------------------------------------------------------------------------------

    @Test
    void testRuleInstancesAndConstructorConfigureGroupingSetMode() {
        assertThat(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.useGroupingSets).isTrue();
        assertThat(FlinkAggregateExpandDistinctAggregatesRule.JOIN.useGroupingSets).isFalse();

        final FlinkAggregateExpandDistinctAggregatesRule customRule =
                new FlinkAggregateExpandDistinctAggregatesRule(
                        LogicalAggregate.class, false, RelFactories.LOGICAL_BUILDER);

        assertThat(customRule.useGroupingSets).isFalse();
        assertThat(customRule.getOperand().getMatchedClass()).isEqualTo(LogicalAggregate.class);
        assertThat(
                        FlinkAggregateExpandDistinctAggregatesRule.INSTANCE
                                .getOperand()
                                .getMatchedClass())
                .isEqualTo(LogicalAggregate.class);
        assertThat(FlinkAggregateExpandDistinctAggregatesRule.JOIN.getOperand().getMatchedClass())
                .isEqualTo(LogicalAggregate.class);
    }

    // ------------------------------------------------------------------------------------------
    // Cases in which the rule must not fire
    // ------------------------------------------------------------------------------------------

    @Test
    void testAggregateWithoutDistinctCallIsLeftUnchanged() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                false,
                                false,
                                new ArrayList<>(),
                                -1,
                                SqlTypeName.BIGINT,
                                "cnt"),
                        sumOfC("sum_c"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        assertThat(planText(rewritten)).isEqualTo(planText(aggregate));
        assertThat(findNodes(rewritten, Join.class)).isEmpty();
        assertThat(findAggregates(rewritten)).hasSize(1);
    }

    @Test
    void testAggregateWithOnlyApproximateDistinctCallIsLeftUnchanged() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                true,
                                Arrays.asList(1),
                                -1,
                                SqlTypeName.BIGINT,
                                "approx_cnt_b"),
                        sumOfC("sum_c"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        assertThat(planText(rewritten)).isEqualTo(planText(aggregate));
        assertThat(findAggregates(rewritten).get(0).getAggCallList().get(0).isDistinct()).isTrue();
    }

    @Test
    void testAggregateWithGroupingSetsIsLeftUnchanged() {
        final RelNode aggregate =
                LogicalAggregate.create(
                        input,
                        ImmutableBitSet.of(0),
                        groupSets(ImmutableBitSet.of(0), ImmutableBitSet.of(0, 1)),
                        Arrays.asList(countDistinctB()));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        assertThat(planText(rewritten)).isEqualTo(planText(aggregate));
        assertThat(findAggregates(rewritten)).hasSize(1);
    }

    @Test
    void testAggregateWithApproximateAndAccurateDistinctCallsIsRejected() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        countDistinctB(),
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                true,
                                Arrays.asList(2),
                                -1,
                                SqlTypeName.BIGINT,
                                "approx_cnt_c"));

        assertThatThrownBy(
                        () ->
                                applyRule(
                                        FlinkAggregateExpandDistinctAggregatesRule.INSTANCE,
                                        aggregate))
                .isInstanceOf(TableException.class)
                .hasMessageContaining(
                        "There are both Distinct AggCall and Approximate Distinct AggCall "
                                + "in one sql statement");
    }

    // ------------------------------------------------------------------------------------------
    // Single distinct argument set: "monopole" rewrite
    // ------------------------------------------------------------------------------------------

    @Test
    void testSingleDistinctArgumentSetIsRewrittenAsDistinctSelectionAndAggregate() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(2),
                                -1,
                                SqlTypeName.BIGINT,
                                "cd_c"),
                        aggregateCall(
                                SqlStdOperatorTable.SUM,
                                true,
                                false,
                                Arrays.asList(2),
                                -1,
                                SqlTypeName.DOUBLE,
                                "sd_c"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        assertThat(planText(rewritten))
                .isEqualTo(
                        "LogicalAggregate(group=[{0}], cd_c=[COUNT($1)], sd_c=[SUM($1)])\n"
                                + "  LogicalAggregate(group=[{0, 1}])\n"
                                + "    LogicalProject(a=[$0], c=[$2])\n"
                                + "      LogicalValues(tuples=[[]])\n");

        assertThat(findNodes(rewritten, Join.class)).isEmpty();
        final List<LogicalAggregate> aggregates = findAggregates(rewritten);
        assertThat(aggregates).hasSize(2);
        // the intermediate relation selects the distinct group key/argument combinations only
        assertThat(aggregates.get(1).getAggCallList()).isEmpty();
        assertThat(aggregates.get(1).getGroupSet().toString()).isEqualTo("{0, 1}");
        // both original distinct calls are re-written to reference the distinct argument
        for (AggregateCall call : aggregates.get(0).getAggCallList()) {
            assertThat(call.isDistinct()).isFalse();
            assertThat(call.getArgList()).containsExactly(1);
        }
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testDistinctAggregatesSharingArgumentsAreRewrittenTogether() {
        // COUNT(DISTINCT b) and MIN(b): MIN/MAX/BIT_AND/BIT_OR ignore the DISTINCT flag, therefore
        // the single argument set {b} can still be handled by the monopole rewrite.
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        countDistinctB(),
                        aggregateCall(
                                SqlStdOperatorTable.MIN,
                                false,
                                false,
                                Arrays.asList(1),
                                -1,
                                SqlTypeName.INTEGER,
                                "min_b"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        assertThat(planText(rewritten))
                .isEqualTo(
                        "LogicalAggregate(group=[{0}], cd_b=[COUNT($1)], min_b=[MIN($1)])\n"
                                + "  LogicalAggregate(group=[{0, 1}])\n"
                                + "    LogicalProject(a=[$0], b=[$1])\n"
                                + "      LogicalValues(tuples=[[]])\n");
        assertThat(findNodes(rewritten, Join.class)).isEmpty();
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testMonopoleRewriteWithFilterUsesConditionalDistinctSelection() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(1),
                                3,
                                SqlTypeName.BIGINT,
                                "cd_b_f"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        // SELECT DISTINCT a, flag, CASE WHEN flag THEN b ELSE NULL END
        final List<LogicalProject> projects = findNodes(rewritten, LogicalProject.class);
        assertThat(projects).hasSize(1);
        final List<RexNode> projections = projects.get(0).getProjects();
        assertThat(projections).hasSize(3);
        final RexCall caseCall = asCall(projections.get(2));
        assertThat(caseCall.getOperator()).isEqualTo(SqlStdOperatorTable.CASE);
        assertThat(((RexInputRef) caseCall.getOperands().get(0)).getIndex()).isEqualTo(3);
        assertThat(caseCall.getOperands().get(1)).isInstanceOf(RexInputRef.class);
        assertThat(((RexInputRef) caseCall.getOperands().get(1)).getIndex()).isEqualTo(1);
        assertThat(caseCall.getOperands().get(2)).isInstanceOf(RexLiteral.class);
        assertThat(((RexLiteral) caseCall.getOperands().get(2)).isNull()).isTrue();

        final LogicalAggregate distinctSelection =
                findAggregates(rewritten).stream()
                        .filter(agg -> agg.getAggCallList().isEmpty())
                        .findFirst()
                        .get();
        assertThat(distinctSelection.getGroupSet().toString()).isEqualTo("{0, 1, 2}");
        assertRowTypePreserved(rewritten, aggregate);
    }

    // ------------------------------------------------------------------------------------------
    // One distinct call plus non-distinct calls: multi-phase aggregation
    // ------------------------------------------------------------------------------------------

    @Test
    void testSingletonDistinctAggregateIsRewrittenAsTwoPhaseAggregation() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                false,
                                false,
                                new ArrayList<>(),
                                -1,
                                SqlTypeName.BIGINT,
                                "cnt"),
                        sumOfC("sum_c"),
                        countDistinctB());

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        assertThat(findNodes(rewritten, Join.class)).isEmpty();
        final List<LogicalAggregate> aggregates = findAggregates(rewritten);
        assertThat(aggregates).hasSize(2);

        final LogicalAggregate topAggregate = aggregates.get(0);
        final LogicalAggregate bottomAggregate = aggregates.get(1);

        // the distinct argument becomes part of the group key of the bottom aggregate
        assertThat(bottomAggregate.getGroupSet().toString()).isEqualTo("{0, 1}");
        assertThat(bottomAggregate.getAggCallList()).hasSize(2);
        assertThat(bottomAggregate.getAggCallList().get(0).getAggregation().getKind())
                .isEqualTo(SqlKind.COUNT);
        assertThat(bottomAggregate.getAggCallList().get(1).getAggregation().getKind())
                .isEqualTo(SqlKind.SUM);

        // COUNT becomes SUM0 on the top aggregate, the other calls are re-aggregated over the
        // partial results, and the distinct call is turned into a plain COUNT of the group key
        final List<AggregateCall> topCalls = topAggregate.getAggCallList();
        assertThat(topCalls).hasSize(3);
        assertThat(topCalls.get(0).getAggregation().getKind()).isEqualTo(SqlKind.SUM0);
        assertThat(topCalls.get(1).getAggregation().getKind()).isEqualTo(SqlKind.SUM);
        assertThat(topCalls.get(2).getAggregation().getKind()).isEqualTo(SqlKind.COUNT);
        assertThat(topCalls.get(2).isDistinct()).isFalse();
        assertThat(topCalls.get(2).getArgList()).containsExactly(1);
        assertThat(topAggregate.getGroupSet().toString()).isEqualTo("{0}");

        assertRowTypePreserved(rewritten, aggregate);
    }

    // ------------------------------------------------------------------------------------------
    // Several distinct argument sets: join rewrite
    // ------------------------------------------------------------------------------------------

    @Test
    void testMultipleDistinctArgumentSetsAreJoinedUsingNullSafeEquality() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        countDistinctB(),
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(2),
                                -1,
                                SqlTypeName.BIGINT,
                                "cd_c"),
                        aggregateCall(
                                SqlStdOperatorTable.AVG,
                                false,
                                false,
                                Arrays.asList(2),
                                -1,
                                SqlTypeName.DOUBLE,
                                "avg_c"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        final List<Join> joins = findNodes(rewritten, Join.class);
        assertThat(joins).hasSize(2);
        for (Join join : joins) {
            final RexCall condition = asCall(join.getCondition());
            assertThat(condition.getOperator())
                    .isEqualTo(SqlStdOperatorTable.IS_NOT_DISTINCT_FROM);
        }

        // two aggregates per distinct argument set plus one for the non-distinct aggregate
        assertThat(findAggregates(rewritten)).hasSize(5);
        // every DISTINCT call is gone, the distinct arguments are aggregated as group keys
        for (LogicalAggregate agg : findAggregates(rewritten)) {
            for (AggregateCall call : agg.getAggCallList()) {
                assertThat(call.isDistinct()).isFalse();
            }
        }

        final LogicalProject project = (LogicalProject) rewritten;
        assertThat(project.getProjects()).hasSize(4);
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testDistinctAggregatesWithFilterAreRewrittenWithConditionalProjection() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(1),
                                3,
                                SqlTypeName.BIGINT,
                                "cd_b_f"),
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(2),
                                3,
                                SqlTypeName.BIGINT,
                                "cd_c_f"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        assertThat(findNodes(rewritten, Join.class)).hasSize(1);
        assertThat(findAggregates(rewritten)).hasSize(4);

        // per distinct argument set: one projection containing a CASE over the filter flag
        final List<LogicalProject> projects = findNodes(rewritten, LogicalProject.class);
        assertThat(projects).hasSize(3);
        final List<RexCall> caseCalls = new ArrayList<>();
        for (LogicalProject project : projects) {
            for (RexNode projection : project.getProjects()) {
                if (projection.getKind() == SqlKind.CASE) {
                    caseCalls.add(asCall(projection));
                }
            }
        }
        assertThat(caseCalls).hasSize(2);
        for (RexCall caseCall : caseCalls) {
            assertThat(caseCall.getOperator()).isEqualTo(SqlStdOperatorTable.CASE);
            assertThat(caseCall.getOperands()).hasSize(3);
            // the filter flag is the first operand of the CASE expression
            assertThat(((RexInputRef) caseCall.getOperands().get(0)).getIndex()).isEqualTo(3);
            assertThat(caseCall.getOperands().get(2)).isInstanceOf(RexLiteral.class);
        }

        // the rewritten aggregate calls keep a filter pointing at the projected flag column
        long filteredCalls = 0;
        for (LogicalAggregate agg : findAggregates(rewritten)) {
            for (AggregateCall call : agg.getAggCallList()) {
                if (call.filterArg >= 0) {
                    filteredCalls++;
                }
            }
        }
        assertThat(filteredCalls).isEqualTo(2);
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testDistinctAggregateOnGroupingKeyReusesGroupingKeySelection() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(0),
                                -1,
                                SqlTypeName.BIGINT,
                                "cd_a"),
                        countDistinctB());

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        assertThat(findNodes(rewritten, Join.class)).hasSize(1);
        final List<LogicalAggregate> distinctSelections =
                findAggregates(rewritten).stream()
                        .filter(agg -> agg.getAggCallList().isEmpty())
                        .collect(Collectors.toList());
        // the distinct argument 'a' is already the group key, hence it is not projected twice
        assertThat(distinctSelections).hasSize(2);
        assertThat(
                        distinctSelections.stream()
                                .map(LogicalAggregate::getGroupCount)
                                .sorted()
                                .collect(Collectors.toList()))
                .containsExactly(1, 2);
        assertRowTypePreserved(rewritten, aggregate);
    }

    // ------------------------------------------------------------------------------------------
    // Several distinct argument sets: grouping sets rewrite
    // ------------------------------------------------------------------------------------------

    @Test
    void testMultipleDistinctArgumentSetsAreRewrittenUsingGroupingSets() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        countDistinctB(),
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(2),
                                -1,
                                SqlTypeName.BIGINT,
                                "cd_c"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        assertThat(findNodes(rewritten, Join.class)).isEmpty();
        final List<LogicalAggregate> aggregates = findAggregates(rewritten);
        assertThat(aggregates).hasSize(2);

        final LogicalAggregate groupingSetsAggregate =
                aggregates.stream()
                        .filter(agg -> agg.getGroupSets().size() > 1)
                        .findFirst()
                        .get();
        assertThat(groupingSetsAggregate.getGroupSet().toString()).isEqualTo("{0, 1, 2}");
        assertThat(groupingSetsAggregate.getGroupSets()).hasSize(2);
        assertThat(
                        groupingSetsAggregate.getGroupSets().stream()
                                .map(ImmutableBitSet::toString)
                                .collect(Collectors.toList()))
                .containsExactlyInAnyOrder("{0, 1}", "{0, 2}");
        // the GROUPING call creates the marker column which identifies the active grouping set
        assertThat(groupingSetsAggregate.getAggCallList()).hasSize(1);
        assertThat(groupingSetsAggregate.getAggCallList().get(0).getAggregation().getKind())
                .isEqualTo(SqlKind.GROUPING);
        assertThat(groupingSetsAggregate.getAggCallList().get(0).getName()).isEqualTo("$g");

        // the marker column is translated into boolean flags which filter the distinct counts
        final LogicalProject flagProject =
                findNodes(rewritten, LogicalProject.class).stream()
                        .filter(
                                project ->
                                        project.getProjects().stream()
                                                .anyMatch(node -> node.getKind() == SqlKind.EQUALS))
                        .findFirst()
                        .get();
        long flags = 0;
        for (RexNode projection : flagProject.getProjects()) {
            if (projection.getKind() == SqlKind.EQUALS) {
                flags++;
            }
        }
        assertThat(flags).isEqualTo(2);

        final LogicalAggregate topAggregate = aggregates.get(0);
        assertThat(topAggregate.getGroupSet().toString()).isEqualTo("{0}");
        assertThat(topAggregate.getAggCallList()).hasSize(2);
        for (AggregateCall call : topAggregate.getAggCallList()) {
            assertThat(call.getAggregation().getKind()).isEqualTo(SqlKind.COUNT);
            assertThat(call.isDistinct()).isFalse();
            assertThat(call.filterArg).isGreaterThanOrEqualTo(0);
        }
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testGroupingSetsRewriteMergesDistinctFilterIntoFlagProjection() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(0),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(1),
                                3,
                                SqlTypeName.BIGINT,
                                "cd_b_f"),
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                false,
                                Arrays.asList(2),
                                3,
                                SqlTypeName.BIGINT,
                                "cd_c_f"));

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        final LogicalAggregate groupingSetsAggregate =
                findAggregates(rewritten).stream()
                        .filter(agg -> agg.getGroupSets().size() > 1)
                        .findFirst()
                        .get();
        // the filter argument becomes part of the grouping sets of the intermediate aggregate
        assertThat(groupingSetsAggregate.getGroupSet().toString()).isEqualTo("{0, 1, 2, 3}");
        assertThat(
                        groupingSetsAggregate.getGroupSets().stream()
                                .map(ImmutableBitSet::toString)
                                .collect(Collectors.toList()))
                .containsExactlyInAnyOrder("{0, 1, 3}", "{0, 2, 3}");

        // the flag columns merge the grouping set marker with the aggregate filter
        final LogicalProject flagProject =
                findNodes(rewritten, LogicalProject.class).stream()
                        .filter(
                                project ->
                                        project.getProjects().stream()
                                                .anyMatch(node -> node.getKind() == SqlKind.AND))
                        .findFirst()
                        .get();
        long conjunctions = 0;
        for (RexNode projection : flagProject.getProjects()) {
            if (projection.getKind() == SqlKind.AND) {
                conjunctions++;
                final RexCall and = asCall(projection);
                assertThat(and.getOperands()).hasSize(2);
                assertThat(and.getOperands().get(0).getKind()).isEqualTo(SqlKind.EQUALS);
                // the flag column of the input relation is the second operand
                assertThat(((RexInputRef) and.getOperands().get(1)).getIndex()).isEqualTo(3);
            }
        }
        assertThat(conjunctions).isEqualTo(2);
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testGroupingSetsRewriteReturnsZeroForCountOnEmptyGroup() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                false,
                                false,
                                new ArrayList<>(),
                                -1,
                                SqlTypeName.BIGINT,
                                "cnt"),
                        countDistinctB());

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.INSTANCE, aggregate);

        // COUNT(*) must return 0 (and not NULL) if the input is empty; the rule therefore wraps
        // the aggregated count into a CASE expression with 0 as default value.
        final LogicalProject project = (LogicalProject) rewritten;
        final RexCall caseCall = asCall(project.getProjects().get(0));
        assertThat(caseCall.getOperator()).isEqualTo(SqlStdOperatorTable.CASE);
        assertThat(caseCall.getOperands()).hasSize(3);
        assertThat(caseCall.getOperands().get(0).getKind()).isEqualTo(SqlKind.IS_NOT_NULL);
        assertThat(caseCall.getOperands().get(2)).isInstanceOf(RexLiteral.class);
        assertThat(((RexLiteral) caseCall.getOperands().get(2)).getValueAs(BigDecimal.class))
                .isEqualTo(BigDecimal.ZERO);
        assertRowTypePreserved(rewritten, aggregate);
    }

    @Test
    void testJoinRewriteUsesSumEmptyIsZeroForCountOnEmptyGroup() {
        final RelNode aggregate =
                aggregate(
                        ImmutableBitSet.of(),
                        null,
                        aggregateCall(
                                SqlStdOperatorTable.COUNT,
                                false,
                                false,
                                new ArrayList<>(),
                                -1,
                                SqlTypeName.BIGINT,
                                "cnt"),
                        countDistinctB());

        final RelNode rewritten =
                applyRule(FlinkAggregateExpandDistinctAggregatesRule.JOIN, aggregate);

        final LogicalAggregate topAggregate = findAggregates(rewritten).get(0);
        assertThat(topAggregate.getAggCallList()).hasSize(2);
        assertThat(topAggregate.getAggCallList().get(0).getAggregation().getKind())
                .isEqualTo(SqlKind.SUM0);
        assertThat(topAggregate.getAggCallList().get(1).getAggregation().getKind())
                .isEqualTo(SqlKind.COUNT);
        assertThat(topAggregate.getAggCallList().get(1).isDistinct()).isFalse();
        assertRowTypePreserved(rewritten, aggregate);
    }

    // ------------------------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------------------------

    private RelNode aggregate(
            ImmutableBitSet groupSet, List<ImmutableBitSet> groupSets, AggregateCall... calls) {
        return LogicalAggregate.create(input, groupSet, groupSets, Arrays.asList(calls));
    }

    private AggregateCall countDistinctB() {
        return aggregateCall(
                SqlStdOperatorTable.COUNT,
                true,
                false,
                Arrays.asList(1),
                -1,
                SqlTypeName.BIGINT,
                "cd_b");
    }

    private AggregateCall sumOfC(String name) {
        return aggregateCall(
                SqlStdOperatorTable.SUM,
                false,
                false,
                Arrays.asList(2),
                -1,
                SqlTypeName.DOUBLE,
                name);
    }

    private AggregateCall aggregateCall(
            SqlAggFunction function,
            boolean distinct,
            boolean approximate,
            List<Integer> argList,
            int filterArg,
            SqlTypeName returnType,
            String name) {
        return AggregateCall.create(
                function,
                distinct,
                approximate,
                argList,
                filterArg,
                TYPE_FACTORY.createSqlType(returnType),
                name);
    }

    private RelNode applyRule(FlinkAggregateExpandDistinctAggregatesRule rule, RelNode rel) {
        final HepPlanner planner =
                new HepPlanner(new HepProgramBuilder().addRuleInstance(rule).build());
        planner.setRoot(rel);
        return planner.findBestExp();
    }

    private static String planText(RelNode rel) {
        return Util.toLinux(RelOptUtil.toString(rel));
    }

    private static List<LogicalAggregate> findAggregates(RelNode root) {
        return findNodes(root, LogicalAggregate.class);
    }

    private static <T extends RelNode> List<T> findNodes(RelNode root, Class<T> clazz) {
        final List<T> result = new ArrayList<>();
        final Deque<RelNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            final RelNode node = stack.pop();
            if (clazz.isInstance(node)) {
                result.add(clazz.cast(node));
            }
            node.getInputs().forEach(stack::push);
        }
        return result;
    }

    private static RexCall asCall(RexNode node) {
        assertThat(node).isInstanceOf(RexCall.class);
        return (RexCall) node;
    }

    private static void assertRowTypePreserved(RelNode rewritten, RelNode original) {
        assertThat(rewritten.getRowType()).isEqualTo(original.getRowType());
    }

    private static List<ImmutableBitSet> groupSets(ImmutableBitSet... groupSets) {
        final List<ImmutableBitSet> sortedGroupSets = new ArrayList<>(Arrays.asList(groupSets));
        sortedGroupSets.sort(ImmutableBitSet.ORDERING);
        return sortedGroupSets;
    }

}

