/**
 * Tests for {@link FlinkAggregateJoinTransposeRule}.
 *
 * <p>The tests build Calcite logical plans directly and apply the rule through a {@link
 * HepPlanner}, so that the observable rewrite can be asserted without depending on the complete
 * Flink planner pipeline.
 */
class FlinkAggregateJoinTransposeRuleTests {

    private static final String EMP = "EMP";
    private static final String DEPT = "DEPT";

    private RelDataTypeFactory typeFactory;
    private RelOptCluster cluster;
    private CalciteCatalogReader catalogReader;

    @BeforeEach
    void setUp() {
        typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        final CalciteSchema rootSchema = CalciteSchema.createRootSchema(false, false);
        rootSchema.add(EMP, new TestTable("EMPNO", "DEPTNO", "SAL", "ACTIVE"));
        rootSchema.add(DEPT, new TestTable("DEPTNO", "DNAME"));

        catalogReader =
                new CalciteCatalogReader(
                        rootSchema,
                        Collections.emptyList(),
                        typeFactory,
                        CalciteConnectionConfig.DEFAULT);
        cluster = RelOptCluster.create(new VolcanoPlanner(), new RexBuilder(typeFactory));
    }

    // -------------------------------------------------------------------------
    // Push-down behavior of EXTENDED
    // -------------------------------------------------------------------------

    @Test
    void testExtendedPushesCountStarToBothJoinInputs() {
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Project project = assertInstanceOf(Project.class, output);
        assertEquals(input.getRowType().getFieldCount(), output.getRowType().getFieldCount());
        assertEquals(2, project.getProjects().size());

        final Join join = requireJoin(output);
        final Aggregate left = assertInstanceOf(Aggregate.class, join.getLeft());
        final Aggregate right = assertInstanceOf(Aggregate.class, join.getRight());
        assertTrue(hasAggCall(left, "COUNT"));
        assertTrue(hasAggCall(right, "COUNT"));

        // The results of the two partial counts are multiplied to compensate for the join.
        final RexCall product = assertInstanceOf(RexCall.class, project.getProjects().get(1));
        assertEquals(SqlKind.TIMES, product.getKind());
    }

    @Test
    void testExtendedPushesSumDownToTheSideOwningTheArgument() {
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(
                                aggregateCall(SqlStdOperatorTable.SUM, "S", 2)));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Project project = assertInstanceOf(Project.class, output);
        assertEquals(input.getRowType().getFieldCount(), output.getRowType().getFieldCount());
        final Join join = requireJoin(output);
        final Aggregate left = assertInstanceOf(Aggregate.class, join.getLeft());
        final Aggregate right = assertInstanceOf(Aggregate.class, join.getRight());

        assertEquals(1, left.getAggCallList().size());
        final AggregateCall pushedSum = left.getAggCallList().get(0);
        assertEquals("SUM", pushedSum.getAggregation().getName());
        assertEquals(Collections.singletonList(2), pushedSum.getArgList());

        // SUM cannot be pushed to the right side, but a partial COUNT is added there.
        assertTrue(hasAggCall(right, "COUNT"));

        // The partial SUM is multiplied by the row count of the other side.
        final RexCall cast = assertInstanceOf(RexCall.class, project.getProjects().get(1));
        assertEquals(SqlKind.CAST, cast.getKind());
        final RexCall product = assertInstanceOf(RexCall.class, cast.getOperands().get(0));
        assertEquals(SqlKind.TIMES, product.getKind());
    }

    @Test
    void testExtendedPushesFunctionlessAggregate() {
        final Aggregate input =
                aggregate(innerJoin(), ImmutableBitSet.of(1), Collections.emptyList());

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        assertInstanceOf(Project.class, output);
        final Join join = requireJoin(output);
        assertTrue(assertInstanceOf(Aggregate.class, join.getLeft()).getAggCallList().isEmpty());
        assertTrue(assertInstanceOf(Aggregate.class, join.getRight()).getAggCallList().isEmpty());
    }

    @Test
    void testExtendedKeepsAggregateWhenJoinKeysAreNotInAggregateOutput() {
        // Grouping by EMPNO means that the join key (DEPTNO) is not part of the group key, so
        // the aggregate cannot be turned into a projection on top of the join.
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(0),
                        Collections.singletonList(aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate top = assertInstanceOf(Aggregate.class, output);
        assertInstanceOf(Project.class, top.getInput(0));

        final Join join = requireJoin(output);
        assertInstanceOf(Aggregate.class, join.getLeft());
        assertInstanceOf(Aggregate.class, join.getRight());
        assertEquals(1, top.getAggCallList().size());
    }

    @Test
    void testExtendedSupportsAuxiliaryGroupAggregates() {
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Arrays.asList(
                                auxiliaryGroupCall(2, "SAL"),
                                aggregateCall(SqlStdOperatorTable.SUM, "S", 2)));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Project project = assertInstanceOf(Project.class, output);
        assertEquals(input.getRowType().getFieldNames(), project.getRowType().getFieldNames());

        // The auxiliary group call is removed and becomes part of the new grouping key.
        assertFalse(containsAggregation(output, FlinkSqlOperatorTable.AUXILIARY_GROUP));
        final Join join = requireJoin(output);
        final Aggregate left = assertInstanceOf(Aggregate.class, join.getLeft());
        assertEquals(2, left.getGroupSet().cardinality());
    }

    @Test
    void testExtendedSupportsAuxiliaryGroupColumnReordering() {
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(2),
                        Arrays.asList(
                                auxiliaryGroupCall(1, "DEPTNO"),
                                aggregateCall(SqlStdOperatorTable.SUM, "S", 2)));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        // The projection after the top aggregate restores the original column order.
        assertEquals(Arrays.asList("SAL", "DEPTNO", "S"), output.getRowType().getFieldNames());
    }

    @Test
    void testExtendedAppliesWhenTemporalTableIsOnTheLeftSide() {
        final RelNode leftSnapshot = snapshot(scan(EMP));
        final Aggregate input =
                aggregate(
                        joinWithLeftInput(leftSnapshot),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Join join = requireJoin(output);
        assertInstanceOf(Aggregate.class, join.getLeft());
        assertInstanceOf(Aggregate.class, join.getRight());
    }

    @Test
    void testConstructorWithFunctionsEnabledPushesAggregates() {
        final RelOptRule rule =
                new FlinkAggregateJoinTransposeRule(
                        LogicalAggregate.class,
                        LogicalJoin.class,
                        RelFactories.LOGICAL_BUILDER,
                        true);
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, rule);

        final Join join = requireJoin(output);
        assertInstanceOf(Aggregate.class, join.getLeft());
        assertInstanceOf(Aggregate.class, join.getRight());
    }

    // -------------------------------------------------------------------------
    // Bail-out behavior
    // -------------------------------------------------------------------------

    @Test
    void testConstructorWithFunctionsDisabledDoesNotPushFunctions() {
        final RelOptRule rule =
                new FlinkAggregateJoinTransposeRule(
                        LogicalAggregate.class,
                        LogicalJoin.class,
                        RelFactories.LOGICAL_BUILDER,
                        false);
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(
                                aggregateCall(SqlStdOperatorTable.SUM, "S", 2)));

        final RelNode output = applyRule(input, rule);

        assertAggregateStaysAboveJoin(output, "functions are not allowed");
    }

    @Test
    void testInstanceDoesNotPushFunctions() {
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(
                                aggregateCall(SqlStdOperatorTable.SUM, "S", 2)));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.INSTANCE);

        assertAggregateStaysAboveJoin(output, "INSTANCE does not allow functions");
    }

    @Test
    void testInstanceDoesNotPushFunctionlessAggregate() {
        // Without functions the rule assumes both join inputs are already unique and bails
        // out; this is the guard that prevents an endless rewrite loop.
        final Aggregate input =
                aggregate(innerJoin(), ImmutableBitSet.of(1), Collections.emptyList());

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.INSTANCE);

        assertAggregateStaysAboveJoin(output, "both inputs are treated as unique");
    }

    @Test
    void testDoesNotPushThroughOuterJoins() {
        for (JoinRelType joinType :
                new JoinRelType[] {JoinRelType.LEFT, JoinRelType.RIGHT, JoinRelType.FULL}) {
            final Aggregate input =
                    aggregate(
                            join(joinType),
                            ImmutableBitSet.of(1),
                            Collections.singletonList(
                                    aggregateCall(SqlStdOperatorTable.COUNT, "C")));

            final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

            final Aggregate aggregate =
                    assertAggregateStaysAboveJoin(output, "joinType=" + joinType);
            assertEquals(joinType, ((Join) aggregate.getInput(0)).getJoinType());
        }
    }

    @Test
    void testDoesNotPushDistinctAggregate() {
        final AggregateCall distinctCount =
                AggregateCall.create(
                        SqlStdOperatorTable.COUNT,
                        true,
                        false,
                        false,
                        Collections.emptyList(),
                        Collections.singletonList(2),
                        -1,
                        null,
                        RelCollations.EMPTY,
                        intType(),
                        "CD");
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(distinctCount));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate aggregate = assertAggregateStaysAboveJoin(output, "DISTINCT aggregate");
        assertTrue(aggregate.getAggCallList().get(0).isDistinct());
    }

    @Test
    void testDoesNotPushAggregateWithFilter() {
        final AggregateCall filteredCount =
                AggregateCall.create(
                        SqlStdOperatorTable.COUNT,
                        false,
                        false,
                        false,
                        Collections.emptyList(),
                        Collections.emptyList(),
                        3,
                        null,
                        RelCollations.EMPTY,
                        intType(),
                        "CF");
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(filteredCount));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate aggregate = assertAggregateStaysAboveJoin(output, "FILTER aggregate");
        assertTrue(aggregate.getAggCallList().get(0).filterArg >= 0);
    }

    @Test
    void testDoesNotPushUnsupportedAggregateFunction() {
        final Aggregate input =
                aggregate(
                        innerJoin(),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(
                                aggregateCall(SqlStdOperatorTable.AVG, "A", 2)));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate aggregate = assertAggregateStaysAboveJoin(output, "AVG cannot be split");
        assertEquals("AVG", aggregate.getAggCallList().get(0).getAggregation().getName());
    }

    @Test
    void testDoesNotPushAcrossNonEquiJoin() {
        final RelBuilder builder = relBuilder();
        final RelNode nonEquiJoin =
                builder.scan(EMP)
                        .scan(DEPT)
                        .join(
                                JoinRelType.INNER,
                                builder.lessThan(
                                        builder.field(2, 0, "DEPTNO"),
                                        builder.field(2, 1, "DEPTNO")))
                        .build();
        final Aggregate input =
                aggregate(
                        nonEquiJoin,
                        ImmutableBitSet.of(0),
                        Collections.singletonList(aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate aggregate =
                assertAggregateStaysAboveJoin(output, "non-equi join condition");
        final RexCall condition =
                assertInstanceOf(RexCall.class, ((Join) aggregate.getInput(0)).getCondition());
        assertEquals(SqlKind.LESS_THAN, condition.getKind());
    }

    @Test
    void testDoesNotPushThroughTemporalTableOnRightSide() {
        final Aggregate input =
                aggregate(
                        joinWithRightInput(snapshot(scan(DEPT))),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate aggregate =
                assertAggregateStaysAboveJoin(output, "temporal table on the right");
        final Join join = (Join) aggregate.getInput(0);
        assertInstanceOf(LogicalSnapshot.class, join.getRight());
    }

    @Test
    void testDoesNotPushThroughNestedTemporalTableOnRightSide() {
        final RelNode filterOverSnapshot =
                LogicalFilter.create(
                        snapshot(scan(DEPT)), cluster.getRexBuilder().makeLiteral(true));
        final Aggregate input =
                aggregate(
                        joinWithRightInput(filterOverSnapshot),
                        ImmutableBitSet.of(1),
                        Collections.singletonList(aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate aggregate =
                assertAggregateStaysAboveJoin(output, "nested temporal table on the right");
        final Join join = (Join) aggregate.getInput(0);
        assertInstanceOf(LogicalFilter.class, join.getRight());
        assertInstanceOf(LogicalSnapshot.class, join.getRight().getInput(0));
    }

    @Test
    void testDoesNotPushAggregateWithGroupingSets() {
        final Aggregate input =
                LogicalAggregate.create(
                        innerJoin(),
                        Collections.emptyList(),
                        ImmutableBitSet.of(1),
                        Arrays.asList(ImmutableBitSet.of(1), ImmutableBitSet.of()),
                        Collections.singletonList(
                                aggregateCall(SqlStdOperatorTable.COUNT, "C")));

        final RelNode output = applyRule(input, FlinkAggregateJoinTransposeRule.EXTENDED);

        final Aggregate aggregate =
                assertAggregateStaysAboveJoin(output, "grouping sets aggregate");
        assertNotEquals(Aggregate.Group.SIMPLE, aggregate.getGroupType());
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private RelBuilder relBuilder() {
        return RelBuilder.proto(Contexts.empty()).create(cluster, catalogReader);
    }

    private RelNode scan(String tableName) {
        return relBuilder().scan(tableName).build();
    }

    private RelNode innerJoin() {
        return join(JoinRelType.INNER);
    }

    private RelNode join(JoinRelType joinType) {
        final RelBuilder builder = relBuilder();
        return builder.scan(EMP)
                .scan(DEPT)
                .join(
                        joinType,
                        builder.equals(
                                builder.field(2, 0, "DEPTNO"),
                                builder.field(2, 1, "DEPTNO")))
                .build();
    }

    private RelNode joinWithLeftInput(RelNode leftInput) {
        final RelBuilder builder = relBuilder();
        return builder.push(leftInput)
                .scan(DEPT)
                .join(
                        JoinRelType.INNER,
                        builder.equals(
                                builder.field(2, 0, "DEPTNO"),
                                builder.field(2, 1, "DEPTNO")))
                .build();
    }

    private RelNode joinWithRightInput(RelNode rightInput) {
        final RelBuilder builder = relBuilder();
        return builder.scan(EMP)
                .push(rightInput)
                .join(
                        JoinRelType.INNER,
                        builder.equals(
                                builder.field(2, 0, "DEPTNO"),
                                builder.field(2, 1, "DEPTNO")))
                .build();
    }

    private RelNode snapshot(RelNode input) {
        return LogicalSnapshot.create(input, cluster.getRexBuilder().makeLiteral(true));
    }

    private Aggregate aggregate(
            RelNode input, ImmutableBitSet groupSet, List<AggregateCall> aggCalls) {
        return LogicalAggregate.create(
                input,
                Collections.emptyList(),
                groupSet,
                Collections.singletonList(groupSet),
                aggCalls);
    }

    private RelDataType intType() {
        return typeFactory.createSqlType(SqlTypeName.INTEGER);
    }

    private AggregateCall aggregateCall(SqlAggFunction function, String name, int... args) {
        return AggregateCall.create(
                function,
                false,
                false,
                false,
                Collections.emptyList(),
                toIntegerList(args),
                -1,
                null,
                RelCollations.EMPTY,
                intType(),
                name);
    }

    private AggregateCall auxiliaryGroupCall(int column, String name) {
        return AggregateCall.create(
                FlinkSqlOperatorTable.AUXILIARY_GROUP,
                false,
                false,
                false,
                Collections.emptyList(),
                Collections.singletonList(column),
                -1,
                null,
                RelCollations.EMPTY,
                intType(),
                name);
    }

    private static List<Integer> toIntegerList(int... values) {
        final List<Integer> list = new ArrayList<>(values.length);
        for (int value : values) {
            list.add(value);
        }
        return list;
    }

    private static RelNode applyRule(RelNode input, RelOptRule rule) {
        final HepProgram program = new HepProgramBuilder().addRuleInstance(rule).build();
        final HepPlanner planner = new HepPlanner(program);
        planner.setRoot(input);
        return planner.findBestExp();
    }

    private static Aggregate assertAggregateStaysAboveJoin(RelNode output, String message) {
        final Aggregate aggregate = assertInstanceOf(Aggregate.class, output, message);
        assertInstanceOf(Join.class, aggregate.getInput(0), message);
        return aggregate;
    }

    private static Join requireJoin(RelNode rel) {
        final Join join = findJoin(rel);
        assertNotNull(join, "expected a join in the plan");
        return join;
    }

    private static Join findJoin(RelNode rel) {
        if (rel instanceof Join) {
            return (Join) rel;
        }
        for (RelNode input : rel.getInputs()) {
            final Join join = findJoin(input);
            if (join != null) {
                return join;
            }
        }
        return null;
    }

    private static boolean hasAggCall(Aggregate aggregate, String functionName) {
        for (AggregateCall call : aggregate.getAggCallList()) {
            if (functionName.equals(call.getAggregation().getName())) {
                return true;
            }
        }
        return false;
    }

    private static boolean containsAggregation(RelNode rel, SqlAggFunction function) {
        if (rel instanceof Aggregate) {
            for (AggregateCall call : ((Aggregate) rel).getAggCallList()) {
                if (call.getAggregation() == function) {
                    return true;
                }
            }
        }
        for (RelNode input : rel.getInputs()) {
            if (containsAggregation(input, function)) {
                return true;
            }
        }
        return false;
    }

    /** Table with the given column names; {@code ACTIVE} is BOOLEAN, everything else INTEGER. */
    private static final class TestTable extends AbstractTable {
        private final String[] columns;

        private TestTable(String... columns) {
            this.columns = columns;
        }

        @Override
        public RelDataType getRowType(RelDataTypeFactory typeFactory) {
            final RelDataTypeFactory.Builder builder = typeFactory.builder();
            for (String column : columns) {
                final SqlTypeName typeName =
                        "ACTIVE".equals(column) ? SqlTypeName.BOOLEAN : SqlTypeName.INTEGER;
                builder.add(column, typeFactory.createSqlType(typeName));
            }
            return builder.build();
        }
    }
}

