import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link SubQueryDecorrelator}.
 *
 * <p>The tests construct logical relational trees directly so that the public entry point {@link
 * SubQueryDecorrelator#decorrelateQuery(RelNode)} can be exercised with precisely controlled
 * correlated subqueries.
 */
class SubQueryDecorrelatorTests {

    private RelOptCluster cluster;
    private RexBuilder rexBuilder;
    private FlinkTypeFactory typeFactory;

    @BeforeEach
    void setUp() {
        typeFactory = new FlinkTypeFactory(getClass().getClassLoader(), FlinkTypeSystem.INSTANCE);
        final ClassLoader classLoader = getClass().getClassLoader();
        final Configuration configuration = new Configuration();
        final CatalogStoreFactory catalogStoreFactory = new GenericInMemoryCatalogStoreFactory();
        final CatalogStore catalogStore = catalogStoreFactory.createCatalogStore();
        final CatalogStoreHolder catalogStoreHolder =
                CatalogStoreHolder.newBuilder()
                        .catalogStore(catalogStore)
                        .factory(catalogStoreFactory)
                        .config(configuration)
                        .classloader(classLoader)
                        .build();
        final CatalogManager catalogManager =
                CatalogManager.newBuilder()
                        .classLoader(classLoader)
                        .config(configuration)
                        .defaultCatalog(
                                "default_catalog",
                                new GenericInMemoryCatalog("default_catalog", "default_database"))
                        .catalogStoreHolder(catalogStoreHolder)
                        .build();
        FlinkContext context =
                new FlinkContextImpl(
                        true,
                        TableConfig.getDefault(),
                        null,
                        null,
                        catalogManager,
                        null,
                        classLoader);
        RelOptPlanner planner = new VolcanoPlanner(context);
        cluster = FlinkRelOptClusterFactory.create(planner, new FlinkRexBuilder(typeFactory));
        rexBuilder = cluster.getRexBuilder();
    }

    @Test
    void testRootWithoutSubqueryProducesEmptyResult() {
        RelNode values = values(rowType("a"), 1);
        RelNode filter =
                LogicalFilter.create(
                        values,
                        rexBuilder.makeCall(
                                SqlStdOperatorTable.IS_NOT_NULL,
                                rexBuilder.makeInputRef(values, 0)));

        Result result = SubQueryDecorrelator.decorrelateQuery(filter);

        assertNotNull(result);
        // There is no subquery in the tree, so no mapping can be retrieved.
        assertNull(result.getSubQueryEquivalent(RexSubQuery.exists(values)));
    }

    @Test
    void testNonCorrelatedSubqueryProducesEmptyResult() {
        RelNode outerValues = values(rowType("a"), 1);
        RelNode innerValues = values(rowType("b"), 2);
        RexSubQuery subQuery = RexSubQuery.exists(innerValues);
        RelNode outerFilter = LogicalFilter.create(outerValues, subQuery);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        assertNull(result.getSubQueryEquivalent(subQuery));
    }

    @Test
    void testSimpleCorrelatedExistsIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.left);
        assertNotNull(equivalent.right);

        // The correlation condition is pulled out and refers to the outer field as well as the
        // subquery field, both addressed as top-level input references.
        ImmutableBitSet conditionInputs =
                org.apache.calcite.plan.RelOptUtil.InputFinder.bits(equivalent.right);
        assertTrue(conditionInputs.get(0));
        assertTrue(conditionInputs.get(1));
        assertEquals(2, conditionInputs.cardinality());

        // The rewritten subquery has a single output column and no longer has correlation
        // variables embedded in it.
        assertEquals(1, equivalent.left.getRowType().getFieldCount());
        assertFalse(equivalent.right.toString().contains("$cor"));
    }

    @Test
    void testCorrelatedScalarSubqueryIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery = RexSubQuery.scalar(innerFilter);
        RexNode outerField = rexBuilder.makeInputRef(outerType, 0);
        RexNode condition = rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, outerField, subQuery);
        RelNode outerFilter = outerFilter(values(outerType, 1), condition, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.left);
        assertNotNull(equivalent.right);
        assertEquals(1, equivalent.left.getRowType().getFieldCount());
    }

    @Test
    void testNonEquiCorrelationIsSupported() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RexNode innerFilterCondition =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.GREATER_THAN,
                        correlatedField(outerType, correlationId, 0),
                        rexBuilder.makeInputRef(innerValues, 0));
        RelNode innerFilter = LogicalFilter.create(innerValues, innerFilterCondition);
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.left);
        assertNotNull(equivalent.right);
        assertTrue(equivalent.right.toString().contains(">"));
        assertEquals(
                ImmutableBitSet.of(0, 1),
                org.apache.calcite.plan.RelOptUtil.InputFinder.bits(equivalent.right));
    }

    @Test
    void testInSubqueryAddsProjectionToAlignOutputFields() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery =
                RexSubQuery.in(
                        innerFilter,
                        com.google.common.collect.ImmutableList.of(
                                rexBuilder.makeInputRef(outerType, 0)));
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        // IN requires an explicit projection around the subquery to keep the output order stable.
        Project project = assertInstanceOf(Project.class, equivalent.left);
        assertEquals(1, project.getRowType().getFieldCount());
        assertEquals("b", project.getRowType().getFieldNames().get(0));
    }

    @Test
    void testExistsSubqueryProjectsOnlyCorrelatedFields() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b0", "b1"), 7, 8);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        // Only the column participating in the correlation condition is kept.
        Project project = assertInstanceOf(Project.class, equivalent.left);
        assertEquals(1, project.getRowType().getFieldCount());
        assertEquals("b0", project.getRowType().getFieldNames().get(0));
    }

    @Test
    void testNonCorrelatedPartOfSubqueryFilterIsKept() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RexNode correlationPredicate =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.EQUALS,
                        correlatedField(outerType, correlationId, 0),
                        rexBuilder.makeInputRef(innerValues, 0));
        RexNode localPredicate =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.GREATER_THAN,
                        rexBuilder.makeInputRef(innerValues, 0),
                        rexBuilder.makeExactLiteral(
                                BigDecimal.ONE, typeFactory.createSqlType(SqlTypeName.INTEGER)));
        RelNode innerFilter =
                LogicalFilter.create(
                        innerValues,
                        rexBuilder.makeCall(
                                SqlStdOperatorTable.AND, correlationPredicate, localPredicate));
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);

        // The local predicate stays inside the rewritten subquery ...
        Filter rewrittenFilter = assertInstanceOf(Filter.class, equivalent.left);
        ImmutableBitSet localInputs =
                org.apache.calcite.plan.RelOptUtil.InputFinder.bits(rewrittenFilter.getCondition());
        assertEquals(ImmutableBitSet.of(0), localInputs);
        assertTrue(rewrittenFilter.getCondition().toString().contains(">"));

        // ... while the correlation predicate is extracted as a join condition.
        ImmutableBitSet correlationInputs =
                org.apache.calcite.plan.RelOptUtil.InputFinder.bits(equivalent.right);
        assertEquals(ImmutableBitSet.of(0, 1), correlationInputs);
    }

    @Test
    void testCorrelatedJoinInputIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode leftValues = values(rowType("l"), 1);
        RelNode rightValues = values(rowType("r"), 2);
        RelNode correlatedRight = correlatedFilter(outerType, correlationId, rightValues, 0, 0);
        RelNode join =
                LogicalJoin.create(
                        leftValues,
                        correlatedRight,
                        com.google.common.collect.ImmutableList.of(),
                        rexBuilder.makeLiteral(true),
                        com.google.common.collect.ImmutableSet.of(),
                        JoinRelType.INNER);
        RexSubQuery subQuery = RexSubQuery.exists(join);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        Project project = assertInstanceOf(Project.class, equivalent.left);
        assertInstanceOf(LogicalJoin.class, project.getInput());
        // The projection keeps only the correlated right-hand side field.
        assertEquals(1, project.getRowType().getFieldCount());
    }

    @Test
    void testInSubqueryWithExistingProjectSkipsAdditionalProjection() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RelNode innerProject =
                LogicalProject.create(
                        innerFilter,
                        com.google.common.collect.ImmutableList.of(),
                        com.google.common.collect.ImmutableList.of(
