        RexSubQuery subQuery =
                RexSubQuery.in(
                        innerProject,
                        com.google.common.collect.ImmutableList.of(
                                rexBuilder.makeInputRef(outerType, 0)));
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.right);
        Project project = assertInstanceOf(Project.class, equivalent.left);
        assertEquals(1, project.getRowType().getFieldCount());
        assertEquals("b", project.getRowType().getFieldNames().get(0));
    }

    @Test
    void testMultipleSubqueriesInOnePredicateAreBothDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId firstId = cluster.createCorrel();
        CorrelationId secondId = cluster.createCorrel();
        RelNode firstInner = values(rowType("b"), 7);
        RelNode firstFilter = correlatedFilter(outerType, firstId, firstInner, 0, 0);
        RelNode secondInner = values(rowType("c"), 8);
        RelNode secondFilter = correlatedFilter(outerType, secondId, secondInner, 0, 0);
        RexSubQuery firstSubQuery = RexSubQuery.exists(firstFilter);
        RexSubQuery secondSubQuery = RexSubQuery.exists(secondFilter);
        RexNode condition =
                rexBuilder.makeCall(SqlStdOperatorTable.AND, firstSubQuery, secondSubQuery);
        RelNode outerFilter =
                LogicalFilter.create(
                        values(outerType, 1),
                        condition,
                        com.google.common.collect.ImmutableSet.of(firstId, secondId));

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> firstEquivalent = result.getSubQueryEquivalent(firstSubQuery);
        Pair<RelNode, RexNode> secondEquivalent = result.getSubQueryEquivalent(secondSubQuery);
        assertNotNull(firstEquivalent);
        assertNotNull(firstEquivalent.right);
        assertNotNull(secondEquivalent);
        assertNotNull(secondEquivalent.right);
    }

    @Test
    void testNestedSubqueryOperandReferencingOuterVariableIsUnsupported() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode nestedValues = values(rowType("c"), 9);
        RexSubQuery nested =
                RexSubQuery.in(
                        nestedValues,
                        com.google.common.collect.ImmutableList.of(
                                correlatedField(outerType, correlationId, 0)));
