    @Test
    void testAggregateInSubqueryIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        AggregateCall count =
                AggregateCall.create(
                        SqlStdOperatorTable.COUNT,
                        false,
                        com.google.common.collect.ImmutableList.of(),
                        -1,
                        typeFactory.createSqlType(SqlTypeName.BIGINT),
                        "cnt");
        RelNode aggregate =
                LogicalAggregate.create(
                        innerFilter,
                        ImmutableBitSet.of(),
                        com.google.common.collect.ImmutableList.of(ImmutableBitSet.of()),
                        com.google.common.collect.ImmutableList.of(count));
        RexSubQuery subQuery = RexSubQuery.exists(aggregate);
