    @Test
    void testUnrelatedSubqueryLookupReturnsNull() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery correlated = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), correlated, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);
        assertNotNull(result);
        assertNotNull(result.getSubQueryEquivalent(correlated));

        RexSubQuery unrelated = RexSubQuery.exists(values(rowType("x"), 1));
        assertNull(result.getSubQueryEquivalent(unrelated));
