    @Test
    void testSimpleCorrelatedExistsIsDecorrelated() {
        RelDataType outerType = rowType("a");
        CorrelationId correlationId = cluster.createCorrel();
        RelNode innerValues = values(rowType("b"), 7);
        RelNode innerFilter = correlatedFilter(outerType, correlationId, innerValues, 0, 0);
        RexSubQuery subQuery = RexSubQuery.exists(innerFilter);
        RelNode outerFilter = outerFilter(values(outerType, 1), subQuery, correlationId);

        Result result = SubQueryDecorrelator.decorrelateQuery(outerFilter);

        assertNotNull(result);
        Pair<RelNode, RexNode> equivalent = result.getSubQueryEquivalent(subQuery);
        assertNotNull(equivalent);
        assertNotNull(equivalent.left);
        assertNotNull(equivalent.right);

        // The correlation condition is pulled out and refers to the outer field as well as the
        // subquery field, both addressed as top-level input references.
        ImmutableBitSet conditionInputs =
                org.apache.calcite.plan.RelOptUtil.InputFinder.bits(equivalent.right);
        assertTrue(conditionInputs.get(0));
        assertTrue(conditionInputs.get(1));
        assertEquals(2, conditionInputs.cardinality());

        // The rewritten subquery has a single output column and no longer has correlation
        // variables embedded in it.
        assertEquals(1, equivalent.left.getRowType().getFieldCount());
        assertFalse(equivalent.right.toString().contains("$cor"));
    }

