    // ------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------

    private RelDataType rowType(String... names) {
        RelDataTypeFactory.Builder builder = typeFactory.builder();
        for (String name : names) {
            builder.add(name, typeFactory.createSqlType(SqlTypeName.INTEGER));
        }
        return builder.build();
    }

    private RelNode values(RelDataType rowType, int... values) {
        List<RexLiteral> row = new ArrayList<>();
        for (int value : values) {
            row.add(
                    rexBuilder.makeExactLiteral(
                            BigDecimal.valueOf(value),
                            typeFactory.createSqlType(SqlTypeName.INTEGER)));
        }
        return LogicalValues.create(
                cluster,
                rowType,
                com.google.common.collect.ImmutableList.of(
                        com.google.common.collect.ImmutableList.copyOf(row)));
    }

    private RexNode correlatedField(
            RelDataType outerRowType, CorrelationId correlationId, int fieldIndex) {
        return rexBuilder.makeFieldAccess(
                rexBuilder.makeCorrel(outerRowType, correlationId), fieldIndex);
    }

    private RelNode correlatedFilter(
            RelDataType outerRowType,
            CorrelationId correlationId,
            RelNode input,
            int outerFieldIndex,
            int innerFieldIndex) {
        RexNode condition =
                rexBuilder.makeCall(
                        SqlStdOperatorTable.EQUALS,
                        correlatedField(outerRowType, correlationId, outerFieldIndex),
                        rexBuilder.makeInputRef(input, innerFieldIndex));
        return LogicalFilter.create(input, condition);
    }

    private RelNode outerFilter(
            RelNode outerInput, RexNode condition, CorrelationId correlationId) {
        return LogicalFilter.create(
                outerInput, condition, com.google.common.collect.ImmutableSet.of(correlationId));
    }
}

