    @Test
    void testLookupNormalizesNullabilityAndReturnsSameConverter() {
        DataType notNullInt = DataTypes.INT().bridgedTo(Integer.class).notNull();
        assertSame(IntConverter.INSTANCE, DataFormatConverters.getConverterForDataType(notNullInt));
        assertSame(
                StringConverter.INSTANCE,
                DataFormatConverters.getConverterForDataType(DataTypes.STRING().notNull()));
    }

    @Test
    void testLookupRejectsUnsupportedConversionClasses() {
        assertThrows(
                RuntimeException.class,
                () -> DataFormatConverters.getConverterForDataType(DataTypes.NULL()));
        assertThrows(
                RuntimeException.class,
                () ->
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.STRING().bridgedTo(Integer.class)));
        assertThrows(
                RuntimeException.class,
                () ->
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.DECIMAL(5, 2).bridgedTo(Integer.class)));
        assertThrows(
                RuntimeException.class,
                () ->
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.TIMESTAMP().bridgedTo(Integer.class)));
    }

    @Test
    void testNullHandlingInPublicConverterApi() {
        DataFormatConverter<Integer, Integer> converter = IntConverter.INSTANCE;
        assertNull(converter.toInternal(null));
        assertNull(converter.toExternal((Integer) null));

        GenericRowData row = GenericRowData.of((Object) null);
        assertNull(converter.toExternal(row, 0));
    }

    @Test
    void testPrimitiveConvertersRoundTripAndReadRows() {
        assertConverted(GenericRowData.of(true), BooleanConverter.INSTANCE, true);
        assertConverted(GenericRowData.of((byte) 7), ByteConverter.INSTANCE, (byte) 7);
        assertConverted(GenericRowData.of((short) 7), ShortConverter.INSTANCE, (short) 7);
        assertConverted(GenericRowData.of(7), IntConverter.INSTANCE, 7);
        assertConverted(GenericRowData.of(7L), LongConverter.INSTANCE, 7L);
        assertConverted(GenericRowData.of(7.25f), FloatConverter.INSTANCE, 7.25f);
        assertConverted(GenericRowData.of(7.25d), DoubleConverter.INSTANCE, 7.25d);
    }

    @Test
    void testStringAndIdentityConvertersRoundTrip() {
        StringConverter stringConverter = StringConverter.INSTANCE;
        StringData hello = StringData.fromString("hello");
        assertEquals(hello, stringConverter.toInternal("hello"));
        assertEquals("hello", stringConverter.toExternal(hello));
        assertEquals("hello", stringConverter.toExternal(GenericRowData.of(hello), 0));

        byte[] bytes = new byte[] {1, 2, 3};
        assertSame(bytes, PrimitiveByteArrayConverter.INSTANCE.toInternal(bytes));
        assertSame(bytes, PrimitiveByteArrayConverter.INSTANCE.toExternal(bytes));
        assertArrayEquals(
                bytes,
                PrimitiveByteArrayConverter.INSTANCE.toExternal(GenericRowData.of(bytes), 0));

        GenericArrayData array = new GenericArrayData(new int[] {1, 2});
        assertSame(array, ArrayDataConverter.INSTANCE.toInternal(array));
        assertSame(array, ArrayDataConverter.INSTANCE.toExternal(array));
        assertSame(array, ArrayDataConverter.INSTANCE.toExternal(GenericRowData.of(array), 0));

        GenericMapData map = new GenericMapData(Collections.singletonMap("k", 1));
        assertSame(map, MapDataConverter.INSTANCE.toInternal(map));
        assertSame(map, MapDataConverter.INSTANCE.toExternal(map));
        assertSame(map, MapDataConverter.INSTANCE.toExternal(GenericRowData.of(map), 0));

        RawValueData<Integer> raw = RawValueData.fromObject(123);
        assertSame(raw, RawValueDataConverter.INSTANCE.toInternal(raw));
        assertSame(raw, RawValueDataConverter.INSTANCE.toExternal(raw));
        assertSame(raw, RawValueDataConverter.INSTANCE.toExternal(GenericRowData.of(raw), 0));

        Bitmap bitmap = Bitmap.fromArray(new int[] {1, 2, 3});
        assertSame(bitmap, BitmapConverter.INSTANCE.toInternal(bitmap));
        assertSame(bitmap, BitmapConverter.INSTANCE.toExternal(bitmap));
        assertSame(bitmap, BitmapConverter.INSTANCE.toExternal(GenericRowData.of(bitmap), 0));

        Variant variant = Variant.newBuilder().of(42);
        assertSame(variant, VariantConverter.INSTANCE.toInternal(variant));
        assertSame(variant, VariantConverter.INSTANCE.toExternal(variant));
        assertSame(variant, VariantConverter.INSTANCE.toExternal(GenericRowData.of(variant), 0));
    }

    @Test
    void testDecimalConverters() {
        BigDecimal value = new BigDecimal("12345.678");
        BigDecimalConverter converter = new BigDecimalConverter(12, 3);
        DecimalData internal = converter.toInternal(value);
        assertEquals(0, value.compareTo(internal.toBigDecimal()));
        assertEquals(3, internal.toBigDecimal().scale());
        assertEquals(value, converter.toExternal(internal));
        assertEquals(value, converter.toExternal(GenericRowData.of(internal), 0));

        DecimalDataConverter identity = new DecimalDataConverter(12, 3);
        assertSame(internal, identity.toInternal(internal));
        assertSame(internal, identity.toExternal(internal));
        assertSame(internal, identity.toExternal(GenericRowData.of(internal), 0));
    }

    @Test
    void testDateAndTimeConverters() {
        LocalDate localDate = LocalDate.of(2024, 2, 29);
        LocalDateConverter localDateConverter = LocalDateConverter.INSTANCE;
        int dateInternal = localDateConverter.toInternal(localDate);
        assertEquals(DateTimeUtils.toInternal(localDate), dateInternal);
        assertEquals(localDate, localDateConverter.toExternal(dateInternal));
        assertEquals(localDate, localDateConverter.toExternal(GenericRowData.of(dateInternal), 0));

        Date date = Date.valueOf(localDate);
        DateConverter dateConverter = DateConverter.INSTANCE;
        assertEquals(DateTimeUtils.toInternal(date), dateConverter.toInternal(date));
        assertEquals(
                DateTimeUtils.toSQLDate(DateTimeUtils.toInternal(date)),
                dateConverter.toExternal(DateTimeUtils.toInternal(date)));

        LocalTime localTime = LocalTime.of(13, 14, 15, 123_000_000);
        LocalTimeConverter localTimeConverter = LocalTimeConverter.INSTANCE;
        int timeInternal = localTimeConverter.toInternal(localTime);
        assertEquals(localTime, localTimeConverter.toExternal(timeInternal));
        assertEquals(localTime, localTimeConverter.toExternal(GenericRowData.of(timeInternal), 0));

        Time time = Time.valueOf(localTime);
        TimeConverter timeConverter = TimeConverter.INSTANCE;
        assertEquals(DateTimeUtils.toInternal(time), timeConverter.toInternal(time));
        assertEquals(
                DateTimeUtils.toSQLTime(DateTimeUtils.toInternal(time)),
                timeConverter.toExternal(DateTimeUtils.toInternal(time)));
    }

    @Test
    void testTimestampAndInstantConverters() {
        LocalDateTime localDateTime = LocalDateTime.of(2024, 3, 4, 5, 6, 7, 123_456_789);
        LocalDateTimeConverter localDateTimeConverter = new LocalDateTimeConverter(9);
        TimestampData internal = localDateTimeConverter.toInternal(localDateTime);
        assertEquals(localDateTime, localDateTimeConverter.toExternal(internal));
        assertEquals(
                localDateTime, localDateTimeConverter.toExternal(GenericRowData.of(internal), 0));

        Instant instant = Instant.parse("2024-03-04T05:06:07.123456789Z");
        InstantConverter instantConverter = new InstantConverter(9);
        TimestampData instantInternal = instantConverter.toInternal(instant);
        assertEquals(instant, instantConverter.toExternal(instantInternal));
        assertEquals(instant, instantConverter.toExternal(GenericRowData.of(instantInternal), 0));

        Timestamp timestamp = Timestamp.from(instant);
        TimestampConverter timestampConverter = new TimestampConverter(9);
        TimestampData timestampInternal = timestampConverter.toInternal(timestamp);
        assertEquals(timestamp, timestampConverter.toExternal(timestampInternal));
        assertEquals(
                timestamp, timestampConverter.toExternal(GenericRowData.of(timestampInternal), 0));

        TimestampLtzConverter ltzConverter = new TimestampLtzConverter(9);
        TimestampData ltzInternal = ltzConverter.toInternal(timestamp);
        assertEquals(timestamp, ltzConverter.toExternal(ltzInternal));
        assertEquals(timestamp, ltzConverter.toExternal(GenericRowData.of(ltzInternal), 0));

        TimestampData epoch = TimestampData.fromEpochMillis(1_234_567L);
        LongTimestampDataConverter longConverter = new LongTimestampDataConverter(6);
        assertEquals(1_234_567L, longConverter.toExternal(longConverter.toInternal(1_234_567L)));
        assertEquals(1_234_567L, longConverter.toExternal(GenericRowData.of(epoch), 0));

        TimestampDataConverter dataConverter = new TimestampDataConverter(3);
        assertSame(epoch, dataConverter.toInternal(epoch));
        assertSame(epoch, dataConverter.toExternal(epoch));
        assertSame(epoch, dataConverter.toExternal(GenericRowData.of(epoch), 0));
    }

    @Test
