    @Test
    void testRowConverterPreservesValuesKindAndNulls() {
        RowConverter converter =
                new RowConverter(
                        new DataType[] {
                            DataTypes.INT().bridgedTo(Integer.class), DataTypes.STRING()
                        });
        Row row = Row.ofKind(RowKind.UPDATE_BEFORE, 42, null);
        RowData internal = converter.toInternal(row);
        assertEquals(RowKind.UPDATE_BEFORE, internal.getRowKind());
        assertEquals(42, internal.getInt(0));
        assertTrue(internal.isNullAt(1));

        Row result = converter.toExternal(internal);
        assertEquals(RowKind.UPDATE_BEFORE, result.getKind());
        assertEquals(42, result.getField(0));
        assertNull(result.getField(1));
        assertEquals(result, converter.toExternal(internal));
    }

    @Test
    void testRowDataConverterFromLookupReadsNestedRow() {
        DataFormatConverter<RowData, RowData> converter =
                DataFormatConverters.getConverterForDataType(
                        DataTypes.ROW(DataTypes.INT(), DataTypes.STRING())
                                .bridgedTo(RowData.class));
        GenericRowData nested = GenericRowData.of(1, StringData.fromString("nested"));
        GenericRowData outer = GenericRowData.of(nested);
        assertSame(nested, converter.toExternal(outer, 0));
        assertSame(nested, converter.toInternal(nested));
        assertSame(nested, converter.toExternal(nested));
        assertNull(converter.toExternal(GenericRowData.of((Object) null), 0));
    }

    @Test
    void testTupleConverter() {
        TupleConverter converter =
                new TupleConverter(
                        (Class<Tuple>) (Class<?>) Tuple2.class,
                        new DataType[] {
                            DataTypes.INT().bridgedTo(Integer.class), DataTypes.STRING()
                        });
        Tuple2<Integer, String> tuple = Tuple2.of(1, "one");
        RowData internal = converter.toInternal(tuple);
        assertEquals(1, internal.getInt(0));
        assertEquals("one", internal.getString(1).toString());

        Tuple2<?, ?> result = (Tuple2<?, ?>) converter.toExternal(internal);
        assertEquals(1, result.f0);
        assertEquals("one", result.f1);

        GenericRowData second = GenericRowData.of(2, StringData.fromString("two"));
        Tuple2<?, ?> secondResult = (Tuple2<?, ?>) converter.toExternal(second);
        assertEquals(2, secondResult.f0);
        assertEquals("two", secondResult.f1);
    }

    @Test
    void testPojoConverter() {
        @SuppressWarnings("unchecked")
        PojoTypeInfo<TestPojo> typeInfo =
                (PojoTypeInfo<TestPojo>) TypeExtractor.getForClass(TestPojo.class);
        PojoConverter<TestPojo> converter =
                new PojoConverter<>(
                        typeInfo,
                        new DataType[] {
                            DataTypes.INT().bridgedTo(Integer.class), DataTypes.STRING()
                        });
        TestPojo pojo = new TestPojo();
        pojo.id = 7;
        pojo.name = "seven";

        RowData internal = converter.toInternal(pojo);
        assertEquals(7, internal.getInt(0));
        assertEquals("seven", internal.getString(1).toString());

        TestPojo result = converter.toExternal(internal);
        assertEquals(7, result.id);
        assertEquals("seven", result.name);
    }

    @Test
    void testGenericConverterUsesProvidedSerializer() {
        GenericConverter<Integer> converter = new GenericConverter<>(IntSerializer.INSTANCE);
        RawValueData<Integer> internal = converter.toInternal(123);
        assertEquals(123, converter.toExternal(internal));
        assertEquals(123, converter.toExternal(GenericRowData.of(internal), 0));
        assertNull(converter.toInternal(null));
        assertNull(converter.toExternal((RawValueData<Integer>) null));
    }

    private static DataFormatConverter<?, ?> converter(DataType dataType) {
        return DataFormatConverters.getConverterForDataType(dataType);
    }

    private static <T> void assertConverted(
            GenericRowData row, DataFormatConverter<T, T> converter, T value) {
        assertSame(value, converter.toInternal(value));
        assertSame(value, converter.toExternal(value));
        assertEquals(value, converter.toExternal(row, 0));
    }

    /** Simple POJO used to verify reflective field access. */
    public static class TestPojo {
        public int id;
        public String name;

        public TestPojo() {}
    }
}

