        assertSame(ShortConverter.INSTANCE, converter(DataTypes.SMALLINT()));
        assertSame(IntConverter.INSTANCE, converter(DataTypes.INT()));
        assertSame(LongConverter.INSTANCE, converter(DataTypes.BIGINT()));
        assertSame(FloatConverter.INSTANCE, converter(DataTypes.FLOAT()));
        assertSame(DoubleConverter.INSTANCE, converter(DataTypes.DOUBLE()));

        assertSame(StringConverter.INSTANCE, converter(DataTypes.STRING()));
        assertSame(
                StringDataConverter.INSTANCE,
                converter(DataTypes.STRING().bridgedTo(StringData.class)));
        assertSame(PrimitiveByteArrayConverter.INSTANCE, converter(DataTypes.BYTES()));

        assertInstanceOf(BigDecimalConverter.class, converter(DataTypes.DECIMAL(12, 3)));
        assertInstanceOf(
                DecimalDataConverter.class,
                converter(DataTypes.DECIMAL(12, 3).bridgedTo(DecimalData.class)));

        assertSame(LocalDateConverter.INSTANCE, converter(DataTypes.DATE()));
        assertSame(DateConverter.INSTANCE, converter(DataTypes.DATE().bridgedTo(Date.class)));
        assertSame(LocalTimeConverter.INSTANCE, converter(DataTypes.TIME()));
        assertSame(TimeConverter.INSTANCE, converter(DataTypes.TIME().bridgedTo(Time.class)));
        assertInstanceOf(LocalDateTimeConverter.class, converter(DataTypes.TIMESTAMP(9)));
        assertInstanceOf(
                TimestampConverter.class,
                converter(DataTypes.TIMESTAMP(9).bridgedTo(Timestamp.class)));
        assertInstanceOf(
                TimestampDataConverter.class,
                converter(DataTypes.TIMESTAMP(9).bridgedTo(TimestampData.class)));
        assertInstanceOf(InstantConverter.class, converter(DataTypes.TIMESTAMP_LTZ(9)));
        assertInstanceOf(
                LongTimestampDataConverter.class,
                converter(DataTypes.TIMESTAMP_LTZ(9).bridgedTo(Long.class)));
        assertInstanceOf(
                TimestampLtzConverter.class,
                converter(DataTypes.TIMESTAMP_LTZ(9).bridgedTo(Timestamp.class)));

        assertSame(
                ArrayDataConverter.INSTANCE,
                converter(DataTypes.ARRAY(DataTypes.INT()).bridgedTo(ArrayData.class)));
        assertSame(
                PrimitiveBooleanArrayConverter.INSTANCE,
                converter(DataTypes.ARRAY(DataTypes.BOOLEAN()).bridgedTo(boolean[].class)));
        assertSame(
                PrimitiveShortArrayConverter.INSTANCE,
                converter(DataTypes.ARRAY(DataTypes.SMALLINT()).bridgedTo(short[].class)));
        assertSame(
                PrimitiveIntArrayConverter.INSTANCE,
                converter(DataTypes.ARRAY(DataTypes.INT()).bridgedTo(int[].class)));
        assertSame(
                PrimitiveLongArrayConverter.INSTANCE,
                converter(DataTypes.ARRAY(DataTypes.BIGINT()).bridgedTo(long[].class)));
        assertSame(
                PrimitiveFloatArrayConverter.INSTANCE,
                converter(DataTypes.ARRAY(DataTypes.FLOAT()).bridgedTo(float[].class)));
        assertSame(
                PrimitiveDoubleArrayConverter.INSTANCE,
                converter(DataTypes.ARRAY(DataTypes.DOUBLE()).bridgedTo(double[].class)));
        assertInstanceOf(ObjectArrayConverter.class, converter(DataTypes.ARRAY(DataTypes.INT())));

        assertSame(
                MapDataConverter.INSTANCE,
                converter(
                        DataTypes.MAP(DataTypes.STRING(), DataTypes.INT())
                                .bridgedTo(MapData.class)));
        assertInstanceOf(
                MapConverter.class, converter(DataTypes.MAP(DataTypes.STRING(), DataTypes.INT())));
        assertInstanceOf(MapConverter.class, converter(DataTypes.MULTISET(DataTypes.STRING())));

        assertInstanceOf(
                RowConverter.class, converter(DataTypes.ROW(DataTypes.INT(), DataTypes.STRING())));
        assertInstanceOf(
                RowDataConverter.class,
                converter(
                        DataTypes.ROW(DataTypes.INT(), DataTypes.STRING())
                                .bridgedTo(RowData.class)));
        assertSame(
                RawValueDataConverter.INSTANCE,
                converter(
                        DataTypes.RAW(Integer.class, IntSerializer.INSTANCE)
                                .bridgedTo(RawValueData.class)));
        assertInstanceOf(
                GenericConverter.class,
                converter(DataTypes.RAW(Integer.class, IntSerializer.INSTANCE)));

        assertSame(BitmapConverter.INSTANCE, converter(DataTypes.BITMAP()));
