    @Test
    void testLookupNormalizesNullabilityAndReturnsSameConverter() {
        DataType notNullInt = DataTypes.INT().bridgedTo(Integer.class).notNull();
        assertSame(IntConverter.INSTANCE, DataFormatConverters.getConverterForDataType(notNullInt));
        assertSame(
                StringConverter.INSTANCE,
                DataFormatConverters.getConverterForDataType(DataTypes.STRING().notNull()));
    }

    @Test
    void testLookupRejectsUnsupportedConversionClasses() {
        assertThrows(
                RuntimeException.class,
                () -> DataFormatConverters.getConverterForDataType(DataTypes.NULL()));
        assertThrows(
                RuntimeException.class,
                () ->
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.STRING().bridgedTo(Integer.class)));
        assertThrows(
                RuntimeException.class,
                () ->
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.DECIMAL(5, 2).bridgedTo(Integer.class)));
        assertThrows(
                RuntimeException.class,
                () ->
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.TIMESTAMP().bridgedTo(Integer.class)));
    }

    @Test
    void testNullHandlingInPublicConverterApi() {
        DataFormatConverter<Integer, Integer> converter = IntConverter.INSTANCE;
        assertNull(converter.toInternal(null));
        assertNull(converter.toExternal((Integer) null));

        GenericRowData row = GenericRowData.of((Object) null);
        assertNull(converter.toExternal(row, 0));
    }

    @Test
    void testPrimitiveConvertersRoundTripAndReadRows() {
        assertConverted(GenericRowData.of(true), BooleanConverter.INSTANCE, true);
        assertConverted(GenericRowData.of((byte) 7), ByteConverter.INSTANCE, (byte) 7);
        assertConverted(GenericRowData.of((short) 7), ShortConverter.INSTANCE, (short) 7);
        assertConverted(GenericRowData.of(7), IntConverter.INSTANCE, 7);
        assertConverted(GenericRowData.of(7L), LongConverter.INSTANCE, 7L);
        assertConverted(GenericRowData.of(7.25f), FloatConverter.INSTANCE, 7.25f);
        assertConverted(GenericRowData.of(7.25d), DoubleConverter.INSTANCE, 7.25d);
    }

    @Test
    void testStringAndIdentityConvertersRoundTrip() {
        StringConverter stringConverter = StringConverter.INSTANCE;
        StringData hello = StringData.fromString("hello");
        assertEquals(hello, stringConverter.toInternal("hello"));
        assertEquals("hello", stringConverter.toExternal(hello));
        assertEquals("hello", stringConverter.toExternal(GenericRowData.of(hello), 0));

        byte[] bytes = new byte[] {1, 2, 3};
