        GenericArrayData array = new GenericArrayData(new int[] {1, 2});
        assertSame(array, ArrayDataConverter.INSTANCE.toInternal(array));
        assertSame(array, ArrayDataConverter.INSTANCE.toExternal(array));
        assertSame(array, ArrayDataConverter.INSTANCE.toExternal(GenericRowData.of(array), 0));

        GenericMapData map = new GenericMapData(Collections.singletonMap("k", 1));
        assertSame(map, MapDataConverter.INSTANCE.toInternal(map));
        assertSame(map, MapDataConverter.INSTANCE.toExternal(map));
        assertSame(map, MapDataConverter.INSTANCE.toExternal(GenericRowData.of(map), 0));

        RawValueData<Integer> raw = RawValueData.fromObject(123);
        assertSame(raw, RawValueDataConverter.INSTANCE.toInternal(raw));
        assertSame(raw, RawValueDataConverter.INSTANCE.toExternal(raw));
        assertSame(raw, RawValueDataConverter.INSTANCE.toExternal(GenericRowData.of(raw), 0));

