    @Test
    void testObjectArrayConverterWithIdentityElementConverter() {
        ObjectArrayConverter<Integer> converter =
                new ObjectArrayConverter<>(DataTypes.INT().bridgedTo(Integer.class));
        Integer[] values = new Integer[] {1, null, 3};
        ArrayData internal = converter.toInternal(values);
        assertInstanceOf(GenericArrayData.class, internal);
        assertArrayEquals(values, converter.toExternal(internal));
        assertArrayEquals(values, converter.toExternal(GenericRowData.of(internal), 0));

        Integer[] primitiveArrayResult =
                converter.toExternal(new GenericArrayData(new int[] {4, 5}));
        assertArrayEquals(new Integer[] {4, 5}, primitiveArrayResult);
    }

    @Test
    void testObjectArrayConverterWithConvertingElementConverter() {
        ObjectArrayConverter<String> converter =
                new ObjectArrayConverter<>(DataTypes.STRING().bridgedTo(String.class));
        String[] values = new String[] {"first", null, "third"};
        ArrayData internal = converter.toInternal(values);
        assertTrue(!(internal instanceof GenericArrayData));
        assertArrayEquals(values, converter.toExternal(internal));
        assertArrayEquals(values, converter.toExternal(GenericRowData.of(internal), 0));

        assertEquals(3, converter.toExternal(internal).length);
        assertArrayEquals(
                new String[] {"a", "b"},
                converter.toExternal(converter.toInternal(new String[] {"a", "b"})));
        assertArrayEquals(
                new String[] {"c", "d"},
                converter.toExternal(converter.toInternal(new String[] {"c", "d"})));
    }

    @Test
    void testObjectArrayConverterReadsGenericArrayDataWithElementConversion() {
        ObjectArrayConverter<String> converter =
                new ObjectArrayConverter<>(DataTypes.STRING().bridgedTo(String.class));
        GenericArrayData generic =
                new GenericArrayData(
                        new Object[] {
                            StringData.fromString("one"), null, StringData.fromString("three")
                        });
