    @Test
    void testMapConverterWithIdentityKeyAndValueConverters() {
        MapConverter converter =
                new MapConverter(
                        DataTypes.INT().bridgedTo(Integer.class),
                        DataTypes.BIGINT().bridgedTo(Long.class));
        Map<Integer, Long> values = new LinkedHashMap<>();
        values.put(1, 10L);
        values.put(2, null);

        MapData internal = converter.toInternal(values);
        assertInstanceOf(GenericMapData.class, internal);
        assertEquals(values, converter.toExternal(internal));
