package org.apache.flink.table.runtime.operators.join.stream;

import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.streaming.runtime.streamrecord.StreamRecord;
import org.apache.flink.streaming.util.KeyedTwoInputStreamOperatorTestHarness;
import org.apache.flink.table.connector.ChangelogMode;
import org.apache.flink.table.data.GenericRowData;
import org.apache.flink.table.data.RowData;
import org.apache.flink.table.runtime.generated.GeneratedJoinCondition;
import org.apache.flink.table.runtime.operators.join.stream.utils.JoinInputSideSpec;
import org.apache.flink.table.runtime.typeutils.InternalTypeInfo;
import org.apache.flink.table.runtime.util.RuntimeChangelogMode;
import org.apache.flink.table.types.logical.BigIntType;
import org.apache.flink.types.RowKind;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link StreamingJoinOperator}. */
class StreamingJoinOperatorTests {

    private static final InternalTypeInfo<RowData> ONE_LONG_TYPE =
            InternalTypeInfo.ofFields(new BigIntType());

    private static final InternalTypeInfo<RowData> TWO_LONG_TYPE =
            InternalTypeInfo.ofFields(new BigIntType(), new BigIntType());

    private static final InternalTypeInfo<RowData> TWO_LONG_JOIN_TYPE =
            InternalTypeInfo.ofFields(
                    new BigIntType(), new BigIntType(), new BigIntType(), new BigIntType());

    private static final InternalTypeInfo<RowData> THREE_LONG_TYPE =
            InternalTypeInfo.ofFields(new BigIntType(), new BigIntType(), new BigIntType());

    private static final InternalTypeInfo<RowData> THREE_LONG_JOIN_TYPE =
            InternalTypeInfo.ofFields(
                    new BigIntType(),
                    new BigIntType(),
                    new BigIntType(),
                    new BigIntType(),
                    new BigIntType(),
                    new BigIntType());

    private static final GeneratedJoinCondition EQUI_CONDITION =
            generatedCondition(
                    "StreamingJoinOperatorTests$EquiCondition",
                    "return in1.getLong(0) == in2.getLong(0);");

    private static final GeneratedJoinCondition EQUI_JOIN_KEY_CONDITION =
            generatedCondition(
                    "StreamingJoinOperatorTests$EquiJoinKeyCondition",
                    "return in1.getLong(1) == in2.getLong(1);");

    private static final GeneratedJoinCondition NON_EQUI_CONDITION =
            generatedCondition(
                    "StreamingJoinOperatorTests$NonEquiCondition",
                    "return in1.getLong(0) == in2.getLong(0)"
                            + " && in1.getLong(1) > in2.getLong(1);");

    private static final GeneratedJoinCondition NON_EQUI_JOIN_KEY_CONDITION =
            generatedCondition(
                    "StreamingJoinOperatorTests$NonEquiJoinKeyCondition",
                    "return in1.getLong(1) == in2.getLong(1)"
                            + " && in1.getLong(2) > in2.getLong(2);");

    @Test
    void testInnerJoinEmitsMatchesForEachInputAndRetractsThem() throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(false, false, EQUI_CONDITION, false, null, null)) {
            harness.processElement1(row(RowKind.INSERT, 1L, 10L), 0L);
            assertOutput(harness);

            harness.processElement2(row(RowKind.INSERT, 1L, 20L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 1L, 20L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.INSERT, 1L, 30L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 1L, 30L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.DELETE, 1L, 20L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 1L, 20L));
            clearOutput(harness);

            harness.processElement1(row(RowKind.DELETE, 1L, 10L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 1L, 30L));
        }
    }

    @Test
    void testInnerJoinForwardsInputRowKindForNonOuterInput() throws Exception {
        RuntimeChangelogMode allChanges = allChanges();
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(false, false, EQUI_CONDITION, false, allChanges, allChanges)) {
            harness.processElement1(row(RowKind.INSERT, 1L, 10L), 0L);

            harness.processElement2(row(RowKind.UPDATE_AFTER, 1L, 20L), 0L);
            assertOutput(harness, expected(RowKind.UPDATE_AFTER, 1L, 10L, 1L, 20L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.UPDATE_BEFORE, 1L, 20L), 0L);
            assertOutput(harness, expected(RowKind.UPDATE_BEFORE, 1L, 10L, 1L, 20L));
        }
    }

    @Test
    void testLeftOuterJoinMaintainsNullPaddingAcrossMatchLifecycle() throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(true, false, EQUI_CONDITION, false, null, null)) {
            harness.processElement1(row(RowKind.INSERT, 1L, 10L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, null, null));
            clearOutput(harness);

            harness.processElement2(row(RowKind.INSERT, 1L, 20L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 10L, null, null),
                    expected(RowKind.INSERT, 1L, 10L, 1L, 20L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.INSERT, 1L, 30L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 1L, 30L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.DELETE, 1L, 20L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 1L, 20L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.DELETE, 1L, 30L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 10L, 1L, 30L),
                    expected(RowKind.INSERT, 1L, 10L, null, null));
            clearOutput(harness);

            harness.processElement1(row(RowKind.DELETE, 1L, 10L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, null, null));
        }
    }

    @Test
    void testRightOuterJoinMaintainsNullPaddingAcrossMultipleMatches() throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(false, true, EQUI_CONDITION, false, null, null)) {
            harness.processElement2(row(RowKind.INSERT, 2L, 20L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, null, null, 2L, 20L));
            clearOutput(harness);

            harness.processElement1(row(RowKind.INSERT, 1L, 10L), 0L);
            assertOutput(harness);
            harness.processElement1(row(RowKind.INSERT, 1L, 12L), 0L);
            assertOutput(harness);

            harness.processElement2(row(RowKind.INSERT, 1L, 30L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.INSERT, 1L, 10L, 1L, 30L),
                    expected(RowKind.INSERT, 1L, 12L, 1L, 30L));
            clearOutput(harness);

            harness.processElement1(row(RowKind.DELETE, 1L, 10L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 1L, 30L));
            clearOutput(harness);

            harness.processElement1(row(RowKind.DELETE, 1L, 12L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 12L, 1L, 30L),
                    expected(RowKind.INSERT, null, null, 1L, 30L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.DELETE, 1L, 30L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, null, null, 1L, 30L));
        }
    }

    @Test
    void testFullOuterJoinTracksAssociationCountsAcrossMultipleMatches() throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(true, true, EQUI_CONDITION, false, null, null)) {
            harness.processElement2(row(RowKind.INSERT, 2L, 20L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, null, null, 2L, 20L));
            clearOutput(harness);

            harness.processElement1(row(RowKind.INSERT, 1L, 10L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, null, null));
            clearOutput(harness);

            harness.processElement2(row(RowKind.INSERT, 1L, 20L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 10L, null, null),
                    expected(RowKind.INSERT, 1L, 10L, 1L, 20L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.INSERT, 1L, 30L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 1L, 30L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.DELETE, 1L, 20L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 1L, 20L));
            clearOutput(harness);

            harness.processElement2(row(RowKind.DELETE, 1L, 30L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 10L, 1L, 30L),
                    expected(RowKind.INSERT, 1L, 10L, null, null));
            clearOutput(harness);

            harness.processElement1(row(RowKind.DELETE, 1L, 10L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, null, null));
        }
    }

    @Test
    void testUpsertReplacementInFullOuterJoinDoesNotDoubleCountAssociation() throws Exception {
        RuntimeChangelogMode upsert = upsertMode(false);
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(
                        THREE_LONG_TYPE,
                        THREE_LONG_JOIN_TYPE,
                        1,
                        EQUI_JOIN_KEY_CONDITION,
                        uniqueKeyOnFirstField(),
                        JoinInputSideSpec.withoutUniqueKey(),
                        true,
                        true,
                        upsert,
                        upsert,
                        false)) {
            harness.processElement2(row3(RowKind.INSERT, 0L, 10L, 50L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, null, null, null, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.INSERT, 1L, 10L, 100L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, null, null, null, 0L, 10L, 50L),
                    expected(RowKind.INSERT, 1L, 10L, 100L, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.UPDATE_AFTER, 1L, 10L, 101L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 101L, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.DELETE, 1L, 10L, 101L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 10L, 101L, 0L, 10L, 50L),
                    expected(RowKind.INSERT, null, null, null, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement2(row3(RowKind.DELETE, 0L, 10L, 50L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, null, null, null, 0L, 10L, 50L));
        }
    }

    @Test
    void testUpsertWithUniqueKeyInJoinKeyKeepsOuterAssociationCountStable() throws Exception {
        RuntimeChangelogMode upsert = upsertMode(false);
        JoinInputSideSpec leftSpec =
                JoinInputSideSpec.withUniqueKeyContainedByJoinKey(
                        ONE_LONG_TYPE, row -> GenericRowData.of(row.getLong(0)));
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(
                        TWO_LONG_TYPE,
                        TWO_LONG_JOIN_TYPE,
                        0,
                        EQUI_CONDITION,
                        leftSpec,
                        JoinInputSideSpec.withoutUniqueKey(),
                        true,
                        true,
                        upsert,
                        allChanges(),
                        false)) {
            harness.processElement2(row(RowKind.INSERT, 10L, 50L), 0L);
            harness.processElement1(row(RowKind.INSERT, 10L, 100L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.INSERT, null, null, 10L, 50L),
                    expected(RowKind.DELETE, null, null, 10L, 50L),
                    expected(RowKind.INSERT, 10L, 100L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row(RowKind.UPDATE_AFTER, 10L, 101L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 10L, 101L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row(RowKind.DELETE, 10L, 101L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 10L, 101L, 10L, 50L),
                    expected(RowKind.INSERT, null, null, 10L, 50L));
        }
    }

    @Test
    void testKeyOnlyDeleteUsesStoredRecordForNonEquiCondition() throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(
                        THREE_LONG_TYPE,
                        THREE_LONG_JOIN_TYPE,
                        1,
                        NON_EQUI_JOIN_KEY_CONDITION,
                        uniqueKeyOnFirstField(),
                        JoinInputSideSpec.withoutUniqueKey(),
                        false,
                        false,
                        upsertMode(true),
                        allChanges(),
                        true)) {
            harness.processElement2(row3(RowKind.INSERT, 0L, 10L, 50L), 0L);
            assertOutput(harness);

            harness.processElement1(row3(RowKind.INSERT, 1L, 10L, 100L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 100L, 0L, 10L, 50L));
            clearOutput(harness);

            // The delete contains the unique key and join key, but not the non-equi field.
            harness.processElement1(row3(RowKind.DELETE, 1L, 10L, null), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 100L, 0L, 10L, 50L));
        }
    }

    @Test
    void testUpsertWithNonEquiConditionRetractsMatchesLostByReplacement() throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(
                        THREE_LONG_TYPE,
                        THREE_LONG_JOIN_TYPE,
                        1,
                        NON_EQUI_JOIN_KEY_CONDITION,
                        uniqueKeyOnFirstField(),
                        JoinInputSideSpec.withoutUniqueKey(),
                        false,
                        false,
                        upsertMode(false),
                        allChanges(),
                        true)) {
            harness.processElement2(row3(RowKind.INSERT, 0L, 10L, 50L), 0L);
            harness.processElement1(row3(RowKind.INSERT, 1L, 10L, 100L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 100L, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.UPDATE_AFTER, 1L, 10L, 20L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 100L, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement2(row3(RowKind.INSERT, 2L, 10L, 10L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 20L, 2L, 10L, 10L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.DELETE, 1L, 10L, 20L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 20L, 2L, 10L, 10L));
        }
    }

    @Test
    void testNonEquiUpsertInFullOuterJoinRetractsLostMatchAndRestoresNullPadding()
            throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(
                        THREE_LONG_TYPE,
                        THREE_LONG_JOIN_TYPE,
                        1,
                        NON_EQUI_JOIN_KEY_CONDITION,
                        uniqueKeyOnFirstField(),
                        JoinInputSideSpec.withoutUniqueKey(),
                        true,
                        true,
                        upsertMode(false),
                        allChanges(),
                        true)) {
            harness.processElement2(row3(RowKind.INSERT, 0L, 10L, 50L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, null, null, null, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.INSERT, 1L, 10L, 100L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, null, null, null, 0L, 10L, 50L),
                    expected(RowKind.INSERT, 1L, 10L, 100L, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.UPDATE_AFTER, 1L, 10L, 20L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 10L, 100L, 0L, 10L, 50L),
                    expected(RowKind.INSERT, null, null, null, 0L, 10L, 50L),
                    expected(RowKind.INSERT, 1L, 10L, 20L, null, null, null));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.DELETE, 1L, 10L, 20L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, 1L, 10L, 20L, null, null, null));
            clearOutput(harness);

            harness.processElement2(row3(RowKind.DELETE, 0L, 10L, 50L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, null, null, null, 0L, 10L, 50L));
        }
    }

    @Test
    void testNonEquiUpsertWithBothVersionsMatchingKeepsAssociationCountStable()
            throws Exception {
        try (KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                createHarness(
                        THREE_LONG_TYPE,
                        THREE_LONG_JOIN_TYPE,
                        1,
                        NON_EQUI_JOIN_KEY_CONDITION,
                        uniqueKeyOnFirstField(),
                        JoinInputSideSpec.withoutUniqueKey(),
                        true,
                        true,
                        upsertMode(false),
                        allChanges(),
                        true)) {
            harness.processElement2(row3(RowKind.INSERT, 0L, 10L, 50L), 0L);
            clearOutput(harness);

            harness.processElement1(row3(RowKind.INSERT, 1L, 10L, 100L), 0L);
            clearOutput(harness);

            harness.processElement1(row3(RowKind.UPDATE_AFTER, 1L, 10L, 60L), 0L);
            assertOutput(harness, expected(RowKind.INSERT, 1L, 10L, 60L, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement1(row3(RowKind.DELETE, 1L, 10L, 60L), 0L);
            assertOutput(
                    harness,
                    expected(RowKind.DELETE, 1L, 10L, 60L, 0L, 10L, 50L),
                    expected(RowKind.INSERT, null, null, null, 0L, 10L, 50L));
            clearOutput(harness);

            harness.processElement2(row3(RowKind.DELETE, 0L, 10L, 50L), 0L);
            assertOutput(harness, expected(RowKind.DELETE, null, null, null, 0L, 10L, 50L));
        }
    }

    // ------------------------------------------------------------------------------------------

    private static KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData>
            createHarness(
                    boolean leftIsOuter,
                    boolean rightIsOuter,
                    GeneratedJoinCondition condition,
                    boolean hasNonEquiCondition,
                    RuntimeChangelogMode leftChangelogMode,
                    RuntimeChangelogMode rightChangelogMode)
                    throws Exception {
        return createHarness(
                TWO_LONG_TYPE,
                TWO_LONG_JOIN_TYPE,
                0,
                condition,
                JoinInputSideSpec.withoutUniqueKey(),
                JoinInputSideSpec.withoutUniqueKey(),
                leftIsOuter,
                rightIsOuter,
                leftChangelogMode,
                rightChangelogMode,
                hasNonEquiCondition);
    }

    private static KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData>
            createHarness(
                    InternalTypeInfo<RowData> inputType,
                    InternalTypeInfo<RowData> outputType,
                    int joinKeyField,
                    GeneratedJoinCondition condition,
                    JoinInputSideSpec leftInputSideSpec,
                    JoinInputSideSpec rightInputSideSpec,
                    boolean leftIsOuter,
                    boolean rightIsOuter,
                    RuntimeChangelogMode leftChangelogMode,
                    RuntimeChangelogMode rightChangelogMode,
                    boolean hasNonEquiCondition)
                    throws Exception {
        StreamingJoinOperator operator =
                new StreamingJoinOperator(
                        inputType,
                        inputType,
                        condition,
                        leftInputSideSpec,
                        rightInputSideSpec,
                        leftIsOuter,
                        rightIsOuter,
                        leftChangelogMode,
                        rightChangelogMode,
                        hasNonEquiCondition,
                        new boolean[] {false, false},
                        0L,
                        0L);
        KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness =
                new KeyedTwoInputStreamOperatorTestHarness<>(
                        operator,
                        row -> row.getLong(joinKeyField),
                        row -> row.getLong(joinKeyField),
                        Types.LONG);
        harness.setup(outputType.toRowSerializer());
        harness.open();
        return harness;
    }

    private static JoinInputSideSpec uniqueKeyOnFirstField() {
        return JoinInputSideSpec.withUniqueKey(
                ONE_LONG_TYPE, row -> GenericRowData.of(row.getLong(0)));
    }

    private static RuntimeChangelogMode upsertMode(boolean keyOnlyDeletes) {
        return changelogMode(keyOnlyDeletes, RowKind.INSERT, RowKind.UPDATE_AFTER, RowKind.DELETE);
    }

    private static RuntimeChangelogMode allChanges() {
        return changelogMode(
                false,
                RowKind.INSERT,
                RowKind.UPDATE_BEFORE,
                RowKind.UPDATE_AFTER,
                RowKind.DELETE);
    }

    private static RuntimeChangelogMode changelogMode(
            boolean keyOnlyDeletes, RowKind... rowKinds) {
        ChangelogMode.Builder builder = ChangelogMode.newBuilder().keyOnlyDeletes(keyOnlyDeletes);
        for (RowKind rowKind : rowKinds) {
            builder.addContainedKind(rowKind);
        }
        return RuntimeChangelogMode.serialize(builder.build());
    }

    private static GenericRowData row(RowKind kind, Long key, Long value) {
        return GenericRowData.ofKind(kind, key, value);
    }

    private static GenericRowData row3(
            RowKind kind, Long uniqueKey, Long joinKey, Long value) {
        return GenericRowData.ofKind(kind, uniqueKey, joinKey, value);
    }

    private static ExpectedRow expected(RowKind kind, Long... values) {
        return new ExpectedRow(kind, values);
    }

    private static void clearOutput(
            KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness) {
        harness.getOutput().clear();
    }

    private static void assertOutput(
            KeyedTwoInputStreamOperatorTestHarness<Long, RowData, RowData, RowData> harness,
            ExpectedRow... expectedRows) {
        List<StreamRecord<RowData>> records = new ArrayList<>(harness.getRecordOutput());
        assertEquals(expectedRows.length, records.size());
        for (int i = 0; i < expectedRows.length; i++) {
            ExpectedRow expected = expectedRows[i];
            RowData actual = records.get(i).getValue();
            assertEquals(expected.kind, actual.getRowKind(), "row kind at output " + i);
            assertEquals(expected.values.length, actual.getArity(), "arity at output " + i);
            for (int field = 0; field < expected.values.length; field++) {
                Long expectedValue = expected.values[field];
                if (expectedValue == null) {
                    assertTrue(actual.isNullAt(field), "field " + field + " should be null");
                } else {
                    assertEquals(
                            expectedValue.longValue(),
                            actual.getLong(field),
                            "field " + field + " at output " + i);
                }
            }
        }
    }

    private static GeneratedJoinCondition generatedCondition(String className, String body) {
        String code =
                "public class "
                        + className
                        + " extends org.apache.flink.api.common.functions.AbstractRichFunction"
                        + " implements org.apache.flink.table.runtime.generated.JoinCondition {\n"
                        + "  public "
                        + className
                        + "(Object[] references) throws Exception {}\n"
                        + "  @Override\n"
                        + "  public boolean apply(org.apache.flink.table.data.RowData in1,"
                        + " org.apache.flink.table.data.RowData in2) throws Exception {\n"
                        + "    "
                        + body
                        + "\n"
                        + "  }\n"
                        + "}\n";
        return new GeneratedJoinCondition(className, code, new Object[0]);
    }

    private static final class ExpectedRow {
        private final RowKind kind;
        private final Long[] values;

        private ExpectedRow(RowKind kind, Long... values) {
            this.kind = kind;
            this.values = values;
        }
    }
}

