    @Test
    void testGetTaskManagerShellCommandIncludesAllConfiguredValues() {
        Configuration configuration = new Configuration();
        configuration.set(
                YarnConfigOptions.YARN_CONTAINER_START_COMMAND_TEMPLATE,
                "%java%|%jvmmem%|%jvmopts%|%logging%|%class%|%args%|%redirects%");
        configuration.set(CoreOptions.FLINK_DEFAULT_JVM_OPTIONS, "-Ddefault=true");
        configuration.set(CoreOptions.FLINK_JVM_OPTIONS, "-Dall=true");
        configuration.set(CoreOptions.FLINK_DEFAULT_TM_JVM_OPTIONS, "-DtmDefault=true");
        configuration.set(CoreOptions.FLINK_TM_JVM_OPTIONS, "-Dtm=true");
        ContaineredTaskManagerParameters tmParameters =
                new ContaineredTaskManagerParameters(createProcessSpec(), new HashMap<>());

        String command =
                Utils.getTaskManagerShellCommand(
                        configuration,
                        tmParameters,
                        "/config",
                        "/logs",
                        true,
                        true,
                        true,
                        TestTaskManagerMain.class,
                        "--job-id 123");

        assertTrue(command.startsWith("$JAVA_HOME/bin/java|"));
        assertTrue(command.contains("-Xmx335544320 -Xms335544320"));
        assertTrue(command.contains("-XX:MaxMetaspaceSize=67108864"));
        assertTrue(
                command.contains(
                        "-Ddefault=true -Dall=true -DtmDefault=true -Dtm=true "
                                + Utils.IGNORE_UNRECOGNIZED_VM_OPTIONS
                                + " -Djava.security.krb5.conf=krb5.conf"));
        assertTrue(
                command.contains(
                        "|-Dlog.file=/logs/taskmanager.log "
                                + "-Dlogback.configurationFile=file:/config/logback.xml "
                                + "-Dlog4j.configuration=file:/config/log4j.properties "
                                + "-Dlog4j.configurationFile=file:/config/log4j.properties|"));
        assertTrue(command.contains("|" + TestTaskManagerMain.class.getName() + "|"));
        assertTrue(command.contains("--configDir /config --job-id 123"));
        assertTrue(command.endsWith("1> /logs/taskmanager.out 2> /logs/taskmanager.err"));
        assertFalse(command.contains("%"));
    }

