    @Test
    void testCreateTaskExecutorContextWithMinimalConfiguration() throws Exception {
        java.nio.file.Path workingDirectory = Files.createDirectory(tempDir.resolve("working"));
        YarnLocalResourceDescriptor flinkDist =
                descriptor("flink-dist.jar", "hdfs://localhost:8020/flink/flink-dist.jar");
        Configuration flinkConfiguration = new Configuration();
        flinkConfiguration.set(
                YarnConfigOptions.YARN_CONTAINER_START_COMMAND_TEMPLATE, "%java%|%class%|%args%");
        YarnConfiguration yarnConfiguration = new YarnConfiguration();
        yarnConfiguration.setStrings(YarnConfiguration.YARN_APPLICATION_CLASSPATH, "yarn/app.jar");
        YarnResourceManagerDriverConfiguration driverConfiguration =
                driverConfiguration(
                        workingDirectory.toString(),
                        "flink/classpath",
                        flinkDist.toString(),
                        "",
                        null,
                        null,
                        null,
                        null,
                        null);
        HashMap<String, String> taskManagerEnv = new HashMap<>();
        taskManagerEnv.put("CUSTOM_ENV", "custom-value");

        ContainerLaunchContext context =
                Utils.createTaskExecutorContext(
                        flinkConfiguration,
                        yarnConfiguration,
                        driverConfiguration,
                        new ContaineredTaskManagerParameters(createProcessSpec(), taskManagerEnv),
                        "--dynamic=value",
                        workingDirectory.toString(),
                        TestTaskManagerMain.class,
                        org.slf4j.LoggerFactory.getLogger(UtilsTests.class));

        assertEquals(1, context.getCommands().size());
        assertTrue(context.getCommands().get(0).contains(TestTaskManagerMain.class.getName()));
        assertTrue(context.getCommands().get(0).contains("--dynamic=value"));
        assertTrue(context.getCommands().get(0).contains("--configDir ."));
        assertEquals(1, context.getLocalResources().size());
        assertEquals(
                LocalResourceType.ARCHIVE,
                context.getLocalResources().get("flink-dist.jar").getType());
        assertEquals(
                LocalResourceVisibility.APPLICATION,
                context.getLocalResources().get("flink-dist.jar").getVisibility());
        assertEquals("custom-value", context.getEnvironment().get("CUSTOM_ENV"));
        assertEquals(
                "flink/classpath",
                context.getEnvironment().get(YarnConfigKeys.ENV_FLINK_CLASSPATH));
        assertTrue(
                context.getEnvironment()
                        .get(ApplicationConstants.Environment.CLASSPATH.name())
                        .contains("yarn/app.jar"));
        assertTrue(
                context.getEnvironment()
                        .get(YarnConfigKeys.ENV_HADOOP_USER_NAME)
                        .equals(UserGroupInformation.getCurrentUser().getUserName()));
        assertFalse(context.getEnvironment().containsKey(YarnConfigKeys.REMOTE_KEYTAB_PATH));
        assertFalse(context.getEnvironment().containsKey(YarnConfigKeys.LOCAL_KEYTAB_PATH));
        assertFalse(context.getLocalResources().containsKey(Utils.KRB5_FILE_NAME));
        assertFalse(context.getLocalResources().containsKey(Utils.YARN_SITE_FILE_NAME));
        assertTrue(context.getApplicationACLs() == null || context.getApplicationACLs().isEmpty());
    }

    @Test
    void testCreateTaskExecutorContextWithSecurityResourcesAndAcls() throws Exception {
        java.nio.file.Path workingDirectory = Files.createDirectory(tempDir.resolve("secure"));
        Files.write(
                workingDirectory.resolve("logback.xml"),
                "logback".getBytes(StandardCharsets.UTF_8));
        Files.write(
                workingDirectory.resolve("log4j.properties"),
                "log4j".getBytes(StandardCharsets.UTF_8));
        java.nio.file.Path keytab = Files.createFile(tempDir.resolve("client.keytab"));
        java.nio.file.Path yarnSite = Files.createFile(tempDir.resolve("yarn-site.xml"));
        java.nio.file.Path krb5 = Files.createFile(tempDir.resolve("krb5.conf"));

        YarnLocalResourceDescriptor flinkDist =
                descriptor("flink-dist.jar", "hdfs://localhost:8020/flink/flink-dist.jar");
        YarnLocalResourceDescriptor extraResource =
                descriptor("extra.jar", "hdfs://localhost:8020/flink/extra.jar");
        Configuration flinkConfiguration = new Configuration();
        flinkConfiguration.set(
                YarnConfigOptions.YARN_CONTAINER_START_COMMAND_TEMPLATE,
                "%java%|%jvmopts%|%logging%|%class%|%args%");
        flinkConfiguration.set(YarnConfigOptions.APPLICATION_VIEW_ACLS, "viewer");
        flinkConfiguration.set(YarnConfigOptions.APPLICATION_MODIFY_ACLS, "modifier");
        YarnConfiguration yarnConfiguration = new YarnConfiguration();
        YarnResourceManagerDriverConfiguration driverConfiguration =
                driverConfiguration(
                        workingDirectory.toString(),
                        "flink/classpath",
                        flinkDist.toString(),
                        extraResource.toString(),
                        keytab.toString(),
                        "client.keytab",
                        "principal",
                        yarnSite.toString(),
                        krb5.toString());

        ContainerLaunchContext context =
                Utils.createTaskExecutorContext(
                        flinkConfiguration,
                        yarnConfiguration,
                        driverConfiguration,
                        new ContaineredTaskManagerParameters(createProcessSpec(), new HashMap<>()),
                        "",
                        workingDirectory.toString(),
                        TestTaskManagerMain.class,
                        org.slf4j.LoggerFactory.getLogger(UtilsTests.class));

        assertTrue(context.getLocalResources().containsKey("flink-dist.jar"));
        assertTrue(context.getLocalResources().containsKey("extra.jar"));
        assertTrue(context.getLocalResources().containsKey(Utils.KRB5_FILE_NAME));
        assertTrue(context.getLocalResources().containsKey(Utils.YARN_SITE_FILE_NAME));
        assertTrue(context.getLocalResources().containsKey("client.keytab"));
        assertEquals(
                krb5.toFile().length(),
                context.getLocalResources().get(Utils.KRB5_FILE_NAME).getSize());
        assertEquals(
                LocalResourceType.FILE,
                context.getLocalResources().get(Utils.KRB5_FILE_NAME).getType());
        assertEquals(
                LocalResourceVisibility.APPLICATION,
                context.getLocalResources().get(Utils.YARN_SITE_FILE_NAME).getVisibility());
        assertEquals(
                keytab.toString(), context.getEnvironment().get(YarnConfigKeys.REMOTE_KEYTAB_PATH));
