    private static YarnResourceManagerDriverConfiguration driverConfiguration(
            String workingDirectory,
            String flinkClasspath,
            String flinkDistJar,
            String clientShipFiles,
            String remoteKeytabPath,
            String localKeytabPath,
            String keytabPrincipal,
            String yarnSiteXmlPath,
            String krb5Path) {
        Map<String, String> environment = new HashMap<>();
        environment.put(YarnConfigKeys.FLINK_YARN_FILES, "files");
        environment.put(YarnConfigKeys.ENV_FLINK_CLASSPATH, flinkClasspath);
        environment.put(YarnConfigKeys.ENV_CLIENT_SHIP_FILES, clientShipFiles);
        environment.put(YarnConfigKeys.FLINK_DIST_JAR, flinkDistJar);
        environment.put(ApplicationConstants.Environment.PWD.key(), workingDirectory);
        if (remoteKeytabPath != null) {
            environment.put(YarnConfigKeys.REMOTE_KEYTAB_PATH, remoteKeytabPath);
        }
        if (localKeytabPath != null) {
            environment.put(YarnConfigKeys.LOCAL_KEYTAB_PATH, localKeytabPath);
        }
        if (keytabPrincipal != null) {
            environment.put(YarnConfigKeys.KEYTAB_PRINCIPAL, keytabPrincipal);
        }
        if (yarnSiteXmlPath != null) {
            environment.put(YarnConfigKeys.ENV_YARN_SITE_XML_PATH, yarnSiteXmlPath);
        }
        if (krb5Path != null) {
            environment.put(YarnConfigKeys.ENV_KRB5_PATH, krb5Path);
        }
        return new YarnResourceManagerDriverConfiguration(environment, "rpc", "web");
    }

    private static TaskExecutorProcessSpec createProcessSpec() {
        return new TaskExecutorProcessSpec(
                new CPUResource(2.0),
                MemorySize.ofMebiBytes(64),
                MemorySize.ofMebiBytes(16),
                MemorySize.ofMebiBytes(256),
                MemorySize.ofMebiBytes(32),
