        final FlinkYarnSessionCli cli = createCli();

        final Configuration configuration =
                cli.toConfiguration(
                        parse(cli, "-yt", shipDirectory.toString(), "-yt", shipFile.toString()));

        assertThat(configuration.get(YarnConfigOptions.SHIP_FILES))
                .containsExactly(shipDirectory.toString(), shipFile.toString());
    }

    @Test
    void testToConfigurationFailsForMissingShipFile() throws Exception {
        final String missingShipFile = temporaryFolder.resolve("does-not-exist").toString();
        final FlinkYarnSessionCli cli = createCli();

        assertThatThrownBy(() -> cli.toConfiguration(parse(cli, "-yt", missingShipFile)))
                .isInstanceOf(ConfigurationException.class)
                .hasMessageContaining("does not exist");
    }

