    @Test
    void testToConfigurationAppliesDynamicPropertiesFromCommandLine() throws Exception {
        final FlinkYarnSessionCli cli = createCli();

        final Configuration configuration =
                cli.toConfiguration(parse(cli, "-yD", "key1=value1", "-yD", "key2=value2"));

        assertThat(configuration.getString("key1", null)).isEqualTo("value1");
        assertThat(configuration.getString("key2", null)).isEqualTo("value2");
        assertThat(configuration.get(DeploymentOptions.TARGET))
                .isEqualTo(YarnSessionClusterExecutor.NAME);
    }

    @Test
    void testToConfigurationAppliesDynamicPropertiesFromYarnPropertiesFile() throws Exception {
        writeYarnPropertiesFile(
                properties(
                        "applicationID",
                        APPLICATION_ID,
                        "dynamicPropertiesString",
                        "key1=value1@@key2=value2"));
        final FlinkYarnSessionCli cli = createCli();

        final Configuration configuration = cli.toConfiguration(parse(cli));

        assertThat(configuration.get(YarnConfigOptions.APPLICATION_ID)).isEqualTo(APPLICATION_ID);
        assertThat(configuration.getString("key1", null)).isEqualTo("value1");
        assertThat(configuration.getString("key2", null)).isEqualTo("value2");
    }

    @Test
    void testToConfigurationIgnoresYarnPropertiesFileIfYarnOptionsAreGiven() throws Exception {
        writeYarnPropertiesFile(
                properties(
                        "applicationID", APPLICATION_ID, "dynamicPropertiesString", "key1=value1"));
        final FlinkYarnSessionCli cli = createCli();

        final Configuration configuration =
                cli.toConfiguration(parse(cli, "-ynm", "my-application"));

        assertThat(configuration.getOptional(YarnConfigOptions.APPLICATION_ID)).isNotPresent();
        assertThat(configuration.getString("key1", null)).isNull();
        assertThat(configuration.get(YarnConfigOptions.APPLICATION_NAME))
                .isEqualTo("my-application");
    }

    @Test
    void testToConfigurationIgnoresYarnPropertiesFileIfJobManagerAddressIsGiven() throws Exception {
        writeYarnPropertiesFile(properties("applicationID", APPLICATION_ID));
        final FlinkYarnSessionCli cli = createCli();

